(331806,36868,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... von zwei Leuten, weil zwei Leute ihre Arme hielten.'::text,'wurde unterstützt'::text,'unterstützte'::text,'unterstützend'::text,'Sie wurde unterstützt von zwei Leuten, weil zwei Leute ihre Arme hielten.'::text),
(331810,36868,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її ... двоє людей, бо двоє людей тримали її за руки.'::text,'підтримували'::text,'підтримувала'::text,'підтримуючи'::text,'Її підтримували двоє людей, бо двоє людей тримали її за руки.'::text),
(331809,36868,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... por dos personas, porque dos personas la sujetaban de los brazos.'::text,'fue ayudada'::text,'ayudó'::text,'ayudando'::text,'Ella fue ayudada por dos personas, porque dos personas la sujetaban de los brazos.'::text),
(331808,36868,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... par deux personnes, parce que deux personnes lui tenaient les bras.'::text,'a été aidée'::text,'a aidé'::text,'aidant'::text,'Elle a été aidée par deux personnes, parce que deux personnes lui tenaient les bras.'::text),
(331811,36868,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O iki kişi tarafından ..., çünkü iki kişi kollarından tutuyordu.'::text,'desteklendi'::text,'destekledi'::text,'destekleyerek'::text,'O iki kişi tarafından desteklendi, çünkü iki kişi kollarından tutuyordu.'::text),
(331812,36868,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Két ember ... őt, mert két ember fogta a karját.'::text,'támogatta'::text,'támogatott'::text,'támogatva'::text,'Két ember támogatta őt, mert két ember fogta a karját.'::text),
(331815,36869,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wie beobachtet, hält der Mann bereits ihren Arm, also ... er im Begriff sein, ihr zu helfen.'::text,'muss'::text,'könnte'::text,'kann nicht'::text,'Wie beobachtet, hält der Mann bereits ihren Arm, also muss er im Begriff sein, ihr zu helfen.'::text),
(331819,36869,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Як видно зі спостережень, чоловік уже тримає її за руку, тож він ... ось-ось їй допоможе.'::text,'напевно'::text,'можливо'::text,'точно не'::text,'Як видно зі спостережень, чоловік уже тримає її за руку, тож він напевно ось-ось їй допоможе.'::text),
(331818,36869,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Según lo observado, el hombre ya la sujeta del brazo, así que ... estar a punto de ayudarla.'::text,'debe de'::text,'podría'::text,'no puede'::text,'Según lo observado, el hombre ya la sujeta del brazo, así que debe de estar a punto de ayudarla.'::text),
(331817,36869,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''après l''observation, l''homme lui tient déjà le bras, donc il ... être sur le point de l''aider.'::text,'doit'::text,'pourrait'::text,'ne peut pas'::text,'D''après l''observation, l''homme lui tient déjà le bras, donc il doit être sur le point de l''aider.'::text),
(331820,36869,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gözlemlendiği üzere adam zaten kolunu tutuyor, yani ona yardım etmek üzere ...'::text,'olmalı'::text,'olabilir'::text,'olamaz'::text,'Gözlemlendiği üzere adam zaten kolunu tutuyor, yani ona yardım etmek üzere olmalı.'::text),
(331821,36869,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A megfigyelések szerint a férfi már fogja a karját, tehát ... segíteni készül neki.'::text,'biztosan'::text,'talán'::text,'biztosan nem'::text,'A megfigyelések szerint a férfi már fogja a karját, tehát biztosan segíteni készül neki.'::text),
(331824,36870,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Fremde, ... ihr an der Absperrung half, rettete ihr ganzes Rennen vor der totalen Katastrophe!'::text,'der'::text,'welches'::text,'dessen'::text,'Der Fremde, der ihr an der Absperrung half, rettete ihr ganzes Rennen vor der totalen Katastrophe!'::text),
(331828,36870,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Незнайомець, ... допоміг їй біля огорожі, врятував увесь її забіг від повної катастрофи!'::text,'який'::text,'що'::text,'чий'::text,'Незнайомець, який допоміг їй біля огорожі, врятував увесь її забіг від повної катастрофи!'::text),
(331827,36870,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El desconocido ... la ayudó en la valla salvó toda su carrera de un desastre total!'::text,'que'::text,'el cual'::text,'cuyo'::text,'¡El desconocido que la ayudó en la valla salvó toda su carrera de un desastre total!'::text),
(331826,36870,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''inconnu ... l''a aidée à la barrière a sauvé toute sa course d''un désastre total !'::text,'qui'::text,'lequel'::text,'dont'::text,'L''inconnu qui l''a aidée à la barrière a sauvé toute sa course d''un désastre total !'::text),
(331829,36870,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bariyerde ona yardım ... yabancı, tüm yarışını tam bir felaketten kurtardı!'::text,'eden'::text,'eden'::text,NULL::text,'Bariyerde ona yardım eden yabancı, tüm yarışını tam bir felaketten kurtardı!'::text),
(331830,36870,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az idegen, ... segített neki a korlátnál, megmentette az egész versenyét a teljes katasztrófától!'::text,'aki'::text,'amely'::text,'akinek'::text,'Az idegen, aki segített neki a korlátnál, megmentette az egész versenyét a teljes katasztrófától!'::text),
(331833,36871,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Schluchzend sagte sie, dass ihr die zwei Fremden durch den schlimmsten Moment ihres Lebens ...!'::text,'geholfen hatten'::text,'geholfen haben'::text,'helfen'::text,'Schluchzend sagte sie, dass ihr die zwei Fremden durch den schlimmsten Moment ihres Lebens geholfen hatten!'::text),
(331837,36871,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Схлипуючи, вона сказала, що двоє незнайомців ... їй пережити найгірший момент її життя!'::text,'допомогли'::text,'допомогли'::text,'допомагають'::text,'Схлипуючи, вона сказала, що двоє незнайомців допомогли їй пережити найгірший момент її життя!'::text),
(331836,36871,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Sollozando, dijo que los dos desconocidos la ... en el peor momento de su vida!'::text,'habían ayudado'::text,'han ayudado'::text,'ayudan'::text,'¡Sollozando, dijo que los dos desconocidos la habían ayudado en el peor momento de su vida!'::text),
(331835,36871,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En sanglotant, elle a dit que les deux inconnus l''... dans le pire moment de sa vie !'::text,'avaient aidée'::text,'ont aidée'::text,'aident'::text,'En sanglotant, elle a dit que les deux inconnus l''avaient aidée dans le pire moment de sa vie !'::text),
(331838,36871,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hıçkırarak, iki yabancının hayatının en kötü anında ona ... söyledi!'::text,'yardım ettiğini'::text,'yardım ettiğini'::text,'yardım ettiğini'::text,'Hıçkırarak, iki yabancının hayatının en kötü anında ona yardım ettiğini söyledi!'::text),
(331839,36871,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zokogva azt mondta, hogy a két idegen ... neki átvészelni élete legrosszabb pillanatát!'::text,'segített'::text,'segített'::text,'segít'::text,'Zokogva azt mondta, hogy a két idegen segített neki átvészelni élete legrosszabb pillanatát!'::text),
(331851,36873,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann mit der Cap bot an, der weinenden Läuferin an der Absperrung ...'::text,'zu helfen'::text,'helfend'::text,'helfen'::text,'Der Mann mit der Cap bot an, der weinenden Läuferin an der Absperrung zu helfen.'::text),
(331855,36873,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік у кепці запропонував ... бігунці, що плакала біля огорожі.'::text,'допомогти'::text,'допомагання'::text,'допомогти'::text,'Чоловік у кепці запропонував допомогти бігунці, що плакала біля огорожі.'::text),
(331854,36873,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre de la gorra se ofreció ... a la corredora que lloraba junto a la valla.'::text,'a ayudar'::text,'ayudando'::text,'ayudar'::text,'El hombre de la gorra se ofreció a ayudar a la corredora que lloraba junto a la valla.'::text),
(331853,36873,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme à la casquette a proposé ... la coureuse en larmes à la barrière.'::text,'d''aider'::text,'aidant'::text,'aider'::text,'L''homme à la casquette a proposé d''aider la coureuse en larmes à la barrière.'::text),
(331856,36873,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şapkalı adam bariyerdeki ağlayan koşucuya ... teklif etti.'::text,'yardım etmeyi'::text,'yardım etmeyi'::text,'yardım etmek'::text,'Şapkalı adam bariyerdeki ağlayan koşucuya yardım etmeyi teklif etti.'::text),
(331857,36873,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sapkás férfi felajánlotta, hogy ... a korlátnál síró futónak.'::text,'segít'::text,'segítés'::text,'segíteni'::text,'A sapkás férfi felajánlotta, hogy segít a korlátnál síró futónak.'::text),
(331860,36874,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann und die Frau haben ihr den ganzen Weg bis ins Ziel geholfen, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Der Mann und die Frau haben ihr den ganzen Weg bis ins Ziel geholfen, oder?'::text),
(331864,36874,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік і жінка допомагали їй аж до фінішу, ...?'::text,'правда'::text,'правда'::text,'правда'::text,'Чоловік і жінка допомагали їй аж до фінішу, правда?'::text),
(331863,36874,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre y la mujer la ayudaron hasta la meta, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'El hombre y la mujer la ayudaron hasta la meta, ¿verdad?'::text),
(331862,36874,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme et la femme l''ont aidée jusqu''à l''arrivée, ... ?'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'L''homme et la femme l''ont aidée jusqu''à l''arrivée, n''est-ce pas ?'::text),
(331865,36874,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adamla kadın ona bitişe kadar yardım etti, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Adamla kadın ona bitişe kadar yardım etti, değil mi?'::text),
(331866,36874,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi és a nő végig segített neki a célig, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'A férfi és a nő végig segített neki a célig, ugye?'::text),
(331869,36875,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann mit der Cap hat ihr geholfen, und ... die Frau im Triathlonanzug. Echt ein Solo-Lauf.'::text,'so auch'::text,'so auch'::text,'so auch'::text,'Der Mann mit der Cap hat ihr geholfen, und so auch die Frau im Triathlonanzug. Echt ein Solo-Lauf.'::text),
(331873,36875,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік у кепці допоміг їй, і ... жінка в костюмі для тріатлону. Справжній сольний забіг.'::text,'так само'::text,'так само'::text,'так само'::text,'Чоловік у кепці допоміг їй, і так само жінка в костюмі для тріатлону. Справжній сольний забіг.'::text),
(331872,36875,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre de la gorra la ayudó, y ... la mujer del traje de triatlón. Toda una carrera en solitario.'::text,'también'::text,'también'::text,'también'::text,'El hombre de la gorra la ayudó, y también la mujer del traje de triatlón. Toda una carrera en solitario.'::text),
(331871,36875,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme à la casquette l''a aidée, ... la femme en combinaison de triathlon. Vraiment une course en solo.'::text,'tout comme'::text,'tout comme'::text,'tout comme'::text,'L''homme à la casquette l''a aidée, tout comme la femme en combinaison de triathlon. Vraiment une course en solo.'::text),
(331874,36875,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şapkalı adam ona yardım etti, ... triatlon kıyafetli kadın da. Tam bir solo koşu.'::text,'keza'::text,'keza'::text,'keza'::text,'Şapkalı adam ona yardım etti, keza triatlon kıyafetli kadın da. Tam bir solo koşu.'::text),
(331875,36875,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sapkás férfi segített neki, és ... a triatlonruhás nő. Igazi szólófutás.'::text,'ugyanígy'::text,'ugyanígy'::text,'ugyanígy'::text,'A sapkás férfi segített neki, és ugyanígy a triatlonruhás nő. Igazi szólófutás.'::text),
(331878,36876,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, die zwei ... sie schon so 300 Meter lang, als sie endlich aufhörte zu weinen, echt jetzt.'::text,'stützten'::text,'stützen'::text,'stützten'::text,'Digga, die zwei stützten sie schon so 300 Meter lang, als sie endlich aufhörte zu weinen, echt jetzt.'::text),
(331882,36876,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ті двоє ... її вже десь 300 метрів, коли вона нарешті перестала плакати, реально.'::text,'підтримували'::text,'підтримують'::text,'підтримували'::text,'Бро, ті двоє підтримували її вже десь 300 метрів, коли вона нарешті перестала плакати, реально.'::text),
(331881,36876,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, esos dos ... como 300 metros cuando por fin dejó de llorar, en serio.'::text,'la llevaban ayudando'::text,'la llevan ayudando'::text,'la estaban ayudando'::text,'Bro, esos dos la llevaban ayudando como 300 metros cuando por fin dejó de llorar, en serio.'::text),
(331880,36876,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, ces deux-là l''... depuis genre 300 mètres quand elle a enfin arrêté de pleurer, sérieux.'::text,'aidaient'::text,'aident'::text,'aidaient'::text,'Frère, ces deux-là l''aidaient depuis genre 300 mètres quand elle a enfin arrêté de pleurer, sérieux.'::text),
(331883,36876,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o ikisi ona bir 300 metredir ... ki sonunda ağlamayı bıraktı, cidden.'::text,'yardım ediyordu'::text,'yardım ediyor'::text,'yardım ediyordu'::text,'Kanka, o ikisi ona bir 300 metredir yardım ediyordu ki sonunda ağlamayı bıraktı, cidden.'::text),
(331884,36876,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, azok ketten már vagy 300 méter óta ... neki, amikor végre abbahagyta a sírást, komolyan.'::text,'segítettek'::text,'segítenek'::text,'segítettek'::text,'Tesó, azok ketten már vagy 300 méter óta segítettek neki, amikor végre abbahagyta a sírást, komolyan.'::text),
(331887,36877,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, bis zum Ende dieses Rennens werden die zwei so drei Läufern ..., ehrlich.'::text,'geholfen haben'::text,'helfen'::text,'am Helfen sein'::text,'Yo, bis zum Ende dieses Rennens werden die zwei so drei Läufern geholfen haben, ehrlich.'::text),
(331891,36877,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, до кінця цього забігу ті двоє ... десь трьом бігунам, без брехні.'::text,'допоможуть'::text,'допоможуть'::text,'допомагатимуть'::text,'Йо, до кінця цього забігу ті двоє допоможуть десь трьом бігунам, без брехні.'::text),
(331890,36877,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, para el final de esta carrera, esos dos ... a como tres corredores, en serio.'::text,'habrán ayudado'::text,'ayudarán'::text,'estarán ayudando'::text,'Oye, para el final de esta carrera, esos dos habrán ayudado a como tres corredores, en serio.'::text),
(331889,36877,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, d''ici la fin de la course, ces deux-là ... genre trois coureurs, sans mentir.'::text,'auront aidé'::text,'aideront'::text,'seront en train d''aider'::text,'Yo, d''ici la fin de la course, ces deux-là auront aidé genre trois coureurs, sans mentir.'::text),
(331892,36877,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu yarışın sonuna kadar o ikisi bir üç koşucuya ..., yalan yok.'::text,'yardım etmiş olacak'::text,'yardım edecek'::text,'yardım ediyor olacak'::text,'Kanka, bu yarışın sonuna kadar o ikisi bir üç koşucuya yardım etmiş olacak, yalan yok.'::text),
(331893,36877,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, a verseny végére azok ketten vagy három futónak ..., komolyan.'::text,'segítettek majd'::text,'segítenek'::text,'segíteni fognak'::text,'Figyu, a verseny végére azok ketten vagy három futónak segítettek majd, komolyan.'::text),
(402303,44701,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er senkt seine Waffe, also ... das Spiel für ihn vorbei sein! Aus!'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Er senkt seine Waffe, also muss das Spiel für ihn vorbei sein! Aus!'::text),
(402307,44701,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він опускає зброю, тож гра для нього ... скінчена! Кінець!'::text,'напевно'::text,'точно не'::text,'мала б бути'::text,'Він опускає зброю, тож гра для нього напевно скінчена! Кінець!'::text),
(402306,44701,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Baja su arma, así que el juego ... haber terminado para él! ¡Se acabó!'::text,'debe de'::text,'no puede'::text,'debería'::text,'¡Baja su arma, así que el juego debe de haber terminado para él! ¡Se acabó!'::text),
(402305,44701,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il baisse son arme, donc la partie ... être finie pour lui ! C''est la fin !'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'Il baisse son arme, donc la partie doit être finie pour lui ! C''est la fin !'::text),
(402308,44701,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Silahını indiriyor, yani oyun onun için bitmiş ...! Son!'::text,'olmalı'::text,'olamaz'::text,'olmalı'::text,'Silahını indiriyor, yani oyun onun için bitmiş olmalı! Son!'::text),
(402309,44701,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Leengedi a fegyverét, szóval számára ... vége a játéknak! Ennyi volt!'::text,'biztosan'::text,'nem lehet, hogy'::text,'elvileg'::text,'Leengedi a fegyverét, szóval számára biztosan vége a játéknak! Ennyi volt!'::text),
(402312,44702,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Waffe, ... er am meisten vertraute, ist jetzt komplett leer!'::text,'der'::text,'die'::text,'wo'::text,'Die Waffe, der er am meisten vertraute, ist jetzt komplett leer!'::text),
(402316,44702,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зброя, ... він довіряв найбільше, тепер зовсім порожня!'::text,'якій'::text,'який'::text,'де'::text,'Зброя, якій він довіряв найбільше, тепер зовсім порожня!'::text),
(402315,44702,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El arma en ... más confiaba ahora está totalmente vacía!'::text,'la que'::text,'quien'::text,'donde'::text,'¡El arma en la que más confiaba ahora está totalmente vacía!'::text),
(402314,44702,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''arme ... il faisait le plus confiance est maintenant complètement vide !'::text,'à laquelle'::text,'à qui'::text,'où'::text,'L''arme à laquelle il faisait le plus confiance est maintenant complètement vide !'::text),
(402317,44702,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En çok ... silahı artık tamamen boş!'::text,'güvendiği'::text,'güvendiği'::text,'güvendiği'::text,'En çok güvendiği silahı artık tamamen boş!'::text),
(402318,44702,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fegyver, ... a legjobban megbízott, most teljesen üres!'::text,'amelyben'::text,'akiben'::text,'ahol'::text,'A fegyver, amelyben a legjobban megbízott, most teljesen üres!'::text),
(402321,44703,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er sagte, dass seiner Waffe die Farbe ...'::text,'ausgegangen war'::text,'ausgegangen ist'::text,'ausgeht'::text,'Er sagte, dass seiner Waffe die Farbe ausgegangen war.'::text),
(402325,44703,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він сказав, що в його зброї ... фарба.'::text,'закінчилася'::text,'закінчилася'::text,'закінчується'::text,'Він сказав, що в його зброї закінчилася фарба.'::text),
(402324,44703,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijo que a su arma se le ... la pintura.'::text,'había acabado'::text,'ha acabado'::text,'acaba'::text,'Dijo que a su arma se le había acabado la pintura.'::text),
(402323,44703,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a dit que son arme ... sa peinture.'::text,'avait épuisé'::text,'a épuisé'::text,'épuise'::text,'Il a dit que son arme avait épuisé sa peinture.'::text),
(402326,44703,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Silahının boyasının ... söyledi.'::text,'bittiğini'::text,'bittiğini'::text,'bittiğini'::text,'Silahının boyasının bittiğini söyledi.'::text),
(402327,44703,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta, hogy a fegyveréből ... a festék.'::text,'kifogyott'::text,'kifogyott'::text,'kifogy'::text,'Azt mondta, hogy a fegyveréből kifogyott a festék.'::text),
(402330,44704,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seine alte Waffe ... viel schwerer als diese.'::text,'war früher'::text,'war früher'::text,'war es gewohnt'::text,'Seine alte Waffe war früher viel schwerer als diese.'::text),
(402334,44704,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його стара зброя ... набагато важчою за цю.'::text,'колись була'::text,'колись була'::text,'звикла бути'::text,'Його стара зброя колись була набагато важчою за цю.'::text),
(402333,44704,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su antigua arma ... mucho más pesada que esta.'::text,'solía ser'::text,'solía ser'::text,'estaba acostumbrada a ser'::text,'Su antigua arma solía ser mucho más pesada que esta.'::text),
(402332,44704,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son ancienne arme ... beaucoup plus lourde que celle-ci.'::text,'était'::text,'était'::text,'avait l''habitude d''être'::text,'Son ancienne arme était beaucoup plus lourde que celle-ci.'::text),
(402335,44704,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eski silahı bundan çok daha ağır ...'::text,'olurdu'::text,'olurdu'::text,'olmaya alışkındı'::text,'Eski silahı bundan çok daha ağır olurdu.'::text),
(402336,44704,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A régi fegyvere ... sokkal nehezebb volt, mint ez.'::text,'régen'::text,'régen'::text,'szokás szerint'::text,'A régi fegyvere régen sokkal nehezebb volt, mint ez.'::text),
(402339,44705,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er beschließt, seine Waffe ... und die Hände zu heben.'::text,'zu senken'::text,'senkend'::text,'senken'::text,'Er beschließt, seine Waffe zu senken und die Hände zu heben.'::text),
(402343,44705,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він вирішує ... зброю і підняти руки.'::text,'опустити'::text,'опускаючи'::text,'опустити'::text,'Він вирішує опустити зброю і підняти руки.'::text),
(402342,44705,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Decide ... su arma y levantar las manos.'::text,'bajar'::text,'bajando'::text,'bajar'::text,'Decide bajar su arma y levantar las manos.'::text),
(402341,44705,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il décide ... son arme et de lever les mains.'::text,'de baisser'::text,'baissant'::text,'baisser'::text,'Il décide de baisser son arme et de lever les mains.'::text),
(402344,44705,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Silahını ... ve ellerini kaldırmaya karar veriyor.'::text,'indirmeye'::text,'indirmeyi'::text,'indirmek'::text,'Silahını indirmeye ve ellerini kaldırmaya karar veriyor.'::text),
(402345,44705,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy dönt, hogy ... a fegyverét, és felteszi a kezét.'::text,'leengedi'::text,'leengedve'::text,'leenged'::text,'Úgy dönt, hogy leengedi a fegyverét, és felteszi a kezét.'::text),
(402348,44706,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, der Waffe ist irgendwie die Farbe ausgegangen, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Digga, der Waffe ist irgendwie die Farbe ausgegangen, oder?'::text),
(402352,44706,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, у тієї зброї ніби закінчилася фарба, ...?'::text,'так'::text,'так'::text,'так'::text,'Бро, у тієї зброї ніби закінчилася фарба, так?'::text),
(402351,44706,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, a esa arma como que se le acabó la pintura, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'Bro, a esa arma como que se le acabó la pintura, ¿verdad?'::text),
(402350,44706,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, cette arme est genre à court de peinture, ... ?'::text,'hein'::text,'hein'::text,'hein'::text,'Frère, cette arme est genre à court de peinture, hein ?'::text),
(402353,44706,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o silahın boyası bitmiş gibi, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Kanka, o silahın boyası bitmiş gibi, değil mi?'::text),
(402354,44706,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, abból a fegyverből mintha kifogyott volna a festék, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'Tesó, abból a fegyverből mintha kifogyott volna a festék, ugye?'::text),
(402357,44707,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, der benutzt die Waffe nicht mehr, und ...'::text,'sein Teamkollege auch nicht'::text,'sein Teamkollege auch'::text,'sein Teamkollege auch nicht'::text,'Nee, der benutzt die Waffe nicht mehr, und sein Teamkollege auch nicht.'::text),
(402361,44707,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, він більше не юзатиме цю зброю, і ...'::text,'його тіммейт теж ні'::text,'його тіммейт теж'::text,'його тіммейт теж ні'::text,'Не, він більше не юзатиме цю зброю, і його тіммейт теж ні.'::text),
(402360,44707,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nah, no va a volver a usar esa arma, y ...'::text,'su compañero tampoco'::text,'su compañero también'::text,'su compañero tampoco'::text,'Nah, no va a volver a usar esa arma, y su compañero tampoco.'::text),
(402359,44707,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan, il va plus utiliser cette arme, et ...'::text,'son coéquipier non plus'::text,'son coéquipier aussi'::text,'son coéquipier non plus'::text,'Nan, il va plus utiliser cette arme, et son coéquipier non plus.'::text),
(402362,44707,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok, o silahı bir daha kullanmayacak, ...'::text,'takım arkadaşı da'::text,'takım arkadaşı da'::text,'takım arkadaşı da'::text,'Yok, o silahı bir daha kullanmayacak, takım arkadaşı da.'::text),
(402363,44707,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, nem fogja többet használni azt a fegyvert, és ...'::text,'a csapattársa sem'::text,'a csapattársa is'::text,'a csapattársa sem'::text,'Á, nem fogja többet használni azt a fegyvert, és a csapattársa sem.'::text),
(402366,44708,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... seine Waffe 45 Minuten lang, bevor das Farbbudget aufgebraucht war.'::text,'nutzte'::text,'nutzt'::text,'nutzte'::text,'Er nutzte seine Waffe 45 Minuten lang, bevor das Farbbudget aufgebraucht war.'::text),
(402370,44708,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... свою зброю 45 хвилин, перш ніж закінчився бюджет на фарбу.'::text,'використовував'::text,'використовує'::text,'використовував'::text,'Він використовував свою зброю 45 хвилин, перш ніж закінчився бюджет на фарбу.'::text),
(402369,44708,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... su arma durante 45 minutos antes de que se acabara el presupuesto de pintura.'::text,'había estado usando'::text,'ha estado usando'::text,'estaba usando'::text,'Él había estado usando su arma durante 45 minutos antes de que se acabara el presupuesto de pintura.'::text),
(402368,44708,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... son arme depuis 45 minutes quand le budget peinture s''est épuisé.'::text,'utilisait'::text,'utilise'::text,'utilisait'::text,'Il utilisait son arme depuis 45 minutes quand le budget peinture s''est épuisé.'::text),
(402371,44708,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Boya bütçesi bitmeden önce silahını 45 dakikadır ...'::text,'kullanıyordu'::text,'kullanıyor'::text,'kullanıyordu'::text,'Boya bütçesi bitmeden önce silahını 45 dakikadır kullanıyordu.'::text),
(402372,44708,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'45 percig ... a fegyverét, mielőtt elfogyott a festékkeret.'::text,'használta'::text,'használja'::text,'használta'::text,'45 percig használta a fegyverét, mielőtt elfogyott a festékkeret.'::text),
(402375,44709,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Ende des Spiels wird er seine Waffe endgültig ...'::text,'abgelegt haben'::text,'ablegen'::text,'am Ablegen sein'::text,'Bis zum Ende des Spiels wird er seine Waffe endgültig abgelegt haben.'::text),
(402379,44709,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця гри він ... свою зброю назавжди.'::text,'відкладе'::text,'відкладе'::text,'відкладатиме'::text,'До кінця гри він відкладе свою зброю назавжди.'::text),
(402378,44709,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el final del juego, ... su arma para siempre.'::text,'habrá dejado'::text,'dejará'::text,'estará dejando'::text,'Para el final del juego, habrá dejado su arma para siempre.'::text),
(402377,44709,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la fin de la partie, il ... son arme pour de bon.'::text,'aura posé'::text,'posera'::text,'sera en train de poser'::text,'D''ici la fin de la partie, il aura posé son arme pour de bon.'::text),
(402380,44709,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oyunun sonuna kadar silahını tamamen ...'::text,'bırakmış olacak'::text,'bırakacak'::text,'bırakıyor olacak'::text,'Oyunun sonuna kadar silahını tamamen bırakmış olacak.'::text),
(402381,44709,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A játék végére végleg ... a fegyverét.'::text,'letette majd'::text,'leteszi'::text,'éppen leteszi'::text,'A játék végére végleg letette majd a fegyverét.'::text),
(394608,43846,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn um ihn herum keine Farbe geplatzt wäre, ... er sich nicht so schnell ergeben! Diese Demütigung!'::text,'hätte'::text,'wird'::text,'hat'::text,'Wenn um ihn herum keine Farbe geplatzt wäre, hätte er sich nicht so schnell ergeben! Diese Demütigung!'::text),
(394612,43846,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби навколо нього не розбризкалася фарба, він ... так швидко! Яке приниження!'::text,'не здався б'::text,'не здасться'::text,'не здався'::text,'Якби навколо нього не розбризкалася фарба, він не здався б так швидко! Яке приниження!'::text),
(394611,43846,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si no le hubiera estallado pintura alrededor, no ... tan rápido! ¡Qué humillación!'::text,'se habría rendido'::text,'se rendirá'::text,'se rindió'::text,'¡Si no le hubiera estallado pintura alrededor, no se habría rendido tan rápido! ¡Qué humillación!'::text),
(394610,43846,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la peinture n''avait pas éclaté autour de lui, il ... si vite ! Quelle humiliation !'::text,'ne se serait pas rendu'::text,'ne se rendra pas'::text,'ne s''est pas rendu'::text,'Si la peinture n''avait pas éclaté autour de lui, il ne se serait pas rendu si vite ! Quelle humiliation !'::text),
(394613,43846,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Etrafında boya patlamasaydı, bu kadar çabuk ...! Ne rezillik!'::text,'teslim olmazdı'::text,'teslim olmayacak'::text,'teslim olmadı'::text,'Etrafında boya patlamasaydı, bu kadar çabuk teslim olmazdı! Ne rezillik!'::text),
(394614,43846,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem robbant volna körülötte festék, nem ... meg ilyen gyorsan! Micsoda megaláztatás!'::text,'adta volna'::text,'adja'::text,'adta'::text,'Ha nem robbant volna körülötte festék, nem adta volna meg ilyen gyorsan! Micsoda megaláztatás!'::text),
(394617,43847,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er sich nicht ergeben hätte, ... er jetzt noch im Spiel.'::text,'wäre'::text,'wäre'::text,'ist'::text,'Wenn er sich nicht ergeben hätte, wäre er jetzt noch im Spiel.'::text),
(394621,43847,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він не здався, то зараз ... ще в грі.'::text,'був би'::text,'був би'::text,'буде'::text,'Якби він не здався, то зараз був би ще в грі.'::text),
(394620,43847,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no se hubiera rendido, ahora ... todavía en el juego.'::text,'estaría'::text,'habría estado'::text,'estará'::text,'Si no se hubiera rendido, ahora estaría todavía en el juego.'::text),
(394619,43847,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il ne s''était pas rendu, il ... encore dans la partie maintenant.'::text,'serait'::text,'aurait été'::text,'sera'::text,'S''il ne s''était pas rendu, il serait encore dans la partie maintenant.'::text),
(394622,43847,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Teslim olmasaydı, şu an hâlâ oyunda ...'::text,'olurdu'::text,'olurdu'::text,'olacak'::text,'Teslim olmasaydı, şu an hâlâ oyunda olurdu.'::text),
(394623,43847,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem adta volna meg magát, most még ... a játékban.'::text,'lenne'::text,'lett volna'::text,'lesz'::text,'Ha nem adta volna meg magát, most még lenne a játékban.'::text),
(394626,43848,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er soll sich schon nach zwei Minuten Spiel ...'::text,'ergeben haben'::text,'ergeben'::text,'ergebend'::text,'Er soll sich schon nach zwei Minuten Spiel ergeben haben.'::text),
(394630,43848,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кажуть, що він ... вже після двох хвилин гри.'::text,'здався'::text,'здатися'::text,'здаючись'::text,'Кажуть, що він здався вже після двох хвилин гри.'::text),
(394629,43848,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se dice que ... tras solo dos minutos de juego.'::text,'se rindió'::text,'rendirse'::text,'rindiéndose'::text,'Se dice que se rindió tras solo dos minutos de juego.'::text),
(394628,43848,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On dit qu''il ... après seulement deux minutes de jeu.'::text,'s''est rendu'::text,'se rendre'::text,'se rendant'::text,'On dit qu''il s''est rendu après seulement deux minutes de jeu.'::text),
(394631,43848,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oyunun sadece iki dakikasından sonra ... söyleniyor.'::text,'teslim olduğu'::text,'teslim olacağı'::text,'teslim olurken'::text,'Oyunun sadece iki dakikasından sonra teslim olduğu söyleniyor.'::text),
(394632,43848,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondják, már két perc játék után ...'::text,'megadta magát'::text,'megadni magát'::text,'megadva magát'::text,'Azt mondják, már két perc játék után megadta magát.'::text),
(394635,43849,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er gab zu, dass er sich ..., weil direkt neben ihm Farbe geplatzt war.'::text,'ergeben hatte'::text,'ergeben'::text,'ergab'::text,'Er gab zu, dass er sich ergeben hatte, weil direkt neben ihm Farbe geplatzt war.'::text),
(394639,43849,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він визнав, що ..., бо фарба розбризкалася прямо поруч із ним.'::text,'здався'::text,'здатися'::text,'здався'::text,'Він визнав, що здався, бо фарба розбризкалася прямо поруч із ним.'::text),
(394638,43849,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Admitió ... porque la pintura estalló justo a su lado.'::text,'haberse rendido'::text,'rendirse'::text,'se rindió'::text,'Admitió haberse rendido porque la pintura estalló justo a su lado.'::text),
(394637,43849,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a admis ... parce que la peinture a éclaté juste à côté de lui.'::text,'s''être rendu'::text,'se rendre'::text,'s''est rendu'::text,'Il a admis s''être rendu parce que la peinture a éclaté juste à côté de lui.'::text),
(394640,43849,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hemen yanında boya patladığı için ... itiraf etti.'::text,'teslim olduğunu'::text,'teslim olmayı'::text,'teslim oldu'::text,'Hemen yanında boya patladığı için teslim olduğunu itiraf etti.'::text),
(394641,43849,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beismerte, hogy ..., mert közvetlenül mellette robbant a festék.'::text,'megadta magát'::text,'megadni magát'::text,'megadta magát'::text,'Beismerte, hogy megadta magát, mert közvetlenül mellette robbant a festék.'::text),
(394644,43850,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... sich nicht so früh ergeben dürfen; sein Team brauchte ihn noch.'::text,'hätte'::text,'musste'::text,'konnte'::text,'Er hätte sich nicht so früh ergeben dürfen; sein Team brauchte ihn noch.'::text),
(394648,43850,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... здаватися так рано; його команда ще потребувала його.'::text,'не мав'::text,'не мусив'::text,'не міг'::text,'Він не мав здаватися так рано; його команда ще потребувала його.'::text),
(394647,43850,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No ... rendirse tan pronto; su equipo todavía lo necesitaba.'::text,'debió'::text,'tuvo que'::text,'pudo'::text,'No debió rendirse tan pronto; su equipo todavía lo necesitaba.'::text),
(394646,43850,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... se rendre si tôt ; son équipe avait encore besoin de lui.'::text,'n''aurait pas dû'::text,'n''a pas dû'::text,'ne pouvait pas'::text,'Il n''aurait pas dû se rendre si tôt ; son équipe avait encore besoin de lui.'::text),
(394649,43850,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu kadar erken teslim ...; takımının ona hâlâ ihtiyacı vardı.'::text,'olmamalıydı'::text,'olmamış olmalı'::text,'olamazdı'::text,'Bu kadar erken teslim olmamalıydı; takımının ona hâlâ ihtiyacı vardı.'::text),
(394650,43850,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem ... ilyen korán megadnia magát; a csapatának még szüksége volt rá.'::text,'kellett volna'::text,'kellett'::text,'lehetett'::text,'Nem kellett volna ilyen korán megadnia magát; a csapatának még szüksége volt rá.'::text),
(394653,43851,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nie ... jemanden mit so einem breiten Grinsen aufgeben sehen.'::text,'habe ich'::text,'ich habe'::text,'sah ich'::text,'Nie habe ich jemanden mit so einem breiten Grinsen aufgeben sehen.'::text),
(394657,43851,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніколи ..., щоб хтось здавався з такою широкою усмішкою.'::text,'я не бачив'::text,'я не бачив'::text,'я не бачив'::text,'Ніколи я не бачив, щоб хтось здавався з такою широкою усмішкою.'::text),
(394656,43851,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nunca ... a nadie rendirse con una sonrisa tan grande.'::text,'he visto'::text,'he visto'::text,'vi'::text,'Nunca he visto a nadie rendirse con una sonrisa tan grande.'::text),
(394655,43851,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jamais ... quelqu''un se rendre avec un si grand sourire.'::text,'je n''ai vu'::text,'j''ai vu'::text,'je vis'::text,'Jamais je n''ai vu quelqu''un se rendre avec un si grand sourire.'::text),
(394658,43851,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hiç kimsenin bu kadar büyük bir sırıtışla teslim olduğunu ...'::text,'görmedim'::text,'görmedim'::text,'görmedim'::text,'Hiç kimsenin bu kadar büyük bir sırıtışla teslim olduğunu görmedim.'::text),
(394659,43851,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soha ... senkit ilyen nagy vigyorral megadni magát.'::text,'nem láttam'::text,'nem láttam'::text,'nem láttam'::text,'Soha nem láttam senkit ilyen nagy vigyorral megadni magát.'::text),
(394662,43852,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Schiedsrichter brachte ihn dazu, sich vor der 10-Minuten-Frist ...'::text,'zu ergeben'::text,'ergeben'::text,'ergebend'::text,'Der Schiedsrichter brachte ihn dazu, sich vor der 10-Minuten-Frist zu ergeben.'::text),
(394666,43852,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Суддя змусив його ... до 10-хвилинного дедлайну.'::text,'здатися'::text,'здатися'::text,'здаючись'::text,'Суддя змусив його здатися до 10-хвилинного дедлайну.'::text),
(394665,43852,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El árbitro consiguió que ... antes del plazo de 10 minutos.'::text,'se rindiera'::text,'se rindiera'::text,'rindiéndose'::text,'El árbitro consiguió que se rindiera antes del plazo de 10 minutos.'::text),
(394664,43852,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''arbitre l''a amené ... avant la deadline des 10 minutes.'::text,'à se rendre'::text,'se rendre'::text,'se rendant'::text,'L''arbitre l''a amené à se rendre avant la deadline des 10 minutes.'::text),
(394667,43852,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hakem onu 10 dakikalık son tarihten önce ... ikna etti.'::text,'teslim olmaya'::text,'teslim olmaya'::text,'teslim olurken'::text,'Hakem onu 10 dakikalık son tarihten önce teslim olmaya ikna etti.'::text),
(394668,43852,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A bíró elérte, hogy a 10 perces határidő előtt ...'::text,'megadja magát'::text,'megadja magát'::text,'megadva magát'::text,'A bíró elérte, hogy a 10 perces határidő előtt megadja magát.'::text),
(394671,43853,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seine Teamkollegen wünschten, er ... sich nicht so schnell ergeben.'::text,'hätte'::text,'hat'::text,'würde'::text,'Seine Teamkollegen wünschten, er hätte sich nicht so schnell ergeben.'::text),
(394675,43853,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його товариші по команді шкодують, що він ... так швидко.'::text,'здався'::text,'здається'::text,'здаватиметься'::text,'Його товариші по команді шкодують, що він здався так швидко.'::text),
(394674,43853,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sus compañeros desearían que no ... tan rápido.'::text,'se hubiera rendido'::text,'se rindiera'::text,'se rindiera'::text,'Sus compañeros desearían que no se hubiera rendido tan rápido.'::text),
(394673,43853,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ses coéquipiers aimeraient qu''il ... si vite.'::text,'ne se soit pas rendu'::text,'ne se rende pas'::text,'ne se rende pas'::text,'Ses coéquipiers aimeraient qu''il ne se soit pas rendu si vite.'::text),
(394676,43853,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Takım arkadaşları keşke bu kadar çabuk ... diyor.'::text,'teslim olmasaydı'::text,'teslim olmasa'::text,'teslim olmasa'::text,'Takım arkadaşları keşke bu kadar çabuk teslim olmasaydı diyor.'::text),
(394677,43853,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csapattársai azt szeretnék, bárcsak ne ... meg ilyen gyorsan.'::text,'adta volna'::text,'adná'::text,'adná'::text,'A csapattársai azt szeretnék, bárcsak ne adta volna meg ilyen gyorsan.'::text),
(394680,43854,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Spieler, ... Markierer am Boden lag, ergab sich anschließend.'::text,'dessen'::text,'welcher'::text,'der'::text,'Der Spieler, dessen Markierer am Boden lag, ergab sich anschließend.'::text),
(394684,43854,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гравець, ... маркер лежав на землі, згодом здався.'::text,'чий'::text,'який'::text,'що'::text,'Гравець, чий маркер лежав на землі, згодом здався.'::text),
(394683,43854,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El jugador, ... marcadora yacía en el suelo, se rindió posteriormente.'::text,'cuya'::text,'el cual'::text,'que'::text,'El jugador, cuya marcadora yacía en el suelo, se rindió posteriormente.'::text),
(394682,43854,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le joueur, ... le lanceur gisait au sol, s''est ensuite rendu.'::text,'dont'::text,'lequel'::text,'que'::text,'Le joueur, dont le lanceur gisait au sol, s''est ensuite rendu.'::text),
(394685,43854,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Markeri yerde ... oyuncu ardından teslim oldu.'::text,'duran'::text,'duran'::text,'duran'::text,'Markeri yerde duran oyuncu ardından teslim oldu.'::text),
(394686,43854,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A játékos, ... markere a földön feküdt, ezt követően megadta magát.'::text,'akinek a'::text,'amely'::text,'aki'::text,'A játékos, akinek a markere a földön feküdt, ezt követően megadta magát.'::text),
(394689,43855,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hat sich ergeben, ... sein Team noch gewann! Verrat!'::text,'obwohl'::text,'trotz'::text,'wegen'::text,'Er hat sich ergeben, obwohl sein Team noch gewann! Verrat!'::text),
(394693,43855,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він здався, ... його команда ще вигравала! Зрада!'::text,'хоча'::text,'попри'::text,'через'::text,'Він здався, хоча його команда ще вигравала! Зрада!'::text),
(394692,43855,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Se rindió ... su equipo seguía ganando! ¡Traición!'::text,'aunque'::text,'a pesar de'::text,'por'::text,'¡Se rindió aunque su equipo seguía ganando! ¡Traición!'::text),
(394691,43855,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il s''est rendu ... son équipe gagnait encore ! Trahison !'::text,'alors que'::text,'malgré'::text,'à cause de'::text,'Il s''est rendu alors que son équipe gagnait encore ! Trahison !'::text),
(394694,43855,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Takımı hâlâ kazanıyor ... teslim oldu! İhanet!'::text,'olmasına rağmen'::text,'rağmen'::text,'yüzünden'::text,'Takımı hâlâ kazanıyor olmasına rağmen teslim oldu! İhanet!'::text),
(394695,43855,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megadta magát, ... a csapata még nyert! Árulás!'::text,'pedig'::text,'annak ellenére'::text,'miatt'::text,'Megadta magát, pedig a csapata még nyert! Árulás!'::text),
(393681,43743,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Also hör zu, sie schwört, sie ... sich gerade Burger in den Mund, als die Menge anfing zu jubeln.'::text,'stopfte'::text,'stopfte'::text,'hat gestopft'::text,'Also hör zu, sie schwört, sie stopfte sich gerade Burger in den Mund, als die Menge anfing zu jubeln.'::text),
(393685,43743,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, вона клянеться, що ... бургери в рот, коли натовп почав вигукувати.'::text,'запихала'::text,'запхала'::text,'запхала'::text,'Слухай, вона клянеться, що запихала бургери в рот, коли натовп почав вигукувати.'::text),
(393684,43743,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, jura que ... hamburguesas en la boca cuando el público empezó a animar.'::text,'se estaba metiendo'::text,'se metió'::text,'se ha metido'::text,'Oye, jura que se estaba metiendo hamburguesas en la boca cuando el público empezó a animar.'::text),
(393683,43743,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, elle jure qu''elle ... des burgers dans la bouche quand la foule a commencé à applaudir.'::text,'se fourrait'::text,'s''est fourré'::text,'s''est fourré'::text,'Écoute, elle jure qu''elle se fourrait des burgers dans la bouche quand la foule a commencé à applaudir.'::text),
(393686,43743,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bak şimdi, kalabalık tezahürat yapmaya başladığında ağzına burger ... yemin ediyor.'::text,'tıkıştırıyor olduğuna'::text,'tıkıştırdığına'::text,'tıkıştırmış olduğuna'::text,'Bak şimdi, kalabalık tezahürat yapmaya başladığında ağzına burger tıkıştırıyor olduğuna yemin ediyor.'::text),
(393687,43743,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, esküszik, hogy éppen ... a burgereket a szájába, amikor a tömeg ujjongani kezdett.'::text,'tömte'::text,'betömte'::text,'betömte'::text,'Figyelj, esküszik, hogy éppen tömte a burgereket a szájába, amikor a tömeg ujjongani kezdett.'::text),
(393690,43744,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... sich jetzt schon seit zehn Minuten Burger in den Mund.'::text,'stopft'::text,'stopft'::text,'stopft'::text,'Sie stopft sich jetzt schon seit zehn Minuten Burger in den Mund.'::text),
(393694,43744,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона вже десять хвилин ... бургери в рот.'::text,'запихає'::text,'запихає'::text,'запихає'::text,'Вона вже десять хвилин запихає бургери в рот.'::text),
(393693,43744,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lleva diez minutos ... hamburguesas en la boca.'::text,'metiéndose'::text,'metiéndose'::text,'metiéndose'::text,'Lleva diez minutos metiéndose hamburguesas en la boca.'::text),
(393692,43744,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ça fait dix minutes qu''elle ... des burgers dans la bouche.'::text,'se fourre'::text,'se fourre'::text,'se fourre'::text,'Ça fait dix minutes qu''elle se fourre des burgers dans la bouche.'::text),
(393695,43744,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On dakikadır ağzına burger ...'::text,'tıkıştırıyor'::text,'tıkıştırıyor'::text,'tıkıştırıyor'::text,'On dakikadır ağzına burger tıkıştırıyor.'::text),
(393696,43744,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már tíz perce ... a burgereket a szájába.'::text,'tömi'::text,'tömi'::text,'tömi'::text,'Már tíz perce tömi a burgereket a szájába.'::text),
(393699,43745,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie trank etwas Wasser und ... sich dann einen ganzen Burger in den Mund.'::text,'stopfte'::text,'stopfte'::text,'stopft'::text,'Sie trank etwas Wasser und stopfte sich dann einen ganzen Burger in den Mund.'::text),
(393703,43745,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона випила трохи води, а потім ... в рот цілий бургер.'::text,'запхала'::text,'запихала'::text,'запихає'::text,'Вона випила трохи води, а потім запхала в рот цілий бургер.'::text),
(393702,43745,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bebió un poco de agua y luego ... una hamburguesa entera en la boca.'::text,'se metió'::text,'se estaba metiendo'::text,'se mete'::text,'Bebió un poco de agua y luego se metió una hamburguesa entera en la boca.'::text),
(393701,43745,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a bu un peu d''eau, puis ... un burger entier dans la bouche.'::text,'s''est fourré'::text,'se fourrait'::text,'se fourre'::text,'Elle a bu un peu d''eau, puis s''est fourré un burger entier dans la bouche.'::text),
(393704,43745,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Biraz su içti ve sonra ağzına koca bir burger ...'::text,'tıkıştırdı'::text,'tıkıştırıyordu'::text,'tıkıştırıyor'::text,'Biraz su içti ve sonra ağzına koca bir burger tıkıştırdı.'::text),
(393705,43745,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ivott egy kis vizet, aztán ... egy egész burgert a szájába.'::text,'betömött'::text,'tömött'::text,'töm'::text,'Ivott egy kis vizet, aztán betömött egy egész burgert a szájába.'::text),
(393708,43746,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hat sich bis jetzt vier Burger in den Mund ...'::text,'gestopft'::text,'gestopft'::text,'gestopft'::text,'Sie hat sich bis jetzt vier Burger in den Mund gestopft.'::text),
(393712,43746,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона вже ... в рот чотири бургери.'::text,'запхала'::text,'запихала'::text,'запихає'::text,'Вона вже запхала в рот чотири бургери.'::text),
(393711,43746,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hasta ahora ... cuatro hamburguesas en la boca.'::text,'se ha metido'::text,'se ha estado metiendo'::text,'se mete'::text,'Hasta ahora se ha metido cuatro hamburguesas en la boca.'::text),
(393710,43746,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jusqu''ici, elle ... quatre burgers dans la bouche.'::text,'s''est fourré'::text,'se fourre'::text,'se fourre'::text,'Jusqu''ici, elle s''est fourré quatre burgers dans la bouche.'::text),
(393713,43746,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şimdiye kadar ağzına dört burger ...'::text,'tıkıştırdı'::text,'tıkıştırıyor'::text,'tıkıştırıyor'::text,'Şimdiye kadar ağzına dört burger tıkıştırdı.'::text),
(393714,43746,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eddig négy burgert ... a szájába.'::text,'tömött be'::text,'tömött'::text,'töm'::text,'Eddig négy burgert tömött be a szájába.'::text),
(393726,43748,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie noch einen Burger reinstopft, ... sie noch einen Burger, also ganz einfach.'::text,'isst'::text,'äße'::text,'aß'::text,'Wenn sie noch einen Burger reinstopft, isst sie noch einen Burger, also ganz einfach.'::text),
(393730,43748,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вона запхає ще один бургер, вона ... ще один бургер, тож усе просто.'::text,'з''їсть'::text,'з''їла б'::text,'з''їла'::text,'Якщо вона запхає ще один бургер, вона з''їсть ще один бургер, тож усе просто.'::text),
(393729,43748,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si se mete una hamburguesa más, ... una hamburguesa más, así que es fácil.'::text,'se comerá'::text,'se comería'::text,'se comió'::text,'Si se mete una hamburguesa más, se comerá una hamburguesa más, así que es fácil.'::text),
(393728,43748,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle se fourre encore un burger, elle ... encore un burger, donc c''est simple.'::text,'mangera'::text,'mangerait'::text,'a mangé'::text,'Si elle se fourre encore un burger, elle mangera encore un burger, donc c''est simple.'::text),
(393731,43748,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir burger daha tıkıştırırsa, bir burger daha ..., yani çok kolay.'::text,'yiyecek'::text,'yerdi'::text,'yedi'::text,'Bir burger daha tıkıştırırsa, bir burger daha yiyecek, yani çok kolay.'::text),
(393732,43748,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha betöm még egy burgert, akkor ... még egy burgert, szóval ez egyszerű.'::text,'megeszik'::text,'megenne'::text,'megevett'::text,'Ha betöm még egy burgert, akkor megeszik még egy burgert, szóval ez egyszerű.'::text),
(393735,43749,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Teilnehmer ihre Münder langsamer ..., würden sie typischerweise besser kauen.'::text,'vollstopften'::text,'vollstopfen'::text,'vollstopfen würden'::text,'Wenn die Teilnehmer ihre Münder langsamer vollstopften, würden sie typischerweise besser kauen.'::text),
(393739,43749,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби учасники ... роти повільніше, вони зазвичай жували б краще.'::text,'напихали'::text,'напихають'::text,'напихали б'::text,'Якби учасники напихали роти повільніше, вони зазвичай жували б краще.'::text),
(393738,43749,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si los participantes se ... la boca más despacio, normalmente masticarían mejor.'::text,'llenaran'::text,'llenan'::text,'llenarían'::text,'Si los participantes se llenaran la boca más despacio, normalmente masticarían mejor.'::text),
(393737,43749,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si les concurrents se ... la bouche plus lentement, ils mâcheraient généralement mieux.'::text,'remplissaient'::text,'remplissent'::text,'rempliraient'::text,'Si les concurrents se remplissaient la bouche plus lentement, ils mâcheraient généralement mieux.'::text),
(393740,43749,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarışmacılar ağızlarını daha yavaş ..., genellikle daha iyi çiğnerlerdi.'::text,'doldursalar'::text,'dolduruyorlar'::text,'doldururlardı'::text,'Yarışmacılar ağızlarını daha yavaş doldursalar, genellikle daha iyi çiğnerlerdi.'::text),
(393741,43749,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a versenyzők lassabban ... a szájukat, jellemzően jobban rágnának.'::text,'tömnék'::text,'tömik'::text,'tömnék'::text,'Ha a versenyzők lassabban tömnék a szájukat, jellemzően jobban rágnának.'::text),
(393744,43750,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Noch ein Burger ... ihr in den Mund gestopft! Dieser Wettbewerb ist das totale Chaos!'::text,'wurde'::text,'stopfte'::text,'stopft'::text,'Noch ein Burger wurde ihr in den Mund gestopft! Dieser Wettbewerb ist das totale Chaos!'::text),
(393748,43750,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ще один бургер ... їй у рот! Цей конкурс — повний хаос!'::text,'запхали'::text,'запхав'::text,'запихає'::text,'Ще один бургер запхали їй у рот! Цей конкурс — повний хаос!'::text),
(393747,43750,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Otra hamburguesa ... en su boca! ¡Este concurso es un caos absoluto!'::text,'fue metida'::text,'metió'::text,'está metiendo'::text,'¡Otra hamburguesa fue metida en su boca! ¡Este concurso es un caos absoluto!'::text),
(393746,43750,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Encore un burger ... dans sa bouche ! Ce concours, c''est le chaos total !'::text,'a été fourré'::text,'a fourré'::text,'est en train de fourrer'::text,'Encore un burger a été fourré dans sa bouche ! Ce concours, c''est le chaos total !'::text),
(393749,43750,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ağzına bir burger daha ...! Bu yarışma tam bir kaos!'::text,'tıkıştırıldı'::text,'tıkıştırdı'::text,'tıkıştırıyor'::text,'Ağzına bir burger daha tıkıştırıldı! Bu yarışma tam bir kaos!'::text),
(393750,43750,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Még egy burger ... a szájába! Ez a verseny totális káosz!'::text,'került be'::text,'tömött'::text,'töm'::text,'Még egy burger került be a szájába! Ez a verseny totális káosz!'::text),
(393753,43751,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... sie sich Burger um Burger in den Mund! Das ist buchstäblich Krieg!'::text,'stopft'::text,'stopft'::text,'hat gestopft'::text,'Gerade stopft sie sich Burger um Burger in den Mund! Das ist buchstäblich Krieg!'::text),
(393757,43751,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Прямо зараз вона ... в рот бургер за бургером! Це буквально війна!'::text,'запихає'::text,'запихає'::text,'запхала'::text,'Прямо зараз вона запихає в рот бургер за бургером! Це буквально війна!'::text),
(393756,43751,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ahora mismo ... una hamburguesa tras otra en la boca! ¡Es literalmente la guerra!'::text,'se está metiendo'::text,'se mete'::text,'se ha metido'::text,'¡Ahora mismo se está metiendo una hamburguesa tras otra en la boca! ¡Es literalmente la guerra!'::text),
(393755,43751,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Là, maintenant, elle ... burger sur burger dans la bouche ! C''est littéralement la guerre !'::text,'se fourre'::text,'se fourre'::text,'s''est fourré'::text,'Là, maintenant, elle se fourre burger sur burger dans la bouche ! C''est littéralement la guerre !'::text),
(393758,43751,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda ağzına burger üstüne burger ...! Resmen savaş!'::text,'tıkıştırıyor'::text,'tıkıştırıyor'::text,'tıkıştırdı'::text,'Şu anda ağzına burger üstüne burger tıkıştırıyor! Resmen savaş!'::text),
(393759,43751,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most ... egyik burgert a másik után a szájába! Ez szó szerint háború!'::text,'tömi'::text,'tömi'::text,'tömte'::text,'Épp most tömi egyik burgert a másik után a szájába! Ez szó szerint háború!'::text),
(393771,43753,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, angeblich wird sie sich bis zum Schlussgong 20 Burger in den Mund ...'::text,'gestopft haben'::text,'stopfen'::text,'stopft'::text,'Bestie, angeblich wird sie sich bis zum Schlussgong 20 Burger in den Mund gestopft haben.'::text),
(393775,43753,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, до фінального дзвоника вона ... в рот 20 бургерів.'::text,'запхає'::text,'запхає'::text,'запихає'::text,'Подруго, кажуть, до фінального дзвоника вона запхає в рот 20 бургерів.'::text),
(393774,43753,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, al parecer para la campana final ... 20 hamburguesas en la boca.'::text,'se habrá metido'::text,'se meterá'::text,'se mete'::text,'Amiga, al parecer para la campana final se habrá metido 20 hamburguesas en la boca.'::text),
(393773,43753,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment, d''ici la sonnerie finale, elle ... 20 burgers dans la bouche.'::text,'se sera fourré'::text,'se fourrera'::text,'se fourre'::text,'Ma belle, apparemment, d''ici la sonnerie finale, elle se sera fourré 20 burgers dans la bouche.'::text),
(393776,43753,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duyduğuma göre son zile kadar ağzına 20 burger ...'::text,'tıkıştırmış olacakmış'::text,'tıkıştıracakmış'::text,'tıkıştırıyormuş'::text,'Kanka, duyduğuma göre son zile kadar ağzına 20 burger tıkıştırmış olacakmış.'::text),
(393777,43753,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag a záróhangjelzésig 20 burgert ... a szájába.'::text,'töm majd be'::text,'töm be'::text,'töm'::text,'Csajszi, állítólag a záróhangjelzésig 20 burgert töm majd be a szájába.'::text),
(397515,44169,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen früh um acht wird der harte Boxer wieder in diesem Gym ...'::text,'trainieren'::text,'trainieren'::text,'trainiert'::text,'Morgen früh um acht wird der harte Boxer wieder in diesem Gym trainieren.'::text),
(397519,44169,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра о восьмій ранку цей жорсткий боксер знову ... в цьому залі.'::text,'тренуватиметься'::text,'тренуватиметься'::text,'тренується'::text,'Завтра о восьмій ранку цей жорсткий боксер знову тренуватиметься в цьому залі.'::text),
(397518,44169,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a las ocho, el boxeador duro ... otra vez en este gimnasio.'::text,'estará entrenando'::text,'entrenará'::text,'entrena'::text,'Mañana a las ocho, el boxeador duro estará entrenando otra vez en este gimnasio.'::text),
(397517,44169,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à huit heures, le boxeur coriace ... de nouveau dans cette salle.'::text,'sera en train de s''entraîner'::text,'s''entraînera'::text,'s''entraîne'::text,'Demain à huit heures, le boxeur coriace sera en train de s''entraîner de nouveau dans cette salle.'::text),
(397520,44169,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın sabah sekizde sert boksör yine bu salonda ...'::text,'antrenman yapıyor olacak'::text,'antrenman yapacak'::text,'antrenman yapıyor'::text,'Yarın sabah sekizde sert boksör yine bu salonda antrenman yapıyor olacak.'::text),
(397521,44169,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap reggel nyolckor a kemény bokszoló ismét ebben a teremben ...'::text,'épp edzeni fog'::text,'edzeni fog'::text,'edz'::text,'Holnap reggel nyolckor a kemény bokszoló ismét ebben a teremben épp edzeni fog.'::text),
(397524,44170,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Trainer will noch eine harte Runde, und der Boxer sagt: „Ich ... sie.“'::text,'übernehme'::text,'werde übernehmen'::text,'übernehme gerade'::text,'Der Trainer will noch eine harte Runde, und der Boxer sagt: „Ich übernehme sie.“'::text),
(397528,44170,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тренер просить ще один жорсткий раунд, і боксер каже: «Я ... це».'::text,'зроблю'::text,'робитиму'::text,'роблю'::text,'Тренер просить ще один жорсткий раунд, і боксер каже: «Я зроблю це».'::text),
(397527,44170,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El entrenador pide un asalto duro más, y el boxeador dice: «Lo ...».'::text,'haré'::text,'estaré haciendo'::text,'estoy haciendo'::text,'El entrenador pide un asalto duro más, y el boxeador dice: «Lo haré».'::text),
(397526,44170,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le coach demande encore un round difficile. « Je le ... », répond le boxeur.'::text,'ferai'::text,'serai en train de faire'::text,'fais'::text,'Le coach demande encore un round difficile. « Je le ferai », répond le boxeur.'::text),
(397529,44170,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antrenör bir sert raunt daha istiyor, boksör de “...” diyor.'::text,'Yaparım'::text,'Yapıyor olacağım'::text,'Yapıyorum'::text,'Antrenör bir sert raunt daha istiyor, boksör de “Yaparım” diyor.'::text),
(397530,44170,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az edző kér még egy kemény menetet, a bokszoló pedig azt mondja: „...”'::text,'Megcsinálom'::text,'Csinálni fogom'::text,'Csinálom'::text,'Az edző kér még egy kemény menetet, a bokszoló pedig azt mondja: „Megcsinálom”'::text),
(397533,44171,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Handtuch ... vom harten Boxer benutzt, um seinen Kopf zu trocknen, was auf eine lange Einheit hindeutet.'::text,'wurde'::text,'benutzte'::text,'benutzend'::text,'Das Handtuch wurde vom harten Boxer benutzt, um seinen Kopf zu trocknen, was auf eine lange Einheit hindeutet.'::text),
(397537,44171,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Рушник ... жорстким боксером, щоб висушити голову, що вказує на довге тренування.'::text,'був використаний'::text,'використав'::text,'використовуючи'::text,'Рушник був використаний жорстким боксером, щоб висушити голову, що вказує на довге тренування.'::text),
(397536,44171,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La toalla ... por el boxeador duro para secarse la cabeza, lo que indica una sesión larga.'::text,'fue usada'::text,'usó'::text,'usando'::text,'La toalla fue usada por el boxeador duro para secarse la cabeza, lo que indica una sesión larga.'::text),
(397535,44171,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La serviette ... par le boxeur coriace pour se sécher la tête, ce qui indique une longue séance.'::text,'a été utilisée'::text,'a utilisé'::text,'utilisant'::text,'La serviette a été utilisée par le boxeur coriace pour se sécher la tête, ce qui indique une longue séance.'::text),
(397538,44171,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Havlu, sert boksör tarafından başını kurulamak için ..., bu da uzun bir antrenmana işaret ediyor.'::text,'kullanıldı'::text,'kullandı'::text,'kullanarak'::text,'Havlu, sert boksör tarafından başını kurulamak için kullanıldı, bu da uzun bir antrenmana işaret ediyor.'::text),
(397539,44171,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A törölközőt a kemény bokszoló ... a feje megszárítására, ami hosszú edzésre utal.'::text,'használta'::text,'használt'::text,'használva'::text,'A törölközőt a kemény bokszoló használta a feje megszárítására, ami hosszú edzésre utal.'::text),
(397542,44172,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nach so einer brutalen Einheit ... er absolut hart sein!'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Nach so einer brutalen Einheit muss er absolut hart sein!'::text),
(397546,44172,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Після такого жорстокого тренування він ... бути абсолютно жорстким!'::text,'мусить'::text,'не може'::text,'мав би'::text,'Після такого жорстокого тренування він мусить бути абсолютно жорстким!'::text),
(397545,44172,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Después de una sesión tan brutal, ... ser un tipo durísimo!'::text,'debe de'::text,'no puede'::text,'debería'::text,'¡Después de una sesión tan brutal, debe de ser un tipo durísimo!'::text),
(397544,44172,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Après une séance aussi brutale, il ... être un vrai dur !'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'Après une séance aussi brutale, il doit être un vrai dur !'::text),
(397547,44172,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu kadar acımasız bir antrenmandan sonra kesinlikle sert biri ...!'::text,'olmalı'::text,'olamaz'::text,'olmalı'::text,'Bu kadar acımasız bir antrenmandan sonra kesinlikle sert biri olmalı!'::text),
(397548,44172,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy ilyen brutális edzés után abszolút keménynek ... lennie!'::text,'kell'::text,'nem lehet'::text,'kellene'::text,'Egy ilyen brutális edzés után abszolút keménynek kell lennie!'::text),
(397551,44173,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Gym, ... der harte Boxer trainiert, ist buchstäblich eine Schweißfabrik!'::text,'in dem'::text,'das'::text,'der'::text,'Das Gym, in dem der harte Boxer trainiert, ist buchstäblich eine Schweißfabrik!'::text),
(397555,44173,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зал, ... тренується жорсткий боксер, — це буквально фабрика поту!'::text,'де'::text,'який'::text,'хто'::text,'Зал, де тренується жорсткий боксер, — це буквально фабрика поту!'::text),
(397554,44173,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El gimnasio ... entrena el boxeador duro es literalmente una fábrica de sudor!'::text,'donde'::text,'que'::text,'quien'::text,'¡El gimnasio donde entrena el boxeador duro es literalmente una fábrica de sudor!'::text),
(397553,44173,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La salle ... s''entraîne le boxeur coriace est littéralement une usine à sueur !'::text,'où'::text,'que'::text,'qui'::text,'La salle où s''entraîne le boxeur coriace est littéralement une usine à sueur !'::text),
(397556,44173,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sert boksörün antrenman ... salon resmen bir ter fabrikası!'::text,'yaptığı'::text,'yaptığı'::text,'yapan'::text,'Sert boksörün antrenman yaptığı salon resmen bir ter fabrikası!'::text),
(397557,44173,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az edzőterem, ... a kemény bokszoló edz, szó szerint egy izzadtséggyár!'::text,'ahol'::text,'amely'::text,'aki'::text,'Az edzőterem, ahol a kemény bokszoló edz, szó szerint egy izzadtséggyár!'::text),
(397569,44175,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Unter uns, er hat zugegeben, dass er ... Angst vor hartem Training hatte.'::text,'früher'::text,'früher'::text,'gewohnheitsmäßig'::text,'Unter uns, er hat zugegeben, dass er früher Angst vor hartem Training hatte.'::text),
(397573,44175,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Між нами, він зізнався, що ... боявся жорстких тренувань.'::text,'колись'::text,'колись'::text,'звично'::text,'Між нами, він зізнався, що колись боявся жорстких тренувань.'::text),
(397572,44175,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Entre nosotros, admitió que ... tenerle miedo al entrenamiento duro.'::text,'solía'::text,'solía'::text,'estaba acostumbrado a'::text,'Entre nosotros, admitió que solía tenerle miedo al entrenamiento duro.'::text),
(397571,44175,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Entre nous, il a avoué qu''avant, il ... peur des entraînements durs.'::text,'avait'::text,'avait'::text,'avait l''habitude d''avoir'::text,'Entre nous, il a avoué qu''avant, il avait peur des entraînements durs.'::text),
(397574,44175,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aramızda kalsın, eskiden sert antrenmandan ... itiraf etti.'::text,'korktuğunu'::text,'korktuğunu'::text,'korkmaya alışkın olduğunu'::text,'Aramızda kalsın, eskiden sert antrenmandan korktuğunu itiraf etti.'::text),
(397575,44175,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köztünk szólva, bevallotta, hogy ... félt a kemény edzésektől.'::text,'régen'::text,'régen'::text,'megszokásból'::text,'Köztünk szólva, bevallotta, hogy régen félt a kemény edzésektől.'::text),
(397578,44176,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, ich hab gehört, er kommt nicht drumherum, vor der Kamera hart ...'::text,'auszusehen'::text,'auszusehen'::text,'aussehen'::text,'Hör zu, ich hab gehört, er kommt nicht drumherum, vor der Kamera hart auszusehen.'::text),
(397582,44176,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що він не може не ... жорстким перед камерою.'::text,'виглядати'::text,'виглядати'::text,'виглядати'::text,'Слухай, я чула, що він не може не виглядати жорстким перед камерою.'::text),
(397581,44176,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, he oído que no puede evitar ... duro delante de la cámara.'::text,'parecer'::text,'parecer'::text,'parecer'::text,'Oye, he oído que no puede evitar parecer duro delante de la cámara.'::text),
(397580,44176,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il paraît qu''il ne peut pas s''empêcher d''... dur devant la caméra.'::text,'avoir l''air'::text,'avoir l''air'::text,'avoir l''air'::text,'Écoute, il paraît qu''il ne peut pas s''empêcher d''avoir l''air dur devant la caméra.'::text),
(397583,44176,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duyduğuma göre kamera karşısında sert ... kendini alamıyormuş.'::text,'görünmekten'::text,'görünmeye'::text,'görünmek'::text,'Dinle, duyduğuma göre kamera karşısında sert görünmekten kendini alamıyormuş.'::text),
(397584,44176,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy nem tudja elkerülni, hogy keménynek ... a kamera előtt.'::text,'tűnjön'::text,'tűnjön'::text,'tűnik'::text,'Figyelj, azt hallottam, hogy nem tudja elkerülni, hogy keménynek tűnjön a kamera előtt.'::text),
(397587,44177,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also angeblich ist er hier der härteste Boxer, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Okay, also angeblich ist er hier der härteste Boxer, oder?'::text),
(397591,44177,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Отже, кажуть, він тут найжорсткіший боксер, ...?'::text,'правда'::text,'правда'::text,'правда'::text,'Отже, кажуть, він тут найжорсткіший боксер, правда?'::text),
(397590,44177,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, al parecer es el boxeador más duro de aquí, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'Vale, al parecer es el boxeador más duro de aquí, ¿verdad?'::text),
(397589,44177,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, apparemment c''est le boxeur le plus coriace ici, ... ?'::text,'non'::text,'non'::text,'non'::text,'Bon, apparemment c''est le boxeur le plus coriace ici, non ?'::text),
(397592,44177,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, güya buradaki en sert boksör o, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Tamam, güya buradaki en sert boksör o, değil mi?'::text),
(397593,44177,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval állítólag ő a legkeményebb bokszoló itt, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'Oké, szóval állítólag ő a legkeményebb bokszoló itt, ugye?'::text),
(397596,44178,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt: Du ... die ganze Stunde lang hart.'::text,'bliebst'::text,'bleibst'::text,'bleibst gerade'::text,'Respekt: Du bliebst die ganze Stunde lang hart.'::text),
(397600,44178,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Респект: ти ... жорстким цілу годину.'::text,'залишався'::text,'залишаєшся'::text,'залишаєшся'::text,'Респект: ти залишався жорстким цілу годину.'::text),
(397599,44178,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respeto: te ... duro toda la hora.'::text,'has mantenido'::text,'mantienes'::text,'estás manteniendo'::text,'Respeto: te has mantenido duro toda la hora.'::text),
(397598,44178,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respect : tu ... coriace pendant toute l''heure.'::text,'es resté'::text,'restes'::text,'restes'::text,'Respect : tu es resté coriace pendant toute l''heure.'::text),
(397601,44178,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saygılar: bütün saat boyunca sert ...'::text,'kaldın'::text,'kalıyorsun'::text,'kalıyorsun'::text,'Saygılar: bütün saat boyunca sert kaldın.'::text),
(397602,44178,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le a kalappal: az egész órán át kemény ...'::text,'maradtál'::text,'maradsz'::text,'maradsz'::text,'Le a kalappal: az egész órán át kemény maradtál.'::text),
(338043,37561,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er das Kanu nicht an der kleinen Insel vorbeigepaddelt hätte, ... er die roten Häuser nicht gesehen.'::text,'hätte'::text,'wird'::text,'hat'::text,'Wenn er das Kanu nicht an der kleinen Insel vorbeigepaddelt hätte, hätte er die roten Häuser nicht gesehen.'::text),
(338047,37561,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він не проплив на каное повз острівець, він ... червоних будиночків.'::text,'не побачив би'::text,'не побачить'::text,'не побачив'::text,'Якби він не проплив на каное повз острівець, він не побачив би червоних будиночків.'::text),
(338046,37561,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no hubiera remado en la canoa junto al islote, no ... las casas rojas.'::text,'habría visto'::text,'verá'::text,'vio'::text,'Si no hubiera remado en la canoa junto al islote, no habría visto las casas rojas.'::text),
(338045,37561,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il n''avait pas pagayé en canoë le long de l''îlot, il ... les maisons rouges.'::text,'n''aurait pas vu'::text,'ne verra pas'::text,'n''a pas vu'::text,'S''il n''avait pas pagayé en canoë le long de l''îlot, il n''aurait pas vu les maisons rouges.'::text),
(338048,37561,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanoyla adacığın yanından geçmeseydi, kırmızı evleri ...'::text,'görmezdi'::text,'görmeyecek'::text,'görmedi'::text,'Kanoyla adacığın yanından geçmeseydi, kırmızı evleri görmezdi.'::text),
(338049,37561,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem evezett volna el a kenuval a kis sziget mellett, nem ... a piros házakat.'::text,'látta volna'::text,'fogja látni'::text,'látta'::text,'Ha nem evezett volna el a kenuval a kis sziget mellett, nem látta volna a piros házakat.'::text),
(338052,37562,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hättest du das Kanu nicht schon vor Jahren gemeistert, ... du jetzt nicht so lässig auf dem Wasser. Respekt.'::text,'wärst'::text,'wärst'::text,'bist'::text,'Hättest du das Kanu nicht schon vor Jahren gemeistert, wärst du jetzt nicht so lässig auf dem Wasser. Respekt.'::text),
(338056,37562,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби ти не опанував каное ще кілька років тому, ти зараз ... таким плавним на воді. Респект.'::text,'не був би'::text,'не був би'::text,'не будеш'::text,'Якби ти не опанував каное ще кілька років тому, ти зараз не був би таким плавним на воді. Респект.'::text),
(338055,37562,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no hubieras dominado la canoa hace años, ahora no ... tan fluido en el agua. Respeto.'::text,'estarías'::text,'habrías estado'::text,'estarás'::text,'Si no hubieras dominado la canoa hace años, ahora no estarías tan fluido en el agua. Respeto.'::text),
(338054,37562,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tu n''avais pas maîtrisé le canoë il y a des années, tu ... pas aussi fluide sur l''eau maintenant. Respect.'::text,'ne serais'::text,'n''aurais été'::text,'ne seras'::text,'Si tu n''avais pas maîtrisé le canoë il y a des années, tu ne serais pas aussi fluide sur l''eau maintenant. Respect.'::text),
(338057,37562,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saygılar: yıllar önce kanoda ustalaşmasaydın, şimdi suda bu kadar akıcı ...'::text,'olmazdın'::text,'olmazdın'::text,'olmayacaksın'::text,'Saygılar: yıllar önce kanoda ustalaşmasaydın, şimdi suda bu kadar akıcı olmazdın.'::text),
(338058,37562,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha évekkel ezelőtt nem tanultad volna meg a kenuzást, most nem ... ilyen laza a vízen. Respekt.'::text,'lennél'::text,'lettél volna'::text,'leszel'::text,'Ha évekkel ezelőtt nem tanultad volna meg a kenuzást, most nem lennél ilyen laza a vízen. Respekt.'::text),
(338061,37563,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Man glaubt, dass das gelbe Kanu vor vielen Jahren von Hand gebaut ...'::text,'wurde'::text,'wird'::text,'werdend'::text,'Man glaubt, dass das gelbe Kanu vor vielen Jahren von Hand gebaut wurde.'::text),
(338065,37563,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вважають, що жовте каное ... зроблене вручну багато років тому.'::text,'було'::text,'є'::text,'будучи'::text,'Вважають, що жовте каное було зроблене вручну багато років тому.'::text),
(338064,37563,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se cree que la canoa amarilla ... construida a mano hace muchos años.'::text,'fue'::text,'es'::text,'siendo'::text,'Se cree que la canoa amarilla fue construida a mano hace muchos años.'::text),
(338063,37563,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On pense que le canoë jaune ... construit à la main il y a de nombreuses années.'::text,'a été'::text,'est'::text,'étant'::text,'On pense que le canoë jaune a été construit à la main il y a de nombreuses années.'::text),
(338066,37563,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sarı kanonun yıllar önce elle ... düşünülüyor.'::text,'yapıldığı'::text,'yapıldığı'::text,'yapılırken'::text,'Sarı kanonun yıllar önce elle yapıldığı düşünülüyor.'::text),
(338067,37563,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy tartják, hogy a sárga kenut sok évvel ezelőtt kézzel ...'::text,'építették'::text,'építik'::text,'építve'::text,'Úgy tartják, hogy a sárga kenut sok évvel ezelőtt kézzel építették.'::text),
(338070,37564,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hast zugegeben, dass du das Kanu nur wegen dieser Zimtschnecke ... hast. Ehrlich, Respekt.'::text,'rübergepaddelt'::text,'rüberpaddeln'::text,'rübergepaddelt'::text,'Du hast zugegeben, dass du das Kanu nur wegen dieser Zimtschnecke rübergepaddelt hast. Ehrlich, Respekt.'::text),
(338074,37564,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти зізнався, що ... на каное на той бік лише заради тієї булочки з корицею. Чесно, респект.'::text,'переплив'::text,'перепливти'::text,'переплив'::text,'Ти зізнався, що переплив на каное на той бік лише заради тієї булочки з корицею. Чесно, респект.'::text),
(338073,37564,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Admitiste ... en canoa solo para conseguir ese rollo de canela. Sinceramente, respeto.'::text,'haber cruzado'::text,'cruzar'::text,'cruzaste'::text,'Admitiste haber cruzado en canoa solo para conseguir ese rollo de canela. Sinceramente, respeto.'::text),
(338072,37564,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu as avoué ... en canoë juste pour ce roulé à la cannelle. Franchement, respect.'::text,'avoir traversé'::text,'traverser'::text,'as traversé'::text,'Tu as avoué avoir traversé en canoë juste pour ce roulé à la cannelle. Franchement, respect.'::text),
(338075,37564,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sırf o tarçınlı çörek için kanoyla karşıya ... itiraf ettin. Açıkçası, saygılar.'::text,'geçtiğini'::text,'geçmeyi'::text,'geçtin'::text,'Sırf o tarçınlı çörek için kanoyla karşıya geçtiğini itiraf ettin. Açıkçası, saygılar.'::text),
(338076,37564,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beismerted, hogy csak azért ... át a kenuval, hogy megszerezd azt a fahéjas csigát. Őszintén, respekt.'::text,'eveztél'::text,'evezni'::text,'eveztél'::text,'Beismerted, hogy csak azért eveztél át a kenuval, hogy megszerezd azt a fahéjas csigát. Őszintén, respekt.'::text),
(338079,37565,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... das Kanu vor dieser Zimtschnecke festbinden sollen. Die Heimfahrt ist jetzt leicht ungeplant.'::text,'hätte'::text,'musste'::text,'hätte nicht'::text,'Er hätte das Kanu vor dieser Zimtschnecke festbinden sollen. Die Heimfahrt ist jetzt leicht ungeplant.'::text),
(338083,37565,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... каное ще до тієї булочки з корицею. Дорога додому тепер трохи незапланована.'::text,'мав прив''язати'::text,'напевно прив''язав'::text,'міг не прив''язувати'::text,'Він мав прив''язати каное ще до тієї булочки з корицею. Дорога додому тепер трохи незапланована.'::text),
(338082,37565,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la canoa antes de ese rollo de canela. El viaje de vuelta ahora está un poco improvisado.'::text,'Debería haber atado'::text,'Debe de haber atado'::text,'No necesitaba haber atado'::text,'Debería haber atado la canoa antes de ese rollo de canela. El viaje de vuelta ahora está un poco improvisado.'::text),
(338081,37565,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... le canoë avant ce roulé à la cannelle. Le retour est maintenant légèrement improvisé.'::text,'aurait dû attacher'::text,'a dû attacher'::text,'n''avait pas besoin d''attacher'::text,'Il aurait dû attacher le canoë avant ce roulé à la cannelle. Le retour est maintenant légèrement improvisé.'::text),
(338084,37565,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanoyu o tarçınlı çörekten önce ...: eve dönüş artık biraz plansız.'::text,'bağlamalıydı'::text,'bağlamış olmalı'::text,'bağlamasına gerek yoktu'::text,'Kanoyu o tarçınlı çörekten önce bağlamalıydı: eve dönüş artık biraz plansız.'::text),
(338085,37565,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Még a fahéjas csiga előtt ... a kenut. A hazaút most kissé rögtönzött.'::text,'ki kellett volna kötnie'::text,'biztosan kikötötte'::text,'nem kellett volna kikötnie'::text,'Még a fahéjas csiga előtt ki kellett volna kötnie a kenut. A hazaút most kissé rögtönzött.'::text),
(338088,37566,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Selten ... ein Kanuausflug so heldenhaft geendet: mit einer Zimtschnecke. Echt legendär.'::text,'hat'::text,'hat'::text,'haben'::text,'Selten hat ein Kanuausflug so heldenhaft geendet: mit einer Zimtschnecke. Echt legendär.'::text),
(338092,37566,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Рідко ... подорож на каное закінчувалася так героїчно — булочкою з корицею. Справді легендарно.'::text,''::text,NULL::text,NULL::text,'Рідко подорож на каное закінчувалася так героїчно — булочкою з корицею. Справді легендарно.'::text),
(338091,37566,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pocas veces ... terminado una excursión en canoa de forma tan heroica, con un rollo de canela. Realmente legendario.'::text,'ha'::text,'ha'::text,'han'::text,'Pocas veces ha terminado una excursión en canoa de forma tan heroica, con un rollo de canela. Realmente legendario.'::text),
(338090,37566,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rarement une sortie en canoë ... fini de façon aussi héroïque, par un roulé à la cannelle. Vraiment légendaire.'::text,'a'::text,'a'::text,'ont'::text,'Rarement une sortie en canoë a fini de façon aussi héroïque, par un roulé à la cannelle. Vraiment légendaire.'::text),
(338093,37566,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nadiren ... bir kano gezisi bu kadar kahramanca sona ermiştir: bir tarçınlı çörekle. Gerçekten efsanevi.'::text,''::text,NULL::text,NULL::text,'Nadiren bir kano gezisi bu kadar kahramanca sona ermiştir: bir tarçınlı çörekle. Gerçekten efsanevi.'::text),
(338094,37566,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ritkán ... ért véget egy kenutúra ilyen hősiesen: egy fahéjas csigában. Igazán legendás.'::text,''::text,NULL::text,NULL::text,'Ritkán ért véget egy kenutúra ilyen hősiesen: egy fahéjas csigában. Igazán legendás.'::text),
(338097,37567,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein echter Profi: Er ließ das Kanu zum Steg ..., bevor er Schnecken holen ging.'::text,'ziehen'::text,'ziehen'::text,'zu ziehen'::text,'Ein echter Profi: Er ließ das Kanu zum Steg ziehen, bevor er Schnecken holen ging.'::text),
(338101,37567,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Справжній профі: він доручив ... каное до причалу, перш ніж піти по булочки.'::text,'витягти'::text,'витягти'::text,'витягти'::text,'Справжній профі: він доручив витягти каное до причалу, перш ніж піти по булочки.'::text),
(338100,37567,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Todo un profesional: hizo ... la canoa hasta el muelle antes de irse a por bollos.'::text,'sacar'::text,'sacar'::text,'sacar'::text,'Todo un profesional: hizo sacar la canoa hasta el muelle antes de irse a por bollos.'::text),
(338099,37567,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un vrai pro : il a fait ... le canoë jusqu''au quai avant de partir chercher des brioches.'::text,'tirer'::text,'tirer'::text,'tirer'::text,'Un vrai pro : il a fait tirer le canoë jusqu''au quai avant de partir chercher des brioches.'::text),
(338102,37567,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tam bir profesyonel: çörek almaya gitmeden önce kanoyu iskeleye ...'::text,'çektirdi'::text,'çektirdi'::text,'çektirdi'::text,'Tam bir profesyonel: çörek almaya gitmeden önce kanoyu iskeleye çektirdi.'::text),
(338103,37567,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Igazi profi: a kenut a stéghez ..., mielőtt elment csigáért.'::text,'húzatta ki'::text,'húzatta ki'::text,'húzatta ki'::text,'Igazi profi: a kenut a stéghez húzatta ki, mielőtt elment csigáért.'::text),
(338106,37568,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Kanuausflug ist für immer vorbei! Er wünschte, er ... noch draußen auf dem Wasser!'::text,'wäre'::text,'ist'::text,'wäre'::text,'Der Kanuausflug ist für immer vorbei! Er wünschte, er wäre noch draußen auf dem Wasser!'::text),
(338110,37568,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подорож на каное скінчилася назавжди! Він хотів би, щоб він ... досі на воді!'::text,'був'::text,'є'::text,'був би'::text,'Подорож на каное скінчилася назавжди! Він хотів би, щоб він був досі на воді!'::text),
(338109,37568,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La excursión en canoa se acabó para siempre! ¡Ojalá ... todavía en el agua!'::text,'estuviera'::text,'está'::text,'estaría'::text,'¡La excursión en canoa se acabó para siempre! ¡Ojalá estuviera todavía en el agua!'::text),
(338108,37568,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La sortie en canoë est finie pour toujours ! Si seulement il ... encore sur l''eau !'::text,'était'::text,'est'::text,'serait'::text,'La sortie en canoë est finie pour toujours ! Si seulement il était encore sur l''eau !'::text),
(338111,37568,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kano gezisi sonsuza dek bitti! Keşke hâlâ suda ...!'::text,'olsa'::text,'olur'::text,'olacak'::text,'Kano gezisi sonsuza dek bitti! Keşke hâlâ suda olsa!'::text),
(338112,37568,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kenutúra örökre véget ért! Bárcsak még mindig a vízen ...!'::text,'lenne'::text,'van'::text,'lesz'::text,'A kenutúra örökre véget ért! Bárcsak még mindig a vízen lenne!'::text),
(338124,37570,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er fährt ... an den roten Häusern vorbei und geht dann in die Altstadt.'::text,'per Kanu'::text,'mit einem Kanu'::text,'mit dem Kanu'::text,'Er fährt per Kanu an den roten Häusern vorbei und geht dann in die Altstadt.'::text),
(338128,37570,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він пливе ... повз червоні будиночки, а потім іде в старе місто.'::text,'на каное'::text,'на каное'::text,'на каное'::text,'Він пливе на каное повз червоні будиночки, а потім іде в старе місто.'::text),
(338127,37570,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Viaja ... junto a las casas rojas y luego entra caminando en el casco antiguo.'::text,'en canoa'::text,'en una canoa'::text,'en la canoa'::text,'Viaja en canoa junto a las casas rojas y luego entra caminando en el casco antiguo.'::text),
(338126,37570,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il se déplace ... devant les maisons rouges, puis entre à pied dans la vieille ville.'::text,'en canoë'::text,'dans un canoë'::text,'dans le canoë'::text,'Il se déplace en canoë devant les maisons rouges, puis entre à pied dans la vieille ville.'::text),
(338129,37570,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kırmızı evlerin önünden ... geçiyor, sonra eski şehre yürüyor.'::text,'kanoyla'::text,'bir kanoyla'::text,'kanoyla'::text,'Kırmızı evlerin önünden kanoyla geçiyor, sonra eski şehre yürüyor.'::text),
(338130,37570,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... halad el a piros házak mellett, aztán besétál az óvárosba.'::text,'Kenuval'::text,'Egy kenuval'::text,'A kenuval'::text,'Kenuval halad el a piros házak mellett, aztán besétál az óvárosba.'::text),
(338133,37571,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... des kalten grauen Wassers genießt er den Kanuausflug und beendet ihn mit einer Zimtschnecke.'::text,'Trotz'::text,'Obwohl'::text,'Wegen'::text,'Trotz des kalten grauen Wassers genießt er den Kanuausflug und beendet ihn mit einer Zimtschnecke.'::text),
(338137,37571,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... холодну сіру воду, він насолоджується подорожжю на каное і завершує її булочкою з корицею.'::text,'Попри'::text,'Хоча'::text,'Через'::text,'Попри холодну сіру воду, він насолоджується подорожжю на каное і завершує її булочкою з корицею.'::text),
(338136,37571,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... el agua fría y gris, disfruta de la excursión en canoa y la termina con un rollo de canela.'::text,'A pesar de'::text,'Aunque'::text,'Por'::text,'A pesar de el agua fría y gris, disfruta de la excursión en canoa y la termina con un rollo de canela.'::text),
(338135,37571,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... l''eau froide et grise, il profite de sa sortie en canoë et la termine avec un roulé à la cannelle.'::text,'Malgré'::text,'Bien que'::text,'À cause de'::text,'Malgré l''eau froide et grise, il profite de sa sortie en canoë et la termine avec un roulé à la cannelle.'::text),
(338138,37571,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soğuk gri suya ..., kano gezisinin tadını çıkarıyor ve onu bir tarçınlı çörekle bitiriyor.'::text,'rağmen'::text,'rağmen'::text,'yüzünden'::text,'Soğuk gri suya rağmen, kano gezisinin tadını çıkarıyor ve onu bir tarçınlı çörekle bitiriyor.'::text),
(338139,37571,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hideg, szürke víz ... élvezi a kenutúrát, és egy fahéjas csigával zárja.'::text,'ellenére'::text,'ellenére'::text,'miatt'::text,'A hideg, szürke víz ellenére élvezi a kenutúrát, és egy fahéjas csigával zárja.'::text),
(357456,39718,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während sie den Mast ..., rutschte ihr Blumenkranz. Absolute Katastrophe!'::text,'aufrichteten'::text,'aufrichteten'::text,'aufgerichtet haben'::text,'Während sie den Mast aufrichteten, rutschte ihr Blumenkranz. Absolute Katastrophe!'::text),
(357460,39718,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вони ... стовп, її вінок зісковзнув. Повна катастрофа!'::text,'піднімали'::text,'підняли'::text,'підняли'::text,'Поки вони піднімали стовп, її вінок зісковзнув. Повна катастрофа!'::text),
(357459,39718,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras ... el poste, se le resbaló la corona de flores. ¡Un desastre absoluto!'::text,'levantaban'::text,'levantaron'::text,'han levantado'::text,'Mientras levantaban el poste, se le resbaló la corona de flores. ¡Un desastre absoluto!'::text),
(357458,39718,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant qu''elles ... le mât, sa couronne de fleurs a glissé. Désastre absolu !'::text,'redressaient'::text,'ont redressé'::text,'ont redressé'::text,'Pendant qu''elles redressaient le mât, sa couronne de fleurs a glissé. Désastre absolu !'::text),
(357461,39718,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlar direği ... çiçek tacı kaydı. Tam bir felaket!'::text,'dikerken'::text,'diktiler'::text,'diktiler'::text,'Onlar direği dikerken çiçek tacı kaydı. Tam bir felaket!'::text),
(357462,39718,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben ... a rudat, lecsúszott a virágkoszorúja. Totális katasztrófa!'::text,'állították fel'::text,'felállították'::text,'felállították'::text,'Miközben állították fel a rudat, lecsúszott a virágkoszorúja. Totális katasztrófa!'::text),
(357465,39719,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... seit dem Morgengrauen Kränze, und jetzt droht der Wind, alle zu zerstören!'::text,'binden'::text,'binden'::text,'binden'::text,'Sie binden seit dem Morgengrauen Kränze, und jetzt droht der Wind, alle zu zerstören!'::text),
(357469,39719,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... вінки з самого світанку, а тепер вітер погрожує знищити їх усі!'::text,'плетуть'::text,'плетуть'::text,'плетуть'::text,'Вони плетуть вінки з самого світанку, а тепер вітер погрожує знищити їх усі!'::text),
(357468,39719,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... coronas de flores desde el amanecer, y ahora el viento amenaza con destruirlas todas!'::text,'Llevan haciendo'::text,'Están haciendo'::text,'Hacen'::text,'¡Llevan haciendo coronas de flores desde el amanecer, y ahora el viento amenaza con destruirlas todas!'::text),
(357467,39719,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elles ... des couronnes depuis l''aube, et maintenant le vent menace de toutes les détruire !'::text,'font'::text,'font'::text,'font'::text,'Elles font des couronnes depuis l''aube, et maintenant le vent menace de toutes les détruire !'::text),
(357470,39719,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şafaktan beri çiçek tacı ... ve şimdi rüzgâr hepsini mahvetmekle tehdit ediyor!'::text,'yapıyorlar'::text,'yapıyorlar'::text,'yapıyorlar'::text,'Şafaktan beri çiçek tacı yapıyorlar ve şimdi rüzgâr hepsini mahvetmekle tehdit ediyor!'::text),
(357471,39719,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hajnal óta ... a koszorúkat, és most a szél azzal fenyeget, hogy mindet tönkreteszi!'::text,'fonják'::text,'fonják'::text,'fonják'::text,'Hajnal óta fonják a koszorúkat, és most a szél azzal fenyeget, hogy mindet tönkreteszi!'::text),
(357474,39720,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, angeblich ... sie gerade das rote Band fest, als ihr Kranz in den See fiel.'::text,'band'::text,'band'::text,'hat gebunden'::text,'Girl, angeblich band sie gerade das rote Band fest, als ihr Kranz in den See fiel.'::text),
(357478,39720,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, вона ... червону стрічку, коли її вінок упав в озеро.'::text,'зав''язувала'::text,'зав''язала'::text,'зав''язала'::text,'Подруго, кажуть, вона зав''язувала червону стрічку, коли її вінок упав в озеро.'::text),
(357477,39720,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer ... la cinta roja cuando su corona de flores se cayó al lago.'::text,'estaba atando'::text,'ató'::text,'ha atado'::text,'Tía, al parecer estaba atando la cinta roja cuando su corona de flores se cayó al lago.'::text),
(357476,39720,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment elle ... le ruban rouge quand sa couronne est tombée dans le lac.'::text,'nouait'::text,'a noué'::text,'a noué'::text,'Meuf, apparemment elle nouait le ruban rouge quand sa couronne est tombée dans le lac.'::text),
(357479,39720,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, güya göle çiçek tacı düştüğünde kırmızı kurdeleyi ...'::text,'bağlıyormuş'::text,'bağlamış'::text,'bağlamış'::text,'Kızım, güya göle çiçek tacı düştüğünde kırmızı kurdeleyi bağlıyormuş.'::text),
(357480,39720,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag éppen ... a piros szalagot, amikor a koszorúja a tóba esett.'::text,'kötötte'::text,'megkötötte'::text,'megkötötte'::text,'Csajszi, állítólag éppen kötötte a piros szalagot, amikor a koszorúja a tóba esett.'::text),
(357483,39721,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, angeblich hat sie heute Abend schon drei Kränze ...'::text,'gebunden'::text,'gebunden'::text,'gebunden'::text,'Hör zu, angeblich hat sie heute Abend schon drei Kränze gebunden.'::text),
(357487,39721,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, вона сьогодні ввечері вже ... три вінки.'::text,'сплела'::text,'плела'::text,'сплела'::text,'Слухай, кажуть, вона сьогодні ввечері вже сплела три вінки.'::text),
(357486,39721,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer ya ... tres coronas de flores esta tarde.'::text,'ha hecho'::text,'ha estado haciendo'::text,'hizo'::text,'Oye, al parecer ya ha hecho tres coronas de flores esta tarde.'::text),
(357485,39721,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment elle ... déjà trois couronnes ce soir.'::text,'a fait'::text,'fait'::text,'a fait'::text,'Écoute, apparemment elle a fait déjà trois couronnes ce soir.'::text),
(357488,39721,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, güya bu akşam şimdiden üç çiçek tacı ...'::text,'yapmış'::text,'yapıyormuş'::text,'yapmış'::text,'Dinle, güya bu akşam şimdiden üç çiçek tacı yapmış.'::text),
(357489,39721,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag ma este már három koszorút ...'::text,'font'::text,'fonogat'::text,'font'::text,'Figyelj, állítólag ma este már három koszorút font.'::text),
(357492,39722,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, ich hab gehört, als der Mast stand, hatte sich schon jeder einen Kranz ...'::text,'aufgesetzt'::text,'aufgesetzt'::text,'aufgesetzt'::text,'Bestie, ich hab gehört, als der Mast stand, hatte sich schon jeder einen Kranz aufgesetzt.'::text),
(357496,39722,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що поки стовп поставили, кожна вже ... вінок.'::text,'наділа'::text,'наділа'::text,'наділа'::text,'Подруго, я чула, що поки стовп поставили, кожна вже наділа вінок.'::text),
(357495,39722,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, he oído que para cuando levantaron el poste, todo el mundo ya ... una corona de flores.'::text,'se había puesto'::text,'se ha puesto'::text,'se puso'::text,'Amiga, he oído que para cuando levantaron el poste, todo el mundo ya se había puesto una corona de flores.'::text),
(357494,39722,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, il paraît qu''au moment où le mât s''est dressé, tout le monde ... une couronne.'::text,'avait mis'::text,'a mis'::text,'a mis'::text,'Ma belle, il paraît qu''au moment où le mât s''est dressé, tout le monde avait mis une couronne.'::text),
(357497,39722,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duyduğuma göre direk dikildiğinde herkes çoktan bir çiçek tacı ...'::text,'takmıştı'::text,'taktı'::text,'taktı'::text,'Kanka, duyduğuma göre direk dikildiğinde herkes çoktan bir çiçek tacı takmıştı.'::text),
(357498,39722,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, mire felállt a rúd, már mindenki ... egy koszorút.'::text,'feltett'::text,'feltett'::text,'feltett'::text,'Csajszi, azt hallottam, mire felállt a rúd, már mindenki feltett egy koszorút.'::text),
(357510,39724,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, mit dem Kranz ... du bestimmt den ganzen Tanz an.'::text,'führst'::text,'führst'::text,'führst'::text,'Ehrlich, mit dem Kranz führst du bestimmt den ganzen Tanz an.'::text),
(357514,39724,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, з цим вінком ти точно ... весь танець.'::text,'поведеш'::text,'вестимеш'::text,'ведеш'::text,'Чесно, з цим вінком ти точно поведеш весь танець.'::text),
(357513,39724,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'De verdad, con esa corona de flores seguro que ... todo el baile.'::text,'liderarás'::text,'estarás liderando'::text,'lideras'::text,'De verdad, con esa corona de flores seguro que liderarás todo el baile.'::text),
(357512,39724,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, avec cette couronne, je suis sûr que tu ... toute la danse.'::text,'mèneras'::text,'seras en train de mener'::text,'mènes'::text,'Franchement, avec cette couronne, je suis sûr que tu mèneras toute la danse.'::text),
(357515,39724,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, o çiçek tacıyla bütün dansı eminim sen ...'::text,'yöneteceksin'::text,'yönetiyor olacaksın'::text,'yönetiyorsun'::text,'Açıkçası, o çiçek tacıyla bütün dansı eminim sen yöneteceksin.'::text),
(357516,39724,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ezzel a koszorúval biztos te ... az egész táncot.'::text,'vezeted majd'::text,'fogod vezetni'::text,'vezeted'::text,'Őszintén, ezzel a koszorúval biztos te vezeted majd az egész táncot.'::text),
(357519,39725,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn du dir einen Kranz auf den Kopf ..., wirst du natürlich sofort zur perfekten Tänzerin.'::text,'setzt'::text,'setzen wirst'::text,'setzen würdest'::text,'Wenn du dir einen Kranz auf den Kopf setzt, wirst du natürlich sofort zur perfekten Tänzerin.'::text),
(357523,39725,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо ти ... вінок на голову, ти, звісно, стаєш ідеальною танцівницею.'::text,'кладеш'::text,'покладеш'::text,'поклала б'::text,'Якщо ти кладеш вінок на голову, ти, звісно, стаєш ідеальною танцівницею.'::text),
(357522,39725,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si te ... una corona de flores en la cabeza, obviamente te conviertes en una bailarina perfecta.'::text,'pones'::text,'pondrás'::text,'pondrías'::text,'Si te pones una corona de flores en la cabeza, obviamente te conviertes en una bailarina perfecta.'::text),
(357521,39725,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tu ... une couronne sur la tête, tu deviens évidemment une danseuse parfaite.'::text,'mets'::text,'mettras'::text,'mettrais'::text,'Si tu mets une couronne sur la tête, tu deviens évidemment une danseuse parfaite.'::text),
(357524,39725,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Başına bir çiçek tacı ..., tabii ki mükemmel bir dansçı olursun.'::text,'takarsan'::text,'takacaksan'::text,'taksaydın'::text,'Başına bir çiçek tacı takarsan, tabii ki mükemmel bir dansçı olursun.'::text),
(357525,39725,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha koszorút ... a fejedre, nyilván tökéletes táncos leszel.'::text,'teszel'::text,'tenni fogsz'::text,'tennél'::text,'Ha koszorút teszel a fejedre, nyilván tökéletes táncos leszel.'::text),
(357528,39726,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Wind ruhig bleibt, ... ihr Kranz während des Tanzes auf dem Kopf.'::text,'bleibt'::text,'bliebe'::text,'blieb'::text,'Wenn der Wind ruhig bleibt, bleibt ihr Kranz während des Tanzes auf dem Kopf.'::text),
(357532,39726,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вітер буде тихим, її вінок ... на голові під час танцю.'::text,'залишиться'::text,'залишився б'::text,'залишився'::text,'Якщо вітер буде тихим, її вінок залишиться на голові під час танцю.'::text),
(357531,39726,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el viento sigue en calma, su corona de flores ... en su cabeza durante el baile.'::text,'seguirá'::text,'seguiría'::text,'siguió'::text,'Si el viento sigue en calma, su corona de flores seguirá en su cabeza durante el baile.'::text),
(357530,39726,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le vent reste calme, sa couronne ... sur sa tête pendant la danse.'::text,'restera'::text,'resterait'::text,'est restée'::text,'Si le vent reste calme, sa couronne restera sur sa tête pendant la danse.'::text),
(357533,39726,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rüzgâr sakin kalırsa, çiçek tacı dans boyunca başında ...'::text,'kalacak'::text,'kalırdı'::text,'kaldı'::text,'Rüzgâr sakin kalırsa, çiçek tacı dans boyunca başında kalacak.'::text),
(357534,39726,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a szél nyugodt marad, a koszorúja a tánc alatt a fején ...'::text,'marad'::text,'maradna'::text,'maradt'::text,'Ha a szél nyugodt marad, a koszorúja a tánc alatt a fején marad.'::text),
(357537,39727,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie keinen Kranz hätte, ... sie im Kreis der Tänzer auffallen.'::text,'würde'::text,'wird'::text,'fällt'::text,'Wenn sie keinen Kranz hätte, würde sie im Kreis der Tänzer auffallen.'::text),
(357541,39727,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби в неї не було вінка, вона ... у колі танцюристів.'::text,'вирізнялася б'::text,'вирізнятиметься'::text,'вирізняється'::text,'Якби в неї не було вінка, вона вирізнялася б у колі танцюристів.'::text),
(357540,39727,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no tuviera corona de flores, ... en el círculo de bailarines.'::text,'destacaría'::text,'destacará'::text,'destaca'::text,'Si no tuviera corona de flores, destacaría en el círculo de bailarines.'::text),
(357539,39727,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle n''avait pas de couronne, elle ... dans le cercle des danseurs.'::text,'détonnerait'::text,'détonnera'::text,'détonne'::text,'Si elle n''avait pas de couronne, elle détonnerait dans le cercle des danseurs.'::text),
(357542,39727,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çiçek tacı olmasaydı, dansçıların çemberinde ...'::text,'göze batardı'::text,'göze batacak'::text,'göze batıyor'::text,'Çiçek tacı olmasaydı, dansçıların çemberinde göze batardı.'::text),
(357543,39727,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem lenne koszorúja, ... a táncosok körében.'::text,'kilógna'::text,'ki fog lógni'::text,'kilóg'::text,'Ha nem lenne koszorúja, kilógna a táncosok körében.'::text),
(357546,39728,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bevor der Tanz begann, ... sie stundenlang am See Kränze.'::text,'banden'::text,'banden'::text,'binden'::text,'Bevor der Tanz begann, banden sie stundenlang am See Kränze.'::text),
(357550,39728,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перш ніж почався танець, вони годинами ... вінки біля озера.'::text,'плели'::text,'плели'::text,'плетуть'::text,'Перш ніж почався танець, вони годинами плели вінки біля озера.'::text),
(357549,39728,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de que empezara el baile, ... horas haciendo coronas de flores junto al lago.'::text,'llevaban'::text,'estaban'::text,'llevan'::text,'Antes de que empezara el baile, llevaban horas haciendo coronas de flores junto al lago.'::text),
(357548,39728,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant que la danse commence, elles ... des couronnes depuis des heures au bord du lac.'::text,'faisaient'::text,'faisaient'::text,'font'::text,'Avant que la danse commence, elles faisaient des couronnes depuis des heures au bord du lac.'::text),
(357551,39728,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dans başlamadan önce saatlerdir gölün kenarında çiçek tacı ...'::text,'yapıyorlardı'::text,'yapıyorlardı'::text,'yapıyorlar'::text,'Dans başlamadan önce saatlerdir gölün kenarında çiçek tacı yapıyorlardı.'::text),
(357552,39728,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt elkezdődött a tánc, órák óta ... a koszorúkat a tó partján.'::text,'fonták'::text,'fonták'::text,'fonják'::text,'Mielőtt elkezdődött a tánc, órák óta fonták a koszorúkat a tó partján.'::text),
(351507,39057,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich hab gehört, der Teig ... über die Schüssel hinaus, während sie auf den Ball schauten, Bestie.'::text,'quoll'::text,'quoll'::text,'ist gequollen'::text,'Ich hab gehört, der Teig quoll über die Schüssel hinaus, während sie auf den Ball schauten, Bestie.'::text),
(351511,39057,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Я чула, що тісто ... через край миски, поки вони дивилися на м''яч, подруго.'::text,'розросталося'::text,'розрослося'::text,'розрослося'::text,'Я чула, що тісто розросталося через край миски, поки вони дивилися на м''яч, подруго.'::text),
(351510,39057,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'He oído que la masa ... por encima del bol mientras miraban la pelota, amiga.'::text,'estaba creciendo'::text,'creció'::text,'ha crecido'::text,'He oído que la masa estaba creciendo por encima del bol mientras miraban la pelota, amiga.'::text),
(351509,39057,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il paraît que la pâte ... par-dessus le bol pendant qu''ils regardaient le ballon, ma belle.'::text,'gonflait'::text,'a gonflé'::text,'a gonflé'::text,'Il paraît que la pâte gonflait par-dessus le bol pendant qu''ils regardaient le ballon, ma belle.'::text),
(351512,39057,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Duyduğuma göre onlar topa bakarken hamur kâsenin üstüne doğru ..., kanka.'::text,'kabarıyormuş'::text,'kabarmış'::text,'kabarmış'::text,'Duyduğuma göre onlar topa bakarken hamur kâsenin üstüne doğru kabarıyormuş, kanka.'::text),
(351513,39057,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt hallottam, hogy a tészta ... a tálon túl, miközben a labdát nézték, csajszi.'::text,'dagadt'::text,'megdagadt'::text,'megdagadt'::text,'Azt hallottam, hogy a tészta dagadt a tálon túl, miközben a labdát nézték, csajszi.'::text),
(351516,39058,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... schon seit zehn Minuten zu, wie der Pool größer wird, und deine Geduld ist beeindruckend.'::text,'schaust'::text,'schaust'::text,'schaust'::text,'Ehrlich, du schaust schon seit zehn Minuten zu, wie der Pool größer wird, und deine Geduld ist beeindruckend.'::text),
(351520,39058,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти вже десять хвилин ..., як басейн розширюється, і твоє терпіння вражає.'::text,'дивишся'::text,'дивишся'::text,'дивишся'::text,'Чесно, ти вже десять хвилин дивишся, як басейн розширюється, і твоє терпіння вражає.'::text),
(351519,39058,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, ... diez minutos viendo cómo se agranda la piscina, y tu paciencia impresiona.'::text,'llevas'::text,'estás'::text,'pasas'::text,'La verdad, llevas diez minutos viendo cómo se agranda la piscina, y tu paciencia impresiona.'::text),
(351518,39058,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, ça fait dix minutes que tu ... la piscine gonfler, et ta patience est impressionnante.'::text,'regardes'::text,'regardes'::text,'regardes'::text,'Franchement, ça fait dix minutes que tu regardes la piscine gonfler, et ta patience est impressionnante.'::text),
(351521,39058,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, on dakikadır havuzun büyümesini ... ve sabrın etkileyici.'::text,'izliyorsun'::text,'izliyorsun'::text,'izliyorsun'::text,'Açıkçası, on dakikadır havuzun büyümesini izliyorsun ve sabrın etkileyici.'::text),
(351522,39058,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, már tíz perce ..., ahogy a medence tágul, és lenyűgöző a türelmed.'::text,'nézed'::text,'nézed'::text,'nézed'::text,'Őszintén, már tíz perce nézed, ahogy a medence tágul, és lenyűgöző a türelmed.'::text),
(351525,39059,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... gerade zu, wie der Ball größer wurde, als neben dir der Teig aufging. Lässige Reaktion, ehrlich.'::text,'schautest'::text,'schautest'::text,'hast geschaut'::text,'Du schautest gerade zu, wie der Ball größer wurde, als neben dir der Teig aufging. Lässige Reaktion, ehrlich.'::text),
(351529,39059,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ..., як м''яч роздувається, коли поруч із тобою піднялося тісто. Плавна реакція, чесно.'::text,'дивився'::text,'подивився'::text,'подивився'::text,'Ти дивився, як м''яч роздувається, коли поруч із тобою піднялося тісто. Плавна реакція, чесно.'::text),
(351528,39059,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... cómo se inflaba la pelota cuando la masa subió a tu lado. Reacción elegante, la verdad.'::text,'Estabas mirando'::text,'Miraste'::text,'Has mirado'::text,'Estabas mirando cómo se inflaba la pelota cuando la masa subió a tu lado. Reacción elegante, la verdad.'::text),
(351527,39059,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... le ballon gonfler quand la pâte a levé à côté de toi. Réaction stylée, franchement.'::text,'regardais'::text,'as regardé'::text,'as regardé'::text,'Tu regardais le ballon gonfler quand la pâte a levé à côté de toi. Réaction stylée, franchement.'::text),
(351530,39059,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yanında hamur kabardığında topun büyümesini ...: havalı tepki, açıkçası.'::text,'izliyordun'::text,'izledin'::text,'izledin'::text,'Yanında hamur kabardığında topun büyümesini izliyordun: havalı tepki, açıkçası.'::text),
(351531,39059,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp ..., ahogy a labda nő, amikor melletted megkelt a tészta. Laza reakció, őszintén.'::text,'nézted'::text,'megnézted'::text,'megnézted'::text,'Épp nézted, ahogy a labda nő, amikor melletted megkelt a tészta. Laza reakció, őszintén.'::text),
(351534,39060,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Teig ... heute schon zweimal über den Rand. Eindeutig ein makelloses Rezept.'::text,'quoll'::text,'quoll'::text,'quoll'::text,'Der Teig quoll heute schon zweimal über den Rand. Eindeutig ein makelloses Rezept.'::text),
(351538,39060,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тісто вже двічі сьогодні ... через край. Явно бездоганний рецепт.'::text,'вилізло'::text,'вилазило'::text,'вилізло'::text,'Тісто вже двічі сьогодні вилізло через край. Явно бездоганний рецепт.'::text),
(351537,39060,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La masa ... por encima del borde dos veces hoy. Está claro que es una receta impecable.'::text,'ha crecido'::text,'ha estado creciendo'::text,'creció'::text,'La masa ha crecido por encima del borde dos veces hoy. Está claro que es una receta impecable.'::text),
(351536,39060,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pâte ... déjà deux fois par-dessus le bord aujourd''hui. Une recette clairement parfaite.'::text,'a débordé'::text,'déborde'::text,'a débordé'::text,'La pâte a débordé déjà deux fois par-dessus le bord aujourd''hui. Une recette clairement parfaite.'::text),
(351539,39060,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hamur bugün şimdiden iki kez kenardan ...: belli ki kusursuz bir tarif.'::text,'taştı'::text,'taşıyor'::text,'taştı'::text,'Hamur bugün şimdiden iki kez kenardan taştı: belli ki kusursuz bir tarif.'::text),
(351540,39060,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tészta ma már kétszer ... a peremen. Nyilvánvalóan hibátlan recept.'::text,'dagadt túl'::text,'dagad túl'::text,'dagadt túl'::text,'A tészta ma már kétszer dagadt túl a peremen. Nyilvánvalóan hibátlan recept.'::text),
(351552,39062,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, wenn die Burg noch größer ..., blockiert sie den ganzen Garten, echt jetzt.'::text,'wird'::text,'werden wird'::text,'wurde'::text,'Digga, wenn die Burg noch größer wird, blockiert sie den ganzen Garten, echt jetzt.'::text),
(351556,39062,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, якщо цей замок ще ..., він перекриє весь сад, реально.'::text,'збільшиться'::text,'збільшиться'::text,'збільшився'::text,'Бро, якщо цей замок ще збільшиться, він перекриє весь сад, реально.'::text),
(351555,39062,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, si ese castillo ... más, va a tapar todo el jardín, en serio.'::text,'crece'::text,'crecerá'::text,'creció'::text,'Bro, si ese castillo crece más, va a tapar todo el jardín, en serio.'::text),
(351554,39062,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, si ce château ... encore, il va bloquer tout le jardin, sérieux.'::text,'gonfle'::text,'gonflera'::text,'gonflait'::text,'Frère, si ce château gonfle encore, il va bloquer tout le jardin, sérieux.'::text),
(351557,39062,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o şato biraz daha ..., bütün bahçeyi kapatacak, cidden.'::text,'büyürse'::text,'büyüyecekse'::text,'büyüdüyse'::text,'Kanka, o şato biraz daha büyürse, bütün bahçeyi kapatacak, cidden.'::text),
(351558,39062,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha az a vár még tovább ..., elzárja az egész kertet, komolyan.'::text,'nő'::text,'fog nőni'::text,'nőtt'::text,'Tesó, ha az a vár még tovább nő, elzárja az egész kertet, komolyan.'::text),
(351561,39063,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Wasserball noch größer würde, ... er über den Gartenzaun.'::text,'schwebte'::text,'schwebt'::text,'schwebt'::text,'Wenn der Wasserball noch größer würde, schwebte er über den Gartenzaun.'::text),
(351565,39063,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби пляжний м''яч ще збільшився, він ... над садовим парканом.'::text,'перелетів би'::text,'перелетить'::text,'летить'::text,'Якби пляжний м''яч ще збільшився, він перелетів би над садовим парканом.'::text),
(351564,39063,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la pelota de playa se inflara más, ... por encima de la valla del jardín.'::text,'flotaría'::text,'flotará'::text,'flota'::text,'Si la pelota de playa se inflara más, flotaría por encima de la valla del jardín.'::text),
(351563,39063,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le ballon de plage gonflait encore, il ... par-dessus la clôture du jardin.'::text,'s''envolerait'::text,'s''envolera'::text,'s''envole'::text,'Si le ballon de plage gonflait encore, il s''envolerait par-dessus la clôture du jardin.'::text),
(351566,39063,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plaj topu biraz daha büyüseydi, bahçe çitinin üstünden ...'::text,'uçardı'::text,'uçacak'::text,'uçuyor'::text,'Plaj topu biraz daha büyüseydi, bahçe çitinin üstünden uçardı.'::text),
(351567,39063,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a strandlabda még tovább nőne, ... a kerítés fölött.'::text,'lebegne'::text,'lebegni fog'::text,'lebeg'::text,'Ha a strandlabda még tovább nőne, lebegne a kerítés fölött.'::text),
(351570,39064,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als sie die Pumpe einschalteten, wussten sie, dass sich die Burg zu voller Größe ...'::text,'aufblähen würde'::text,'aufblähen wird'::text,'aufbläht'::text,'Als sie die Pumpe einschalteten, wussten sie, dass sich die Burg zu voller Größe aufblähen würde.'::text),
(351574,39064,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли вони ввімкнули насос, то знали, що замок ... до повного розміру.'::text,'роздується'::text,'роздується'::text,'роздувається'::text,'Коли вони ввімкнули насос, то знали, що замок роздується до повного розміру.'::text),
(351573,39064,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando encendieron la bomba, sabían que el castillo ... hasta su tamaño completo.'::text,'se inflaría'::text,'se inflará'::text,'se infla'::text,'Cuando encendieron la bomba, sabían que el castillo se inflaría hasta su tamaño completo.'::text),
(351572,39064,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand ils ont allumé la pompe, ils savaient que le château ... jusqu''à sa taille maximale.'::text,'gonflerait'::text,'gonflera'::text,'gonfle'::text,'Quand ils ont allumé la pompe, ils savaient que le château gonflerait jusqu''à sa taille maximale.'::text),
(351575,39064,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pompayı açtıklarında şatonun tam boyutuna ... biliyorlardı.'::text,'ulaşacağını'::text,'ulaşacağını'::text,'ulaştığını'::text,'Pompayı açtıklarında şatonun tam boyutuna ulaşacağını biliyorlardı.'::text),
(351576,39064,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amikor bekapcsolták a pumpát, tudták, hogy a vár teljes méretére ...'::text,'fog nőni'::text,'fog nőni'::text,'nő'::text,'Amikor bekapcsolták a pumpát, tudták, hogy a vár teljes méretére fog nőni.'::text),
(351588,39066,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also angeblich ... sich die Hüpfburg fünf Minuten lang auf, bevor irgendwer ein Wort sagte.'::text,'blähte'::text,'bläht'::text,'bläht'::text,'Okay, also angeblich blähte sich die Hüpfburg fünf Minuten lang auf, bevor irgendwer ein Wort sagte.'::text),
(351592,39066,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Отже, кажуть, надувний замок ... п''ять хвилин, перш ніж хтось сказав хоч слово.'::text,'роздувався'::text,'роздувається'::text,'роздувається'::text,'Отже, кажуть, надувний замок роздувався п''ять хвилин, перш ніж хтось сказав хоч слово.'::text),
(351591,39066,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, al parecer el castillo hinchable ... cinco minutos antes de que nadie dijera nada.'::text,'llevaba inflándose'::text,'lleva inflándose'::text,'se está inflando'::text,'Vale, al parecer el castillo hinchable llevaba inflándose cinco minutos antes de que nadie dijera nada.'::text),
(351590,39066,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, apparemment le château gonflable ... depuis cinq minutes avant que quelqu''un dise un mot.'::text,'gonflait'::text,'gonfle'::text,'gonfle'::text,'Bon, apparemment le château gonflable gonflait depuis cinq minutes avant que quelqu''un dise un mot.'::text),
(351593,39066,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, güya kimse tek kelime etmeden önce şişme şato beş dakikadır ...'::text,'büyüyormuş'::text,'büyüyor'::text,'büyüyor'::text,'Tamam, güya kimse tek kelime etmeden önce şişme şato beş dakikadır büyüyormuş.'::text),
(351594,39066,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval állítólag az ugrálóvár öt percig ..., mielőtt bárki megszólalt volna.'::text,'nőtt'::text,'nő'::text,'nő'::text,'Oké, szóval állítólag az ugrálóvár öt percig nőtt, mielőtt bárki megszólalt volna.'::text),
(351597,39067,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, angeblich wird die Hüpfburg bis zwei Uhr ihre volle Größe ...'::text,'erreicht haben'::text,'erreichen'::text,'erreicht'::text,'Hör zu, angeblich wird die Hüpfburg bis zwei Uhr ihre volle Größe erreicht haben.'::text),
(351601,39067,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, до другої години надувний замок ... до повного розміру.'::text,'роздується'::text,'роздується'::text,'роздувається'::text,'Слухай, кажуть, до другої години надувний замок роздується до повного розміру.'::text),
(351600,39067,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer para las dos el castillo hinchable ... hasta su tamaño completo.'::text,'se habrá inflado'::text,'se inflará'::text,'se infla'::text,'Oye, al parecer para las dos el castillo hinchable se habrá inflado hasta su tamaño completo.'::text),
(351599,39067,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment d''ici deux heures, le château gonflable ... jusqu''à sa taille maximale.'::text,'aura gonflé'::text,'gonflera'::text,'gonfle'::text,'Écoute, apparemment d''ici deux heures, le château gonflable aura gonflé jusqu''à sa taille maximale.'::text),
(351602,39067,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, güya saat ikiye kadar şişme şato tam boyutuna ...'::text,'ulaşmış olacakmış'::text,'ulaşacakmış'::text,'ulaşıyormuş'::text,'Dinle, güya saat ikiye kadar şişme şato tam boyutuna ulaşmış olacakmış.'::text),
(351603,39067,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag kettőre az ugrálóvár ... teljes méretére.'::text,'megnő majd'::text,'megnő'::text,'nő'::text,'Figyelj, állítólag kettőre az ugrálóvár megnő majd teljes méretére.'::text),
(385410,42824,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, er hat mir gesagt, das Wasser war flach, und ...'::text,'der Hafen auch'::text,'der Hafen auch'::text,'der Hafen auch nicht'::text,'Girl, er hat mir gesagt, das Wasser war flach, und der Hafen auch.'::text),
(385414,42824,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він сказав мені, що вода була мілка, і ...'::text,'у гавані теж'::text,'у гавані теж'::text,'у гавані теж ні'::text,'Подруго, він сказав мені, що вода була мілка, і у гавані теж.'::text),
(385413,42824,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me dijo que el agua era poco profunda, y ...'::text,'el puerto también'::text,'el puerto también'::text,'el puerto tampoco'::text,'Tía, me dijo que el agua era poco profunda, y el puerto también.'::text),
(385412,42824,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, il m''a dit que l''eau était peu profonde, et ...'::text,'le port aussi'::text,'le port aussi'::text,'le port non plus'::text,'Meuf, il m''a dit que l''eau était peu profonde, et le port aussi.'::text),
(385415,42824,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bana suyun sığ olduğunu söyledi, ...'::text,'limanınki de öyle'::text,'limanınki de öyle'::text,'limanınki de değil'::text,'Kızım, bana suyun sığ olduğunu söyledi, limanınki de öyle.'::text),
(385416,42824,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, hogy sekély volt a víz, és ...'::text,'a kikötő is'::text,'a kikötő is'::text,'a kikötő sem'::text,'Csajszi, azt mondta, hogy sekély volt a víz, és a kikötő is.'::text),
(385419,42825,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also er behauptet, dass er bis Mittag zehn Kilometer im flachen Wasser ...'::text,'geschwommen sein wird'::text,'schwimmen wird'::text,'am Schwimmen sein wird'::text,'Okay, also er behauptet, dass er bis Mittag zehn Kilometer im flachen Wasser geschwommen sein wird.'::text),
(385423,42825,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Отже, він стверджує, що до полудня ... десять кілометрів у мілкій воді.'::text,'пропливе'::text,'пропливе'::text,'пливтиме'::text,'Отже, він стверджує, що до полудня пропливе десять кілометрів у мілкій воді.'::text),
(385422,42825,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, dice que para el mediodía ... diez kilómetros en aguas poco profundas.'::text,'habrá nadado'::text,'nadará'::text,'estará nadando'::text,'Vale, dice que para el mediodía habrá nadado diez kilómetros en aguas poco profundas.'::text),
(385421,42825,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, il prétend que d''ici midi il ... dix kilomètres en eau peu profonde.'::text,'aura nagé'::text,'nagera'::text,'sera en train de nager'::text,'Bon, il prétend que d''ici midi il aura nagé dix kilomètres en eau peu profonde.'::text),
(385424,42825,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, öğlene kadar sığ suda on kilometre ... iddia ediyor.'::text,'yüzmüş olacağını'::text,'yüzeceğini'::text,'yüzüyor olacağını'::text,'Tamam, öğlene kadar sığ suda on kilometre yüzmüş olacağını iddia ediyor.'::text),
(385425,42825,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval azt állítja, hogy délre tíz kilométert ... sekély vízben.'::text,'leúszik majd'::text,'úszik'::text,'fog úszni'::text,'Oké, szóval azt állítja, hogy délre tíz kilométert leúszik majd sekély vízben.'::text),
(385428,42826,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, wenn das Wasser nicht flach gewesen wäre, ... er sich nicht auf den Sand gekniet, echt jetzt.'::text,'hätte'::text,'wird'::text,'hat'::text,'Yo, wenn das Wasser nicht flach gewesen wäre, hätte er sich nicht auf den Sand gekniet, echt jetzt.'::text),
(385432,42826,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, якби вода не була мілкою, він ... на той пісок, реально.'::text,'не став би на коліна'::text,'не стане на коліна'::text,'не став на коліна'::text,'Йо, якби вода не була мілкою, він не став би на коліна на той пісок, реально.'::text),
(385431,42826,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, si el agua no hubiera sido poco profunda, no ... en esa arena, en serio.'::text,'se habría arrodillado'::text,'se arrodillará'::text,'se arrodilló'::text,'Oye, si el agua no hubiera sido poco profunda, no se habría arrodillado en esa arena, en serio.'::text),
(385430,42826,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, si l''eau n''avait pas été peu profonde, il ... sur ce sable, sérieux.'::text,'ne se serait pas agenouillé'::text,'ne s''agenouillera pas'::text,'ne s''est pas agenouillé'::text,'Yo, si l''eau n''avait pas été peu profonde, il ne se serait pas agenouillé sur ce sable, sérieux.'::text),
(385433,42826,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, su sığ olmasaydı o kuma diz ..., cidden.'::text,'çökmezdi'::text,'çökmeyecek'::text,'çökmedi'::text,'Kanka, su sığ olmasaydı o kuma diz çökmezdi, cidden.'::text),
(385434,42826,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, ha nem lett volna sekély a víz, nem ... le arra a homokra, komolyan.'::text,'térdelt volna'::text,'fog letérdelni'::text,'térdelt'::text,'Figyu, ha nem lett volna sekély a víz, nem térdelt volna le arra a homokra, komolyan.'::text),
(385437,42827,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, er hat zugegeben, den flachen Teil absichtlich ... zu haben, ehrlich.'::text,'gewählt'::text,'wählen'::text,'wählte'::text,'Alter, er hat zugegeben, den flachen Teil absichtlich gewählt zu haben, ehrlich.'::text),
(385441,42827,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, він зізнався, що ... мілку частину навмисно, без брехні.'::text,'вибрав'::text,'вибрати'::text,'вибрав'::text,'Чувак, він зізнався, що вибрав мілку частину навмисно, без брехні.'::text),
(385440,42827,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, admitió ... la parte poco profunda a propósito, en serio.'::text,'haber elegido'::text,'elegir'::text,'eligió'::text,'Tío, admitió haber elegido la parte poco profunda a propósito, en serio.'::text),
(385439,42827,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, il a avoué ... la partie peu profonde exprès, sans mentir.'::text,'avoir choisi'::text,'choisir'::text,'a choisi'::text,'Mec, il a avoué avoir choisi la partie peu profonde exprès, sans mentir.'::text),
(385442,42827,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, sığ kısmı bilerek ... itiraf etti, yalan yok.'::text,'seçtiğini'::text,'seçmeyi'::text,'seçti'::text,'Kanka, sığ kısmı bilerek seçtiğini itiraf etti, yalan yok.'::text),
(385443,42827,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, beismerte, hogy szándékosan ... a sekély részt, komolyan.'::text,'választotta'::text,'választani'::text,'választotta'::text,'Tesó, beismerte, hogy szándékosan választotta a sekély részt, komolyan.'::text),
(385446,42828,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... dort nicht knien können, wenn das Wasser nicht flach gewesen wäre.'::text,'hätte'::text,'müsste'::text,'sollte'::text,'Er hätte dort nicht knien können, wenn das Wasser nicht flach gewesen wäre.'::text),
(385450,42828,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... там стати на коліна, якби вода не була мілкою.'::text,'не зміг би'::text,'не мусив би'::text,'не мав би'::text,'Він не зміг би там стати на коліна, якби вода не була мілкою.'::text),
