(385452,42828,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem ... ott letérdelni, ha nem lett volna sekély a víz.'::text,'tudott volna'::text,'kellett volna'::text,'kellene'::text,'Nem tudott volna ott letérdelni, ha nem lett volna sekély a víz.'::text),
(385455,42829,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ließ sein Schwimmen im flachen Wasser von einem Freund ...'::text,'filmen'::text,'filmen'::text,'filmend'::text,'Er ließ sein Schwimmen im flachen Wasser von einem Freund filmen.'::text),
(385459,42829,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він попросив друга ... його заплив на мілководді.'::text,'зняти'::text,'зняти'::text,'знімаючи'::text,'Він попросив друга зняти його заплив на мілководді.'::text),
