(394878,43876,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie den Schläger kräftiger schwingt, ... der Ball weiter.'::text,'fliegt'::text,'flöge'::text,'flog'::text,'Wenn sie den Schläger kräftiger schwingt, fliegt der Ball weiter.'::text),
(394882,43876,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вона сильніше змахне ключкою, м''яч ... далі.'::text,'полетить'::text,'полетів би'::text,'полетів'::text,'Якщо вона сильніше змахне ключкою, м''яч полетить далі.'::text),
(394881,43876,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si balancea el palo con más fuerza, la bola ... más lejos.'::text,'volará'::text,'volaría'::text,'voló'::text,'Si balancea el palo con más fuerza, la bola volará más lejos.'::text),
(394880,43876,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle balance le club plus fort, la balle ... plus loin.'::text,'volera'::text,'volerait'::text,'a volé'::text,'Si elle balance le club plus fort, la balle volera plus loin.'::text),
(394883,43876,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sopayı daha sert savurursa, top daha uzağa ...'::text,'uçacak'::text,'uçardı'::text,'uçtu'::text,'Sopayı daha sert savurursa, top daha uzağa uçacak.'::text),
(394884,43876,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha erősebben lendíti az ütőt, a labda messzebbre ...'::text,'repül'::text,'repülne'::text,'repült'::text,'Ha erősebben lendíti az ütőt, a labda messzebbre repül.'::text),
(394887,43877,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie beim Schwingen loslassen würde, ... sie direkt in den See.'::text,'fiele'::text,'fällt'::text,'fällt'::text,'Wenn sie beim Schwingen loslassen würde, fiele sie direkt in den See.'::text),
(394891,43877,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона відпустила мотузку під час гойдання, то ... просто в озеро.'::text,'впала б'::text,'впаде'::text,'падає'::text,'Якби вона відпустила мотузку під час гойдання, то впала б просто в озеро.'::text),
(394890,43877,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si se soltara mientras se balancea, ... directamente al lago.'::text,'caería'::text,'caerá'::text,'cae'::text,'Si se soltara mientras se balancea, caería directamente al lago.'::text),
(394889,43877,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle lâchait prise en se balançant, elle ... droit dans le lac.'::text,'tomberait'::text,'tombera'::text,'tombe'::text,'Si elle lâchait prise en se balançant, elle tomberait droit dans le lac.'::text),
(394892,43877,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sallanırken ipi bıraksaydı, doğrudan göle ...'::text,'düşerdi'::text,'düşecek'::text,'düşüyor'::text,'Sallanırken ipi bıraksaydı, doğrudan göle düşerdi.'::text),
(394893,43877,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha lendülés közben elengedné, egyenesen a tóba ...'::text,'esne'::text,'fog esni'::text,'esik'::text,'Ha lendülés közben elengedné, egyenesen a tóba esne.'::text),
(394896,43878,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Golfschläger ... in einem weiten Bogen über ihre Schulter geschwungen.'::text,'wurde'::text,'wird'::text,'schwang'::text,'Der Golfschläger wurde in einem weiten Bogen über ihre Schulter geschwungen.'::text),
(394900,43878,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ключкою для гольфу ... широкою дугою над її плечем.'::text,'змахнули'::text,'змахують'::text,'змахнула'::text,'Ключкою для гольфу змахнули широкою дугою над її плечем.'::text),
(394899,43878,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El palo de golf ... en un amplio arco por encima de su hombro.'::text,'fue blandido'::text,'es blandido'::text,'blandió'::text,'El palo de golf fue blandido en un amplio arco por encima de su hombro.'::text),
(394898,43878,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le club de golf ... en un large arc au-dessus de son épaule.'::text,'a été balancé'::text,'est balancé'::text,'a balancé'::text,'Le club de golf a été balancé en un large arc au-dessus de son épaule.'::text),
(394901,43878,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Golf sopası omzunun üstünden geniş bir yay çizerek ...'::text,'savruldu'::text,'savruluyor'::text,'savurdu'::text,'Golf sopası omzunun üstünden geniş bir yay çizerek savruldu.'::text),
(394902,43878,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A golfütőt széles ívben ... át a vállán.'::text,'lendítették'::text,'lendítik'::text,'lendítette'::text,'A golfütőt széles ívben lendítették át a vállán.'::text),
(394905,43879,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Offensichtlich keine Angst vor Wasser: Sie ... an einem Seil über den See hinaus.'::text,'schwang'::text,'wurde geschwungen'::text,'schwingend'::text,'Offensichtlich keine Angst vor Wasser: Sie schwang an einem Seil über den See hinaus.'::text),
(394909,43879,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Очевидно, жодного страху перед водою: вона ... на мотузці над озером.'::text,'розгойдалася'::text,'була розгойдана'::text,'розгойдуючись'::text,'Очевидно, жодного страху перед водою: вона розгойдалася на мотузці над озером.'::text),
(394908,43879,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Está claro que no le teme al agua: ... sobre el lago colgada de una cuerda.'::text,'se balanceó'::text,'fue balanceada'::text,'balanceándose'::text,'Está claro que no le teme al agua: se balanceó sobre el lago colgada de una cuerda.'::text),
(394907,43879,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Clairement aucune peur de l''eau : elle ... au-dessus du lac au bout d''une corde.'::text,'s''est balancée'::text,'a été balancée'::text,'se balançant'::text,'Clairement aucune peur de l''eau : elle s''est balancée au-dessus du lac au bout d''une corde.'::text),
(394910,43879,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki sudan hiç korkmuyor: bir iple gölün üstüne doğru ...'::text,'sallandı'::text,'sallandırıldı'::text,'sallanarak'::text,'Belli ki sudan hiç korkmuyor: bir iple gölün üstüne doğru sallandı.'::text),
(394911,43879,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván semmi víziszony: egy kötélen ... ki a tó fölé.'::text,'lendült'::text,'lendítették'::text,'lendülve'::text,'Nyilván semmi víziszony: egy kötélen lendült ki a tó fölé.'::text),
(394914,43880,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie schwingt so hoch über dem See, also ... sie absolut furchtlos sein!'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Sie schwingt so hoch über dem See, also muss sie absolut furchtlos sein!'::text),
(394918,43880,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона гойдається так високо над озером, тож ... бути абсолютно безстрашною!'::text,'мусить'::text,'не може'::text,'мала б'::text,'Вона гойдається так високо над озером, тож мусить бути абсолютно безстрашною!'::text),
(394917,43880,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Se balancea tan alto sobre el lago que ... ser totalmente intrépida!'::text,'debe de'::text,'no puede'::text,'debería'::text,'¡Se balancea tan alto sobre el lago que debe de ser totalmente intrépida!'::text),
(394916,43880,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle se balance si haut au-dessus du lac qu''elle ... être totalement intrépide !'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'Elle se balance si haut au-dessus du lac qu''elle doit être totalement intrépide !'::text),
(394919,43880,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gölün üstünde o kadar yükseğe sallanıyor ki kesinlikle korkusuz ...!'::text,'olmalı'::text,'olamaz'::text,'olmalı'::text,'Gölün üstünde o kadar yükseğe sallanıyor ki kesinlikle korkusuz olmalı!'::text),
(394920,43880,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Olyan magasra lendül a tó fölött, hogy ... teljesen rettenthetetlen!'::text,'biztosan'::text,'nem lehet'::text,'elvileg'::text,'Olyan magasra lendül a tó fölött, hogy biztosan teljesen rettenthetetlen!'::text),
(394923,43881,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Seil, ... sie schwingt, könnte jeden Moment reißen! Katastrophe!'::text,'an dem'::text,'an dem'::text,'wo'::text,'Das Seil, an dem sie schwingt, könnte jeden Moment reißen! Katastrophe!'::text),
(394927,43881,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Мотузка, ... вона гойдається, може будь-якої миті порватися! Катастрофа!'::text,'на якій'::text,'на якій'::text,'де'::text,'Мотузка, на якій вона гойдається, може будь-якої миті порватися! Катастрофа!'::text),
(394926,43881,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La cuerda en ... se balancea podría romperse en cualquier momento! ¡Desastre!'::text,'la que'::text,'quien'::text,'donde'::text,'¡La cuerda en la que se balancea podría romperse en cualquier momento! ¡Desastre!'::text),
(394925,43881,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La corde à ... elle se balance pourrait lâcher à tout moment ! Catastrophe !'::text,'laquelle'::text,'qui'::text,'où'::text,'La corde à laquelle elle se balance pourrait lâcher à tout moment ! Catastrophe !'::text),
(394928,43881,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Üzerinde ... ip herhangi bir anda kopabilir! Felaket!'::text,'sallandığı'::text,'sallandığı'::text,'sallandığı'::text,'Üzerinde sallandığı ip herhangi bir anda kopabilir! Felaket!'::text),
(394929,43881,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kötél, ... hintázik, bármelyik pillanatban elszakadhat! Katasztrófa!'::text,'amelyen'::text,'akin'::text,'ahol'::text,'A kötél, amelyen hintázik, bármelyik pillanatban elszakadhat! Katasztrófa!'::text),
(394932,43882,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, sie hat mir gesagt, dass sie am nächsten Tag wieder an dem Seil ...'::text,'schwingen würde'::text,'schwingen wird'::text,'schwingt'::text,'Hör zu, sie hat mir gesagt, dass sie am nächsten Tag wieder an dem Seil schwingen würde.'::text),
(394936,43882,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, вона сказала мені, що наступного дня знову ... на тій мотузці.'::text,'погойдається'::text,'погойдається'::text,'гойдається'::text,'Слухай, вона сказала мені, що наступного дня знову погойдається на тій мотузці.'::text),
(394935,43882,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me dijo que al día siguiente ... otra vez en esa cuerda.'::text,'se columpiaría'::text,'se columpiará'::text,'se columpia'::text,'Oye, me dijo que al día siguiente se columpiaría otra vez en esa cuerda.'::text),
(394934,43882,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, elle m''a dit qu''elle ... encore à cette corde le lendemain.'::text,'se balancerait'::text,'se balancera'::text,'se balance'::text,'Écoute, elle m''a dit qu''elle se balancerait encore à cette corde le lendemain.'::text),
(394937,43882,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana ertesi gün o ipte yine ... söyledi.'::text,'sallanacağını'::text,'sallanacağını'::text,'sallandığını'::text,'Dinle, bana ertesi gün o ipte yine sallanacağını söyledi.'::text),
(394938,43882,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy másnap újra ... azon a kötélen.'::text,'hintázni fog'::text,'hintázni fog'::text,'hintázik'::text,'Figyelj, azt mondta, hogy másnap újra hintázni fog azon a kötélen.'::text),
(395076,43898,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, er ... im Dunkeln nach dem Schalter, als seine Hand ihn endlich fand, echt jetzt.'::text,'tastete'::text,'tastete'::text,'hat getastet'::text,'Alter, er tastete im Dunkeln nach dem Schalter, als seine Hand ihn endlich fand, echt jetzt.'::text),
(395080,43898,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, він ... вимикач у темряві, коли його рука нарешті його знайшла, реально.'::text,'намацував'::text,'намацав'::text,'намацав'::text,'Чувак, він намацував вимикач у темряві, коли його рука нарешті його знайшла, реально.'::text),
(395079,43898,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ... el interruptor a oscuras cuando por fin su mano lo encontró, en serio.'::text,'estaba buscando a tientas'::text,'buscó a tientas'::text,'ha buscado a tientas'::text,'Tío, estaba buscando a tientas el interruptor a oscuras cuando por fin su mano lo encontró, en serio.'::text),
(395078,43898,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, il ... l''interrupteur dans le noir quand sa main l''a enfin trouvé, sérieux.'::text,'cherchait à tâtons'::text,'a cherché à tâtons'::text,'a cherché à tâtons'::text,'Mec, il cherchait à tâtons l''interrupteur dans le noir quand sa main l''a enfin trouvé, sérieux.'::text),
(395081,43898,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, eli sonunda düğmeyi bulduğunda karanlıkta onu el yordamıyla ..., cidden.'::text,'arıyordu'::text,'aradı'::text,'aradı'::text,'Kanka, eli sonunda düğmeyi bulduğunda karanlıkta onu el yordamıyla arıyordu, cidden.'::text),
(395082,43898,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, épp ... a kapcsolót a sötétben, amikor a keze végre megtalálta, komolyan.'::text,'tapogatta'::text,'kitapogatta'::text,'kitapogatta'::text,'Tesó, épp tapogatta a kapcsolót a sötétben, amikor a keze végre megtalálta, komolyan.'::text),
(395085,43899,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dieser Schalter ... die Lichter seit 3 Jahren ohne jedes Wartungsbudget.'::text,'steuert'::text,'steuert'::text,'steuert'::text,'Dieser Schalter steuert die Lichter seit 3 Jahren ohne jedes Wartungsbudget.'::text),
(395089,43899,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цей вимикач ... світлом уже 3 роки з нульовим бюджетом на обслуговування.'::text,'керує'::text,'керує'::text,'керує'::text,'Цей вимикач керує світлом уже 3 роки з нульовим бюджетом на обслуговування.'::text),
(395088,43899,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Este interruptor ... las luces desde hace 3 años con presupuesto de mantenimiento cero.'::text,'controla'::text,'está controlando'::text,'controla'::text,'Este interruptor controla las luces desde hace 3 años con presupuesto de mantenimiento cero.'::text),
(395087,43899,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cet interrupteur ... les lumières depuis 3 ans avec un budget maintenance nul.'::text,'contrôle'::text,'contrôle'::text,'contrôle'::text,'Cet interrupteur contrôle les lumières depuis 3 ans avec un budget maintenance nul.'::text),
(395090,43899,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu düğme 3 yıldır sıfır bakım bütçesiyle ışıkları ...'::text,'kontrol ediyor'::text,'kontrol ediyor'::text,'kontrol ediyor'::text,'Bu düğme 3 yıldır sıfır bakım bütçesiyle ışıkları kontrol ediyor.'::text),
(395091,43899,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a kapcsoló 3 éve ... a világítást nulla karbantartási kerettel.'::text,'vezérli'::text,'vezérli'::text,'vezérli'::text,'Ez a kapcsoló 3 éve vezérli a világítást nulla karbantartási kerettel.'::text),
(395094,43900,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er drückte den Schalter und die Lichter ... an, weil der Schalter für die Lichter ist.'::text,'gingen'::text,'gingen gerade'::text,'gehen'::text,'Er drückte den Schalter und die Lichter gingen an, weil der Schalter für die Lichter ist.'::text),
(395098,43900,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він натиснув вимикач, і світло ..., бо вимикач — для світла.'::text,'увімкнулося'::text,'вмикалося'::text,'вмикається'::text,'Він натиснув вимикач, і світло увімкнулося, бо вимикач — для світла.'::text),
(395097,43900,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pulsó el interruptor y las luces se ..., porque el interruptor es para las luces.'::text,'encendieron'::text,'estaban encendiendo'::text,'encienden'::text,'Pulsó el interruptor y las luces se encendieron, porque el interruptor es para las luces.'::text),
(395096,43900,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a appuyé sur l''interrupteur et les lumières se ..., parce que l''interrupteur sert aux lumières.'::text,'sont allumées'::text,'allumaient'::text,'allument'::text,'Il a appuyé sur l''interrupteur et les lumières se sont allumées, parce que l''interrupteur sert aux lumières.'::text),
(395099,43900,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Düğmeye bastı ve ışıklar ..., çünkü düğme ışıklar için.'::text,'yandı'::text,'yanıyordu'::text,'yanıyor'::text,'Düğmeye bastı ve ışıklar yandı, çünkü düğme ışıklar için.'::text),
(395100,43900,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megnyomta a kapcsolót, és a lámpák ..., mert a kapcsoló a lámpákhoz van.'::text,'felkapcsolódtak'::text,'kapcsolódtak éppen fel'::text,'felkapcsolódnak'::text,'Megnyomta a kapcsolót, és a lámpák felkapcsolódtak, mert a kapcsoló a lámpákhoz van.'::text),
(395112,43902,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... den Schalter gedrückt, bevor er in die Kamera lächelte.'::text,'hatte'::text,'hat'::text,'drückt'::text,'Er hatte den Schalter gedrückt, bevor er in die Kamera lächelte.'::text),
(395116,43902,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... вимикач, перш ніж усміхнувся в камеру.'::text,'натиснув'::text,'натиснув'::text,'натискає'::text,'Він натиснув вимикач, перш ніж усміхнувся в камеру.'::text),
(395115,43902,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... el interruptor antes de sonreír a la cámara.'::text,'Había pulsado'::text,'Ha pulsado'::text,'Pulsa'::text,'Había pulsado el interruptor antes de sonreír a la cámara.'::text),
(395114,43902,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... l''interrupteur avant de sourire à la caméra.'::text,'avait appuyé sur'::text,'a appuyé sur'::text,'appuie sur'::text,'Il avait appuyé sur l''interrupteur avant de sourire à la caméra.'::text),
(395117,43902,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kameraya gülümsemeden önce düğmeye ...'::text,'basmıştı'::text,'bastı'::text,'basıyor'::text,'Kameraya gülümsemeden önce düğmeye basmıştı.'::text),
(395118,43902,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már ... a kapcsolót, mielőtt a kamerába mosolygott.'::text,'megnyomta'::text,'megnyomta'::text,'nyomja'::text,'Már megnyomta a kapcsolót, mielőtt a kamerába mosolygott.'::text),
(395121,43903,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Heute Abend um neun wird er im Dunkeln wieder nach dem Schalter ...'::text,'tasten'::text,'tasten'::text,'tastet'::text,'Heute Abend um neun wird er im Dunkeln wieder nach dem Schalter tasten.'::text),
(395125,43903,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сьогодні о дев''ятій вечора він знову ... до вимикача в темряві.'::text,'тягнутиметься'::text,'потягнеться'::text,'тягнеться'::text,'Сьогодні о дев''ятій вечора він знову тягнутиметься до вимикача в темряві.'::text),
(395124,43903,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esta noche a las nueve ... otra vez el interruptor a oscuras.'::text,'estará buscando'::text,'buscará'::text,'busca'::text,'Esta noche a las nueve estará buscando otra vez el interruptor a oscuras.'::text),
(395123,43903,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce soir à neuf heures, il ... de nouveau l''interrupteur dans le noir.'::text,'sera en train de chercher'::text,'cherchera'::text,'cherche'::text,'Ce soir à neuf heures, il sera en train de chercher de nouveau l''interrupteur dans le noir.'::text),
(395126,43903,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu akşam saat dokuzda karanlıkta yine düğmeye ...'::text,'uzanıyor olacak'::text,'uzanacak'::text,'uzanıyor'::text,'Bu akşam saat dokuzda karanlıkta yine düğmeye uzanıyor olacak.'::text),
(395127,43903,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma este kilenckor ismét a kapcsoló után ... a sötétben.'::text,'fog nyúlni'::text,'nyúl majd'::text,'nyúl'::text,'Ma este kilenckor ismét a kapcsoló után fog nyúlni a sötétben.'::text),
(395130,43904,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese Wohnung ... früher keinen Lichtschalter an der Tür! Ein echter Albtraum!'::text,'hatte'::text,'hatte'::text,'war gewohnt'::text,'Diese Wohnung hatte früher keinen Lichtschalter an der Tür! Ein echter Albtraum!'::text),
(395134,43904,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У цій квартирі ... не було вимикача біля дверей! Справжній жах!'::text,'колись'::text,'колись'::text,'звично'::text,'У цій квартирі колись не було вимикача біля дверей! Справжній жах!'::text),
(395133,43904,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Este piso ... no tener interruptor junto a la puerta! ¡Una pesadilla total!'::text,'solía'::text,'solía'::text,'estaba acostumbrado a'::text,'¡Este piso solía no tener interruptor junto a la puerta! ¡Una pesadilla total!'::text),
(395132,43904,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cet appartement ... pas d''interrupteur près de la porte ! Un vrai cauchemar !'::text,'n''avait'::text,'n''avait'::text,'n''était habitué à avoir'::text,'Cet appartement n''avait pas d''interrupteur près de la porte ! Un vrai cauchemar !'::text),
(395135,43904,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu dairede eskiden kapının yanında ışık düğmesi ...! Tam bir kâbus!'::text,'yoktu'::text,'yoktu'::text,'olmamaya alışkındı'::text,'Bu dairede eskiden kapının yanında ışık düğmesi yoktu! Tam bir kâbus!'::text),
(395136,43904,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ebben a lakásban ... nem volt villanykapcsoló az ajtó mellett! Tiszta rémálom!'::text,'régen'::text,'régen'::text,'megszokottan'::text,'Ebben a lakásban régen nem volt villanykapcsoló az ajtó mellett! Tiszta rémálom!'::text),
(395139,43905,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wird nie vergessen, wie er den Schalter in völliger Dunkelheit ...!'::text,'fand'::text,'zu finden'::text,'finden'::text,'Er wird nie vergessen, wie er den Schalter in völliger Dunkelheit fand!'::text),
(395143,43905,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ніколи не забуде, як ... той вимикач у повній темряві!'::text,'знайшов'::text,'знайти'::text,'знайти'::text,'Він ніколи не забуде, як знайшов той вимикач у повній темряві!'::text),
(395142,43905,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Nunca olvidará ... ese interruptor en plena oscuridad!'::text,'haber encontrado'::text,'encontrar'::text,'encontrar'::text,'¡Nunca olvidará haber encontrado ese interruptor en plena oscuridad!'::text),
(395141,43905,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il n''oubliera jamais ... cet interrupteur dans le noir total !'::text,'avoir trouvé'::text,'trouver'::text,'trouver'::text,'Il n''oubliera jamais avoir trouvé cet interrupteur dans le noir total !'::text),
(395144,43905,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O düğmeyi zifiri karanlıkta ... asla unutmayacak!'::text,'bulduğunu'::text,'bulmayı'::text,'bulmak'::text,'O düğmeyi zifiri karanlıkta bulduğunu asla unutmayacak!'::text),
(395145,43905,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soha nem felejti el, hogy ... azt a kapcsolót a teljes sötétben!'::text,'megtalálta'::text,'megtalálni'::text,'megtalál'::text,'Soha nem felejti el, hogy megtalálta azt a kapcsolót a teljes sötétben!'::text),
(395148,43906,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, angeblich ist ... an der Tür der einzige in der ganzen Wohnung.'::text,'der Schalter'::text,'ein Schalter'::text,'Schalter'::text,'Girl, angeblich ist der Schalter an der Tür der einzige in der ganzen Wohnung.'::text),
(395152,43906,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, ... біля дверей — єдиний у всій квартирі.'::text,'вимикач'::text,'вимикач'::text,'вимикач'::text,'Подруго, кажуть, вимикач біля дверей — єдиний у всій квартирі.'::text),
(395151,43906,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer ... de la puerta es el único de todo el piso.'::text,'el interruptor'::text,'un interruptor'::text,'interruptor'::text,'Tía, al parecer el interruptor de la puerta es el único de todo el piso.'::text),
(395150,43906,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment ... près de la porte est le seul de tout l''appart.'::text,'l''interrupteur'::text,'un interrupteur'::text,'interrupteur'::text,'Meuf, apparemment l''interrupteur près de la porte est le seul de tout l''appart.'::text),
(395153,43906,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, güya kapının yanındaki ... bütün dairedeki tek düğme.'::text,'düğme'::text,'bir düğme'::text,'düğme'::text,'Kızım, güya kapının yanındaki düğme bütün dairedeki tek düğme.'::text),
(395154,43906,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag ... az ajtó mellett az egyetlen az egész lakásban.'::text,'a kapcsoló'::text,'egy kapcsoló'::text,'kapcsoló'::text,'Csajszi, állítólag a kapcsoló az ajtó mellett az egyetlen az egész lakásban.'::text),
(395157,43907,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, angeblich hat er den Schalter dreimal ..., seit er nach Hause gekommen ist.'::text,'gedrückt'::text,'drückt'::text,'drückt'::text,'Hör zu, angeblich hat er den Schalter dreimal gedrückt, seit er nach Hause gekommen ist.'::text),
(395161,43907,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, він ... той вимикач тричі, відколи прийшов додому.'::text,'натиснув'::text,'натискає'::text,'натискає'::text,'Слухай, кажуть, він натиснув той вимикач тричі, відколи прийшов додому.'::text),
(395160,43907,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer ... ese interruptor tres veces desde que llegó a casa.'::text,'ha pulsado'::text,'pulsa'::text,'está pulsando'::text,'Oye, al parecer ha pulsado ese interruptor tres veces desde que llegó a casa.'::text),
(395159,43907,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment il ... cet interrupteur trois fois depuis qu''il est rentré.'::text,'a appuyé sur'::text,'appuie sur'::text,'appuie sur'::text,'Écoute, apparemment il a appuyé sur cet interrupteur trois fois depuis qu''il est rentré.'::text),
(395162,43907,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, güya eve geldiğinden beri o düğmeye üç kez ...'::text,'basmış'::text,'basıyor'::text,'basıyor'::text,'Dinle, güya eve geldiğinden beri o düğmeye üç kez basmış.'::text),
(395163,43907,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag háromszor ... azt a kapcsolót, mióta hazaért.'::text,'megnyomta'::text,'nyomja'::text,'nyomja'::text,'Figyelj, állítólag háromszor megnyomta azt a kapcsolót, mióta hazaért.'::text),
(330168,36686,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit wird der Schneider ein weiteres Sakko für einen neuen Kunden ...'::text,'ändern'::text,'ändern'::text,'ändert'::text,'Morgen um diese Zeit wird der Schneider ein weiteres Sakko für einen neuen Kunden ändern.'::text),
(330172,36686,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час кравець ... ще один піджак для нового клієнта.'::text,'перешиватиме'::text,'перешиє'::text,'перешиває'::text,'Завтра в цей час кравець перешиватиме ще один піджак для нового клієнта.'::text),
(330171,36686,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora, el sastre ... otra chaqueta para un cliente nuevo.'::text,'estará arreglando'::text,'arreglará'::text,'arregla'::text,'Mañana a esta hora, el sastre estará arreglando otra chaqueta para un cliente nuevo.'::text),
(330170,36686,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, le tailleur ... une autre veste pour un nouveau client.'::text,'sera en train de retoucher'::text,'retouchera'::text,'retouche'::text,'Demain à la même heure, le tailleur sera en train de retoucher une autre veste pour un nouveau client.'::text),
(330173,36686,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte terzi yeni bir müşteri için başka bir ceketi ...'::text,'tadil ediyor olacak'::text,'tadil edecek'::text,'tadil ediyor'::text,'Yarın bu saatte terzi yeni bir müşteri için başka bir ceketi tadil ediyor olacak.'::text),
(330174,36686,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor a szabó egy újabb zakót ... egy új ügyfélnek.'::text,'fog átalakítani'::text,'alakít át'::text,'alakít át'::text,'Holnap ilyenkor a szabó egy újabb zakót fog átalakítani egy új ügyfélnek.'::text),
(330186,36688,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das dunkelblaue Sakko ... gestern in weniger als einer Stunde an der alten Nähmaschine geändert.'::text,'wurde'::text,'wird'::text,'änderte'::text,'Das dunkelblaue Sakko wurde gestern in weniger als einer Stunde an der alten Nähmaschine geändert.'::text),
(330190,36688,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Темно-синій піджак ... вчора на старій швейній машинці менш ніж за годину.'::text,'перешили'::text,'перешивають'::text,'перешив'::text,'Темно-синій піджак перешили вчора на старій швейній машинці менш ніж за годину.'::text),
(330189,36688,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La chaqueta azul marino ... ayer en la vieja máquina de coser en menos de una hora.'::text,'fue arreglada'::text,'es arreglada'::text,'arregló'::text,'La chaqueta azul marino fue arreglada ayer en la vieja máquina de coser en menos de una hora.'::text),
(330188,36688,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La veste bleu marine ... hier sur la vieille machine à coudre en moins d''une heure.'::text,'a été retouchée'::text,'est retouchée'::text,'a retouché'::text,'La veste bleu marine a été retouchée hier sur la vieille machine à coudre en moins d''une heure.'::text),
(330191,36688,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lacivert ceket dün eski dikiş makinesinde bir saatten kısa sürede ...'::text,'tadil edildi'::text,'tadil ediliyor'::text,'tadil etti'::text,'Lacivert ceket dün eski dikiş makinesinde bir saatten kısa sürede tadil edildi.'::text),
(330192,36688,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sötétkék zakót tegnap a régi varrógépen kevesebb mint egy óra alatt ...'::text,'alakították át'::text,'alakítják át'::text,'alakította át'::text,'A sötétkék zakót tegnap a régi varrógépen kevesebb mint egy óra alatt alakították át.'::text),
(330195,36689,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Schneider ... das Sakko nur mit Kreide und einer Maschine. Eindeutig ein totaler Amateur.'::text,'änderte'::text,'wurde geändert'::text,'ändernd'::text,'Der Schneider änderte das Sakko nur mit Kreide und einer Maschine. Eindeutig ein totaler Amateur.'::text),
(330199,36689,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кравець ... піджак лише крейдою та машинкою. Явно повний аматор.'::text,'перешив'::text,'був перешитий'::text,'перешиваючи'::text,'Кравець перешив піджак лише крейдою та машинкою. Явно повний аматор.'::text),
(330198,36689,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El sastre ... la chaqueta solo con tiza y una máquina. Está claro que es un aficionado total.'::text,'arregló'::text,'fue arreglado'::text,'arreglando'::text,'El sastre arregló la chaqueta solo con tiza y una máquina. Está claro que es un aficionado total.'::text),
(330197,36689,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le tailleur ... la veste avec juste une craie et une machine. Clairement un amateur total.'::text,'a retouché'::text,'a été retouché'::text,'retouchant'::text,'Le tailleur a retouché la veste avec juste une craie et une machine. Clairement un amateur total.'::text),
(330200,36689,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Terzi ceketi sadece tebeşir ve bir makineyle ...: belli ki tam bir amatör.'::text,'tadil etti'::text,'tadil edildi'::text,'tadil ederek'::text,'Terzi ceketi sadece tebeşir ve bir makineyle tadil etti: belli ki tam bir amatör.'::text),
(330201,36689,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szabó csak krétával és egy géppel ... át a zakót. Nyilvánvalóan totál amatőr.'::text,'alakította'::text,'alakíttatott'::text,'alakítva'::text,'A szabó csak krétával és egy géppel alakította át a zakót. Nyilvánvalóan totál amatőr.'::text),
(330204,36690,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, er näht buchstäblich den Ärmel, also ... er das Sakko gerade ändern, echt jetzt.'::text,'muss'::text,'könnte'::text,'kann nicht'::text,'Digga, er näht buchstäblich den Ärmel, also muss er das Sakko gerade ändern, echt jetzt.'::text),
(330208,36690,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він буквально пришиває рукав, тож він ... перешивати той піджак, реально.'::text,'мусить'::text,'може'::text,'не може'::text,'Бро, він буквально пришиває рукав, тож він мусить перешивати той піджак, реально.'::text),
(330207,36690,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, está literalmente cosiendo la manga, así que ... estar arreglando esa chaqueta, en serio.'::text,'debe de'::text,'podría'::text,'no puede'::text,'Bro, está literalmente cosiendo la manga, así que debe de estar arreglando esa chaqueta, en serio.'::text),
(330206,36690,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, il coud littéralement la manche, donc il ... être en train de retoucher cette veste, sérieux.'::text,'doit'::text,'pourrait'::text,'ne peut pas'::text,'Frère, il coud littéralement la manche, donc il doit être en train de retoucher cette veste, sérieux.'::text),
(330209,36690,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, resmen kolu dikiyor, yani o ceketi tadil ediyor ..., cidden.'::text,'olmalı'::text,'olabilir'::text,'olamaz'::text,'Kanka, resmen kolu dikiyor, yani o ceketi tadil ediyor olmalı, cidden.'::text),
(330210,36690,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, szó szerint az ujját varrja, szóval ... azt a zakót alakítja át, komolyan.'::text,'biztosan'::text,'talán'::text,'nem lehet, hogy'::text,'Tesó, szó szerint az ujját varrja, szóval biztosan azt a zakót alakítja át, komolyan.'::text),
(330213,36691,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, der Schneider, ... dieses Sakko geändert hat, ist echt krass gut, ehrlich.'::text,'der'::text,'welches'::text,'dessen'::text,'Yo, der Schneider, der dieses Sakko geändert hat, ist echt krass gut, ehrlich.'::text),
(330217,36691,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, кравець, ... перешив цей піджак, реально топ, без брехні.'::text,'який'::text,'що'::text,'чий'::text,'Йо, кравець, який перешив цей піджак, реально топ, без брехні.'::text),
(330216,36691,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, el sastre ... arregló esta chaqueta es un crack, en serio.'::text,'que'::text,'el cual'::text,'cuyo'::text,'Oye, el sastre que arregló esta chaqueta es un crack, en serio.'::text),
(330215,36691,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, le tailleur ... a retouché cette veste est trop un boss, sans mentir.'::text,'qui'::text,'lequel'::text,'dont'::text,'Yo, le tailleur qui a retouché cette veste est trop un boss, sans mentir.'::text),
(330218,36691,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu ceketi tadil ... terzi resmen efsane, yalan yok.'::text,'eden'::text,'eden'::text,'eden'::text,'Kanka, bu ceketi tadil eden terzi resmen efsane, yalan yok.'::text),
(330219,36691,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, a szabó, ... ezt a zakót átalakította, tök király, komolyan.'::text,'aki'::text,'amely'::text,'akinek'::text,'Figyu, a szabó, aki ezt a zakót átalakította, tök király, komolyan.'::text),
(330222,36692,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Kunde meldete, dass der Schneider das Sakko innerhalb der 2-Stunden-Frist ...'::text,'geändert hatte'::text,'geändert hat'::text,'ändert'::text,'Der Kunde meldete, dass der Schneider das Sakko innerhalb der 2-Stunden-Frist geändert hatte.'::text),
(330226,36692,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Клієнт повідомив, що кравець ... піджак у межах 2-годинного дедлайну.'::text,'перешив'::text,'перешив'::text,'перешиває'::text,'Клієнт повідомив, що кравець перешив піджак у межах 2-годинного дедлайну.'::text),
(330225,36692,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El cliente informó de que el sastre ... la chaqueta dentro del plazo de 2 horas.'::text,'había arreglado'::text,'ha arreglado'::text,'arregla'::text,'El cliente informó de que el sastre había arreglado la chaqueta dentro del plazo de 2 horas.'::text),
(330224,36692,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le client a signalé que le tailleur ... la veste dans le délai de 2 heures.'::text,'avait retouché'::text,'a retouché'::text,'retouche'::text,'Le client a signalé que le tailleur avait retouché la veste dans le délai de 2 heures.'::text),
(330227,36692,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Müşteri, terzinin ceketi 2 saatlik süre içinde ... bildirdi.'::text,'tadil etmiş olduğunu'::text,'tadil ettiğini'::text,'tadil ettiğini'::text,'Müşteri, terzinin ceketi 2 saatlik süre içinde tadil etmiş olduğunu bildirdi.'::text),
(330228,36692,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ügyfél jelentette, hogy a szabó a 2 órás határidőn belül ... a zakót.'::text,'átalakította'::text,'átalakította'::text,'átalakítja'::text,'Az ügyfél jelentette, hogy a szabó a 2 órás határidőn belül átalakította a zakót.'::text),
(330231,36693,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sein altes Sakko ... früher zu groß, weil es niemand geändert hat, also war es nicht klein.'::text,'war'::text,'war'::text,'war gewohnt'::text,'Sein altes Sakko war früher zu groß, weil es niemand geändert hat, also war es nicht klein.'::text),
(330235,36693,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його старий піджак ... завеликим, бо його ніхто не перешив, тож він не був малим.'::text,'колись був'::text,'колись був'::text,'звик бути'::text,'Його старий піджак колись був завеликим, бо його ніхто не перешив, тож він не був малим.'::text),
(330234,36693,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su vieja chaqueta ... ser demasiado grande porque nadie la arregló, así que no era pequeña.'::text,'solía'::text,'solía'::text,'estaba acostumbrada a'::text,'Su vieja chaqueta solía ser demasiado grande porque nadie la arregló, así que no era pequeña.'::text),
(330233,36693,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sa vieille veste ... trop grande parce que personne ne l''avait retouchée, donc elle n''était pas petite.'::text,'était'::text,'était'::text,'avait l''habitude d''être'::text,'Sa vieille veste était trop grande parce que personne ne l''avait retouchée, donc elle n''était pas petite.'::text),
(330236,36693,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eski ceketi eskiden çok büyük ..., çünkü kimse onu tadil etmemişti, yani küçük değildi.'::text,'olurdu'::text,'olurdu'::text,'olmaya alışkındı'::text,'Eski ceketi eskiden çok büyük olurdu, çünkü kimse onu tadil etmemişti, yani küçük değildi.'::text),
(330237,36693,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A régi zakója ... túl nagy volt, mert senki nem alakította át, szóval nem volt kicsi.'::text,'régen'::text,'régen'::text,'megszokottan'::text,'A régi zakója régen túl nagy volt, mert senki nem alakította át, szóval nem volt kicsi.'::text),
(330240,36694,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Schneider vermeidet es typischerweise, ein Sakko vor dem Vermessen der Schultern ...'::text,'zu ändern'::text,'zu ändern'::text,'ändern'::text,'Der Schneider vermeidet es typischerweise, ein Sakko vor dem Vermessen der Schultern zu ändern.'::text),
(330244,36694,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кравець зазвичай уникає ... піджака до вимірювання плечей.'::text,'перешивання'::text,'перешити'::text,'перешити'::text,'Кравець зазвичай уникає перешивання піджака до вимірювання плечей.'::text),
(330243,36694,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El sastre normalmente evita ... una chaqueta antes de medir los hombros.'::text,'arreglar'::text,'arreglar'::text,'arreglar'::text,'El sastre normalmente evita arreglar una chaqueta antes de medir los hombros.'::text),
(330242,36694,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le tailleur évite généralement de ... une veste avant de mesurer les épaules.'::text,'retoucher'::text,'retoucher'::text,'retoucher'::text,'Le tailleur évite généralement de retoucher une veste avant de mesurer les épaules.'::text),
(330245,36694,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Terzi genellikle omuzları ölçmeden önce bir ceketi ... kaçınır.'::text,'tadil etmekten'::text,'tadil etmeye'::text,'tadil etmek'::text,'Terzi genellikle omuzları ölçmeden önce bir ceketi tadil etmekten kaçınır.'::text),
(330246,36694,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szabó jellemzően kerüli, hogy ... egy zakót, mielőtt megméri a vállakat.'::text,'átalakítson'::text,'átalakítani'::text,'átalakít'::text,'A szabó jellemzően kerüli, hogy átalakítson egy zakót, mielőtt megméri a vállakat.'::text),
(330249,36695,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Niemand fasst das Sakko an! Der Schneider ... es gerade jetzt, und ein falscher Stich ist eine Katastrophe!'::text,'ändert'::text,'ändert'::text,'hat geändert'::text,'Niemand fasst das Sakko an! Der Schneider ändert es gerade jetzt, und ein falscher Stich ist eine Katastrophe!'::text),
(330253,36695,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніхто не чіпайте той піджак! Кравець ... його прямо зараз, і один неправильний стібок — це катастрофа!'::text,'перешиває'::text,'перешиває'::text,'перешив'::text,'Ніхто не чіпайте той піджак! Кравець перешиває його прямо зараз, і один неправильний стібок — це катастрофа!'::text),
(330252,36695,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Que nadie toque esa chaqueta! ¡El sastre la ... ahora mismo, y una puntada mal hecha es un desastre!'::text,'está arreglando'::text,'arregla'::text,'ha arreglado'::text,'¡Que nadie toque esa chaqueta! ¡El sastre la está arreglando ahora mismo, y una puntada mal hecha es un desastre!'::text),
(330251,36695,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Que personne ne touche à cette veste ! Le tailleur la ... en ce moment, et un seul mauvais point, c''est la catastrophe !'::text,'retouche'::text,'retouche'::text,'a retouchée'::text,'Que personne ne touche à cette veste ! Le tailleur la retouche en ce moment, et un seul mauvais point, c''est la catastrophe !'::text),
(330254,36695,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kimse o cekete dokunmasın! Terzi onu şu anda ..., tek bir yanlış dikiş felaket olur!'::text,'tadil ediyor'::text,'tadil eder'::text,'tadil etti'::text,'Kimse o cekete dokunmasın! Terzi onu şu anda tadil ediyor, tek bir yanlış dikiş felaket olur!'::text),
(330255,36695,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Senki ne nyúljon ahhoz a zakóhoz! A szabó épp most ... át, és egy rossz öltés katasztrófa!'::text,'alakítja'::text,'alakítja'::text,'alakította'::text,'Senki ne nyúljon ahhoz a zakóhoz! A szabó épp most alakítja át, és egy rossz öltés katasztrófa!'::text),
(395220,43914,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Radfahrer sieht die Lampe und sagt: „Die ... ich.“'::text,'nehme'::text,'werde nehmen'::text,'nehme gerade'::text,'Der Radfahrer sieht die Lampe und sagt: „Die nehme ich.“'::text),
(395224,43914,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Велосипедист бачить лампу й каже: «Я ... оцю».'::text,'візьму'::text,'братиму'::text,'беру'::text,'Велосипедист бачить лампу й каже: «Я візьму оцю».'::text),
(395223,43914,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El ciclista ve la lámpara y dice: «Me ... esa».'::text,'llevaré'::text,'estaré llevando'::text,'llevo'::text,'El ciclista ve la lámpara y dice: «Me llevaré esa».'::text),
(395222,43914,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le cycliste voit la lampe et dit : « Je ... celle-là. »'::text,'prendrai'::text,'serai en train de prendre'::text,'prends'::text,'Le cycliste voit la lampe et dit : « Je prendrai celle-là. »'::text),
(395225,43914,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bisikletçi lambayı görüyor ve “Onu ben ...” diyor.'::text,'alırım'::text,'alıyor olacağım'::text,'alıyorum'::text,'Bisikletçi lambayı görüyor ve “Onu ben alırım” diyor.'::text),
(395226,43914,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A biciklis meglátja a lámpát, és azt mondja: „Azt én ...”'::text,'elviszem'::text,'el fogom vinni'::text,'viszem'::text,'A biciklis meglátja a lámpát, és azt mondja: „Azt én elviszem”'::text),
(395229,43915,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn auf einer Kiste GRATIS ZEUG ..., nehmen sich Leute Sachen daraus.'::text,'steht'::text,'stand'::text,'stehen wird'::text,'Wenn auf einer Kiste GRATIS ZEUG steht, nehmen sich Leute Sachen daraus.'::text),
(395233,43915,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо на коробці ... «БЕЗКОШТОВНІ РЕЧІ», люди беруть із неї речі.'::text,'написано'::text,'було написано'::text,'буде написано'::text,'Якщо на коробці написано «БЕЗКОШТОВНІ РЕЧІ», люди беруть із неї речі.'::text),
(395232,43915,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si una caja ... COSAS GRATIS, la gente coge cosas de ella.'::text,'dice'::text,'decía'::text,'dirá'::text,'Si una caja dice COSAS GRATIS, la gente coge cosas de ella.'::text),
(395231,43915,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si une boîte ... TRUCS GRATUITS, les gens y prennent des choses.'::text,'indique'::text,'indiquait'::text,'indiquera'::text,'Si une boîte indique TRUCS GRATUITS, les gens y prennent des choses.'::text),
(395234,43915,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir kutunun üzerinde BEDAVA EŞYA ..., insanlar ondan bir şeyler alır.'::text,'yazıyorsa'::text,'yazıyorduysa'::text,'yazacaksa'::text,'Bir kutunun üzerinde BEDAVA EŞYA yazıyorsa, insanlar ondan bir şeyler alır.'::text),
(395235,43915,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy dobozon INGYEN CUCC felirat ..., az emberek elvisznek belőle dolgokat.'::text,'van'::text,'volt'::text,'lesz'::text,'Ha egy dobozon INGYEN CUCC felirat van, az emberek elvisznek belőle dolgokat.'::text),
(395247,43917,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, wenn ich die Kiste sehen würde, ... ich mir die Lampe auch schnappen, ehrlich.'::text,'würde'::text,'werde'::text,'schnappe'::text,'Nee, wenn ich die Kiste sehen würde, würde ich mir die Lampe auch schnappen, ehrlich.'::text),
(395251,43917,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, якби я побачив ту коробку, я теж ... лампу, без брехні.'::text,'взяв би'::text,'візьму'::text,'беру'::text,'Не, якби я побачив ту коробку, я теж взяв би лампу, без брехні.'::text),
(395250,43917,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nah, si viera esa caja, yo también ... la lámpara, en serio.'::text,'cogería'::text,'cogeré'::text,'cojo'::text,'Nah, si viera esa caja, yo también cogería la lámpara, en serio.'::text),
(395249,43917,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan, si je voyais cette boîte, je ... la lampe aussi, sans mentir.'::text,'prendrais'::text,'prendrai'::text,'prends'::text,'Nan, si je voyais cette boîte, je prendrais la lampe aussi, sans mentir.'::text),
(395252,43917,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok, o kutuyu görsem ben de lambayı ..., yalan yok.'::text,'alırdım'::text,'alacağım'::text,'alıyorum'::text,'Yok, o kutuyu görsem ben de lambayı alırdım, yalan yok.'::text),
(395253,43917,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, ha látnám azt a dobozt, én is ... a lámpát, komolyan.'::text,'elvinném'::text,'elviszem'::text,'viszem'::text,'Á, ha látnám azt a dobozt, én is elvinném a lámpát, komolyan.'::text),
(395256,43918,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alle Artikel ... vor 17 Uhr aus der Kiste genommen, also wurde das Tagesziel erreicht.'::text,'wurden'::text,'werden'::text,'nahmen'::text,'Alle Artikel wurden vor 17 Uhr aus der Kiste genommen, also wurde das Tagesziel erreicht.'::text),
(395260,43918,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Усі речі ... з коробки до 17:00, тож денну ціль виконано.'::text,'забрали'::text,'забирають'::text,'забрали'::text,'Усі речі забрали з коробки до 17:00, тож денну ціль виконано.'::text),
(395259,43918,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Todos los artículos ... de la caja antes de las 17:00, así que se cumplió el objetivo diario.'::text,'fueron retirados'::text,'son retirados'::text,'retiraron'::text,'Todos los artículos fueron retirados de la caja antes de las 17:00, así que se cumplió el objetivo diario.'::text),
(395258,43918,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tous les articles ... de la boîte avant 17 h, donc l''objectif quotidien a été atteint.'::text,'ont été retirés'::text,'sont retirés'::text,'ont retiré'::text,'Tous les articles ont été retirés de la boîte avant 17 h, donc l''objectif quotidien a été atteint.'::text),
(395261,43918,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tüm ürünler saat 17.00''den önce kutudan ..., yani günlük hedefe ulaşıldı.'::text,'alındı'::text,'alınıyor'::text,'aldı'::text,'Tüm ürünler saat 17.00''den önce kutudan alındı, yani günlük hedefe ulaşıldı.'::text),
(395262,43918,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az összes tételt ... a dobozból 17 óra előtt, így a napi cél teljesült.'::text,'elvitték'::text,'elviszik'::text,'elvitte'::text,'Az összes tételt elvitték a dobozból 17 óra előtt, így a napi cél teljesült.'::text),
(395265,43919,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Kiste ... von dem jungen Mann weggenommen, also ist die Kiste jetzt weg.'::text,'wurde'::text,'nahm'::text,'nehmend'::text,'Die Kiste wurde von dem jungen Mann weggenommen, also ist die Kiste jetzt weg.'::text),
(395269,43919,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коробку ... молодий чоловік, тож тепер коробки немає.'::text,'забрав'::text,'забрала'::text,'забираючи'::text,'Коробку забрав молодий чоловік, тож тепер коробки немає.'::text),
(395268,43919,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La caja ... por el joven, así que ahora la caja ya no está.'::text,'fue llevada'::text,'llevó'::text,'llevando'::text,'La caja fue llevada por el joven, así que ahora la caja ya no está.'::text),
(395267,43919,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La boîte ... par le jeune homme, donc maintenant la boîte n''est plus là.'::text,'a été emportée'::text,'a emporté'::text,'emportant'::text,'La boîte a été emportée par le jeune homme, donc maintenant la boîte n''est plus là.'::text),
(395270,43919,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kutu genç adam tarafından ..., yani artık kutu yok.'::text,'götürüldü'::text,'götürdü'::text,'götürerek'::text,'Kutu genç adam tarafından götürüldü, yani artık kutu yok.'::text),
(395271,43919,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A dobozt ... a fiatal férfi, így most nincs doboz.'::text,'elvitte'::text,'elvitt'::text,'elvíve'::text,'A dobozt elvitte a fiatal férfi, így most nincs doboz.'::text),
(395274,43920,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der junge Mann nimmt die leere Kiste, also ... er sie für etwas benötigen.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Der junge Mann nimmt die leere Kiste, also muss er sie für etwas benötigen.'::text),
(395278,43920,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Молодий чоловік бере порожню коробку, тож вона йому ... для чогось потрібна.'::text,'напевно'::text,'аж ніяк не'::text,'мала б бути'::text,'Молодий чоловік бере порожню коробку, тож вона йому напевно для чогось потрібна.'::text),
(395277,43920,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El joven se lleva la caja vacía, así que ... necesitarla para algo.'::text,'debe de'::text,'no puede'::text,'debería'::text,'El joven se lleva la caja vacía, así que debe de necesitarla para algo.'::text),
(395276,43920,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le jeune homme prend la boîte vide, donc il ... en avoir besoin pour quelque chose.'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'Le jeune homme prend la boîte vide, donc il doit en avoir besoin pour quelque chose.'::text),
(395279,43920,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genç adam boş kutuyu alıyor, yani bir şey için ona ihtiyacı ...'::text,'olmalı'::text,'olamaz'::text,'olmalı'::text,'Genç adam boş kutuyu alıyor, yani bir şey için ona ihtiyacı olmalı.'::text),
(395280,43920,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fiatal férfi elviszi az üres dobozt, tehát ... szüksége van rá valamihez.'::text,'biztosan'::text,'nem lehet, hogy'::text,'elvileg'::text,'A fiatal férfi elviszi az üres dobozt, tehát biztosan szüksége van rá valamihez.'::text),
(395283,43921,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau, ... den Blumentopf nahm, hat die Kiste komplett leer zurückgelassen!'::text,'die'::text,'welches'::text,'deren'::text,'Die Frau, die den Blumentopf nahm, hat die Kiste komplett leer zurückgelassen!'::text),
(395287,43921,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка, ... взяла вазон, залишила коробку зовсім порожньою!'::text,'яка'::text,'що'::text,'чия'::text,'Жінка, яка взяла вазон, залишила коробку зовсім порожньою!'::text),
(395286,43921,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La mujer ... se llevó la maceta dejó la caja totalmente vacía!'::text,'que'::text,'la cual'::text,'cuya'::text,'¡La mujer que se llevó la maceta dejó la caja totalmente vacía!'::text),
(395285,43921,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme ... a pris le pot de fleurs a laissé la boîte complètement vide !'::text,'qui'::text,'laquelle'::text,'dont'::text,'La femme qui a pris le pot de fleurs a laissé la boîte complètement vide !'::text),
(395288,43921,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saksıyı ... kadın kutuyu tamamen boş bıraktı!'::text,'alan'::text,'alan'::text,'alan'::text,'Saksıyı alan kadın kutuyu tamamen boş bıraktı!'::text),
(395289,43921,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nő, ... elvitte a virágcserepet, teljesen üresen hagyta a dobozt!'::text,'aki'::text,'amely'::text,'akinek'::text,'A nő, aki elvitte a virágcserepet, teljesen üresen hagyta a dobozt!'::text),
(395292,43922,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Radfahrer sagte, er würde die Lampe ... oder es für immer bereuen!'::text,'nehmen'::text,'nehmen'::text,'nimmt'::text,'Der Radfahrer sagte, er würde die Lampe nehmen oder es für immer bereuen!'::text),
(395296,43922,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Велосипедист сказав, що ... лампу, або шкодуватиме про це все життя!'::text,'візьме'::text,'візьме'::text,'бере'::text,'Велосипедист сказав, що візьме лампу, або шкодуватиме про це все життя!'::text),
(395295,43922,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El ciclista dijo que ... la lámpara o se arrepentiría para siempre!'::text,'se llevaría'::text,'se llevará'::text,'se lleva'::text,'¡El ciclista dijo que se llevaría la lámpara o se arrepentiría para siempre!'::text),
(395294,43922,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le cycliste a dit qu''il ... la lampe ou qu''il le regretterait pour toujours !'::text,'prendrait'::text,'prendra'::text,'prend'::text,'Le cycliste a dit qu''il prendrait la lampe ou qu''il le regretterait pour toujours !'::text),
(395297,43922,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bisikletçi lambayı ..., yoksa sonsuza dek pişman olacağını söyledi!'::text,'alacağını'::text,'alacağını'::text,'aldığını'::text,'Bisikletçi lambayı alacağını, yoksa sonsuza dek pişman olacağını söyledi!'::text),
(395298,43922,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A biciklis azt mondta, hogy ... a lámpát, különben örökké bánni fogja!'::text,'elviszi'::text,'elviszi'::text,'viszi'::text,'A biciklis azt mondta, hogy elviszi a lámpát, különben örökké bánni fogja!'::text),
(395301,43923,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Letzten Sommer ... die Leute alles in wenigen Minuten aus der Kiste! Totales Chaos!'::text,'nahmen'::text,'nahmen'::text,'waren gewohnt'::text,'Letzten Sommer nahmen die Leute alles in wenigen Minuten aus der Kiste! Totales Chaos!'::text),
(395305,43923,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Минулого літа люди ... все з тієї коробки за лічені хвилини! Повний хаос!'::text,'розбирали'::text,'розбирали'::text,'звикли розбирати'::text,'Минулого літа люди розбирали все з тієї коробки за лічені хвилини! Повний хаос!'::text),
(395304,43923,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El verano pasado la gente ... todo de esa caja en minutos! ¡Caos total!'::text,'se llevaba'::text,'solía llevarse'::text,'estaba acostumbrada a llevarse'::text,'¡El verano pasado la gente se llevaba todo de esa caja en minutos! ¡Caos total!'::text),
(395303,43923,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''été dernier, les gens ... tout dans cette boîte en quelques minutes ! Le chaos total !'::text,'prenaient'::text,'prenaient'::text,'avaient l''habitude de prendre'::text,'L''été dernier, les gens prenaient tout dans cette boîte en quelques minutes ! Le chaos total !'::text),
(395306,43923,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Geçen yaz insanlar o kutudaki her şeyi dakikalar içinde ...! Tam bir kaos!'::text,'alırdı'::text,'alırdı'::text,'almaya alışkındı'::text,'Geçen yaz insanlar o kutudaki her şeyi dakikalar içinde alırdı! Tam bir kaos!'::text),
(395307,43923,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tavaly nyáron az emberek percek alatt ... mindent abból a dobozból! Totális káosz!'::text,'elvittek'::text,'elvittek'::text,'megszokták, hogy elvigyenek'::text,'Tavaly nyáron az emberek percek alatt elvittek mindent abból a dobozból! Totális káosz!'::text),
(395310,43924,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der junge Mann beschließt, auch die leere Kiste ...'::text,'mitzunehmen'::text,'mitnehmend'::text,'mitnehmen'::text,'Der junge Mann beschließt, auch die leere Kiste mitzunehmen.'::text),
(395314,43924,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Молодий чоловік вирішує ... і порожню коробку.'::text,'забрати'::text,'забираючи'::text,'забрати'::text,'Молодий чоловік вирішує забрати і порожню коробку.'::text),
(395313,43924,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El joven decide ... también la caja vacía.'::text,'llevarse'::text,'llevándose'::text,'llevarse'::text,'El joven decide llevarse también la caja vacía.'::text),
(395312,43924,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le jeune homme décide ... aussi la boîte vide.'::text,'d''emporter'::text,'emportant'::text,'emporter'::text,'Le jeune homme décide d''emporter aussi la boîte vide.'::text),
(395315,43924,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genç adam boş kutuyu da ... karar veriyor.'::text,'götürmeye'::text,'götürmeyi'::text,'götürmek'::text,'Genç adam boş kutuyu da götürmeye karar veriyor.'::text),
(395316,43924,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fiatal férfi úgy dönt, hogy az üres dobozt is ...'::text,'elviszi'::text,'elvíve'::text,'elvisz'::text,'A fiatal férfi úgy dönt, hogy az üres dobozt is elviszi.'::text),
(332301,36923,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ein Taxi auf einer belebten Avenue das Dachlicht anhat, ... es typischerweise Fahrgäste.'::text,'akzeptiert'::text,'akzeptierte'::text,'wird akzeptieren'::text,'Wenn ein Taxi auf einer belebten Avenue das Dachlicht anhat, akzeptiert es typischerweise Fahrgäste.'::text),
(332305,36923,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо в таксі на жвавому проспекті світиться вогник на даху, воно зазвичай ... пасажирів.'::text,'бере'::text,'брало'::text,'візьме'::text,'Якщо в таксі на жвавому проспекті світиться вогник на даху, воно зазвичай бере пасажирів.'::text),
(332304,36923,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un taxi en una avenida concurrida lleva la luz del techo encendida, normalmente ... pasajeros.'::text,'acepta'::text,'aceptaba'::text,'aceptará'::text,'Si un taxi en una avenida concurrida lleva la luz del techo encendida, normalmente acepta pasajeros.'::text),
(332303,36923,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un taxi sur une avenue animée a son lumineux allumé, il ... généralement des passagers.'::text,'accepte'::text,'acceptait'::text,'acceptera'::text,'Si un taxi sur une avenue animée a son lumineux allumé, il accepte généralement des passagers.'::text),
(332306,36923,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İşlek bir caddedeki taksinin tepe lambası yanıyorsa, genellikle yolcu ...'::text,'alır'::text,'alırdı'::text,'alacak'::text,'İşlek bir caddedeki taksinin tepe lambası yanıyorsa, genellikle yolcu alır.'::text),
(332307,36923,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy forgalmas sugárúton egy taxi tetőlámpája világít, jellemzően ... utasokat.'::text,'felvesz'::text,'felvett'::text,'fel fog venni'::text,'Ha egy forgalmas sugárúton egy taxi tetőlámpája világít, jellemzően felvesz utasokat.'::text),
(332310,36924,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du winkst dir auf dieser Avenue Taxis heran wie ein Profi, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Ehrlich, du winkst dir auf dieser Avenue Taxis heran wie ein Profi, oder?'::text),
(332314,36924,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ловиш таксі на цьому проспекті як профі, ...?'::text,'правда'::text,'правда'::text,'правда'::text,'Чесно, ти ловиш таксі на цьому проспекті як профі, правда?'::text),
(332313,36924,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, paras taxis en esta avenida como una pro, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'La verdad, paras taxis en esta avenida como una pro, ¿verdad?'::text),
(332312,36924,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu hèles les taxis sur cette avenue comme une pro, ... ?'::text,'pas vrai'::text,'pas vrai'::text,'pas vrai'::text,'Franchement, tu hèles les taxis sur cette avenue comme une pro, pas vrai ?'::text),
(332315,36924,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, bu caddede profesyonel gibi taksi çeviriyorsun, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Açıkçası, bu caddede profesyonel gibi taksi çeviriyorsun, değil mi?'::text),
(332316,36924,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, úgy intesz le taxit ezen a sugárúton, mint egy profi, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'Őszintén, úgy intesz le taxit ezen a sugárúton, mint egy profi, ugye?'::text),
(332337,36927,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wäre sie zwei Spuren weiter die Avenue hinaufgegangen, ... sie ein Taxi bekommen. Makellose Planung.'::text,'hätte'::text,'wird'::text,'hat'::text,'Wäre sie zwei Spuren weiter die Avenue hinaufgegangen, hätte sie ein Taxi bekommen. Makellose Planung.'::text),
(332341,36927,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона пройшла на дві смуги далі проспектом, вона ... таксі. Бездоганне планування.'::text,'впіймала б'::text,'впіймає'::text,'впіймала'::text,'Якби вона пройшла на дві смуги далі проспектом, вона впіймала б таксі. Бездоганне планування.'::text),
(332340,36927,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si hubiera caminado dos carriles más avenida arriba, ... un taxi. Una planificación impecable.'::text,'habría conseguido'::text,'conseguirá'::text,'consiguió'::text,'Si hubiera caminado dos carriles más avenida arriba, habría conseguido un taxi. Una planificación impecable.'::text),
(332339,36927,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle avait marché deux voies plus loin sur l''avenue, elle ... un taxi. Organisation impeccable.'::text,'aurait eu'::text,'aura'::text,'a eu'::text,'Si elle avait marché deux voies plus loin sur l''avenue, elle aurait eu un taxi. Organisation impeccable.'::text),
(332342,36927,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Caddede iki şerit daha ileri yürüseydi bir taksi ...: kusursuz planlama.'::text,'bulurdu'::text,'bulacak'::text,'buldu'::text,'Caddede iki şerit daha ileri yürüseydi bir taksi bulurdu: kusursuz planlama.'::text),
(332343,36927,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha két sávval feljebb ment volna a sugárúton, ... taxit. Hibátlan tervezés.'::text,'kapott volna'::text,'fog kapni'::text,'kapott'::text,'Ha két sávval feljebb ment volna a sugárúton, kapott volna taxit. Hibátlan tervezés.'::text),
(332346,36928,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie bestand aufs ... eines Taxis auf der belebtesten Avenue der Stadt. Toller Plan, offensichtlich.'::text,'Heranwinken'::text,'heranzuwinken'::text,'herangewunken'::text,'Sie bestand aufs Heranwinken eines Taxis auf der belebtesten Avenue der Stadt. Toller Plan, offensichtlich.'::text),
(332350,36928,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона наполягла на тому, щоб ... таксі на найжвавішому проспекті міста. Чудовий план, очевидно.'::text,'зловити'::text,'зловити'::text,'зловила'::text,'Вона наполягла на тому, щоб зловити таксі на найжвавішому проспекті міста. Чудовий план, очевидно.'::text),
(332349,36928,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Insistió en ... un taxi en la avenida más concurrida de la ciudad. Un plan genial, obviamente.'::text,'parar'::text,'parar'::text,'paró'::text,'Insistió en parar un taxi en la avenida más concurrida de la ciudad. Un plan genial, obviamente.'::text),
(332348,36928,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a tenu à ... un taxi sur l''avenue la plus animée de la ville. Super plan, évidemment.'::text,'héler'::text,'héler'::text,'a hélé'::text,'Elle a tenu à héler un taxi sur l''avenue la plus animée de la ville. Super plan, évidemment.'::text),
(332351,36928,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şehrin en işlek caddesinde taksi ... ısrar etti. Harika plan, belli ki.'::text,'çevirmekte'::text,'çevirmeye'::text,'çevirdi'::text,'Şehrin en işlek caddesinde taksi çevirmekte ısrar etti. Harika plan, belli ki.'::text),
(332352,36928,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ragaszkodott hozzá, hogy a város legforgalmasabb sugárútján ... le taxit. Remek terv, nyilván.'::text,'intsen'::text,'inteni'::text,'intett'::text,'Ragaszkodott hozzá, hogy a város legforgalmasabb sugárútján intsen le taxit. Remek terv, nyilván.'::text),
(332355,36929,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mit dem Koffer ... sie ein Taxi vom Hotel aus buchen sollen, nicht von der Avenue. Makellos.'::text,'hätte'::text,'musste'::text,'hätte nicht'::text,'Mit dem Koffer hätte sie ein Taxi vom Hotel aus buchen sollen, nicht von der Avenue. Makellos.'::text),
(332359,36929,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'З такою валізою їй ... таксі з готелю, а не з проспекту. Бездоганно.'::text,'варто було замовити'::text,'напевно, довелося замовити'::text,'не треба було замовляти'::text,'З такою валізою їй варто було замовити таксі з готелю, а не з проспекту. Бездоганно.'::text),
(332358,36929,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Con esa maleta, ... un taxi desde el hotel, no desde la avenida. Impecable.'::text,'debería haber reservado'::text,'debe de haber reservado'::text,'no tenía que haber reservado'::text,'Con esa maleta, debería haber reservado un taxi desde el hotel, no desde la avenida. Impecable.'::text),
(332357,36929,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avec cette valise, elle ... un taxi depuis l''hôtel, pas depuis l''avenue. Impeccable.'::text,'aurait dû réserver'::text,'a dû réserver'::text,'n''avait pas besoin de réserver'::text,'Avec cette valise, elle aurait dû réserver un taxi depuis l''hôtel, pas depuis l''avenue. Impeccable.'::text),
(332360,36929,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O bavulla taksiyi caddeden değil, otelden ...: kusursuz.'::text,'ayırtmalıydı'::text,'ayırtmış olmalı'::text,'ayırtmasına gerek yoktu'::text,'O bavulla taksiyi caddeden değil, otelden ayırtmalıydı: kusursuz.'::text),
(332361,36929,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ezzel a bőrönddel a szállodából ... taxit, nem a sugárútról. Hibátlan.'::text,'kellett volna rendelnie'::text,'biztosan rendelt'::text,'nem kellett volna rendelnie'::text,'Ezzel a bőrönddel a szállodából kellett volna rendelnie taxit, nem a sugárútról. Hibátlan.'::text),
(332364,36930,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie wird einen Taxifahrer dazu bringen, ihren Koffer ..., bevor sie die Avenue hinunterfahren.'::text,'anzuheben'::text,'anheben'::text,'angehoben'::text,'Sie wird einen Taxifahrer dazu bringen, ihren Koffer anzuheben, bevor sie die Avenue hinunterfahren.'::text),
(332368,36930,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона попросить таксиста ... її валізу, перш ніж вони поїдуть проспектом.'::text,'підняти'::text,'підняти'::text,'піднятий'::text,'Вона попросить таксиста підняти її валізу, перш ніж вони поїдуть проспектом.'::text),
(332367,36930,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hará que un taxista le ... la maleta antes de que se vayan por la avenida.'::text,'levante'::text,'levante'::text,'levantada'::text,'Hará que un taxista le levante la maleta antes de que se vayan por la avenida.'::text),
(332366,36930,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle va demander à un chauffeur de taxi de ... sa valise avant qu''ils partent sur l''avenue.'::text,'soulever'::text,'soulever'::text,'soulevé'::text,'Elle va demander à un chauffeur de taxi de soulever sa valise avant qu''ils partent sur l''avenue.'::text),
(332369,36930,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Caddeden yola çıkmadan önce bavulunu bir taksi şoförüne ...'::text,'kaldırtacak'::text,'kaldırtacak'::text,'kaldırılmış'::text,'Caddeden yola çıkmadan önce bavulunu bir taksi şoförüne kaldırtacak.'::text),
(332370,36930,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megkér majd egy taxisofőrt, hogy ... a bőröndjét, mielőtt elhajtanak a sugárúton.'::text,'emelje fel'::text,'felemelni'::text,'felemelt'::text,'Megkér majd egy taxisofőrt, hogy emelje fel a bőröndjét, mielőtt elhajtanak a sugárúton.'::text),
(332373,36931,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Auf der belebten Avenue stehend wünscht sie sich, dass ein Taxi für sie ...'::text,'anhielte'::text,'anhalten wird'::text,'anhält'::text,'Auf der belebten Avenue stehend wünscht sie sich, dass ein Taxi für sie anhielte.'::text),
(332377,36931,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стоячи на жвавому проспекті, вона хоче, щоб таксі для неї ...'::text,'зупинилося'::text,'зупиниться'::text,'зупиняється'::text,'Стоячи на жвавому проспекті, вона хоче, щоб таксі для неї зупинилося.'::text),
(332376,36931,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'De pie en la avenida concurrida, desearía que un taxi ... por ella.'::text,'parara'::text,'parará'::text,'para'::text,'De pie en la avenida concurrida, desearía que un taxi parara por ella.'::text),
(332375,36931,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Debout sur l''avenue animée, elle aimerait qu''un taxi ... pour elle.'::text,'s''arrête'::text,'s''arrêtera'::text,'s''arrête'::text,'Debout sur l''avenue animée, elle aimerait qu''un taxi s''arrête pour elle.'::text),
(332378,36931,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İşlek caddede dururken keşke bir taksi onun için ... diye düşünüyor.'::text,'dursa'::text,'duracak'::text,'duruyor'::text,'İşlek caddede dururken keşke bir taksi onun için dursa diye düşünüyor.'::text),
(332379,36931,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A forgalmas sugárúton állva azt szeretné, ha egy taxi ... neki.'::text,'megállna'::text,'meg fog állni'::text,'megáll'::text,'A forgalmas sugárúton állva azt szeretné, ha egy taxi megállna neki.'::text),
(332382,36932,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Avenue, ... Spuren voller gelber Taxis sind, verläuft zwischen hohen Gebäuden.'::text,'deren'::text,'welche'::text,'wo'::text,'Die Avenue, deren Spuren voller gelber Taxis sind, verläuft zwischen hohen Gebäuden.'::text),
(332386,36932,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Проспект, ... смуги заповнені жовтими таксі, пролягає між високими будівлями.'::text,'чиї'::text,'який'::text,'де'::text,'Проспект, чиї смуги заповнені жовтими таксі, пролягає між високими будівлями.'::text),
(332385,36932,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La avenida, ... carriles están llenos de taxis amarillos, discurre entre edificios altos.'::text,'cuyos'::text,'la cual'::text,'donde'::text,'La avenida, cuyos carriles están llenos de taxis amarillos, discurre entre edificios altos.'::text),
(332384,36932,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''avenue, ... les voies sont pleines de taxis jaunes, passe entre de hauts immeubles.'::text,'dont'::text,'laquelle'::text,'où'::text,'L''avenue, dont les voies sont pleines de taxis jaunes, passe entre de hauts immeubles.'::text),
(332387,36932,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şeritleri sarı taksilerle ... cadde, yüksek binaların arasından geçiyor.'::text,'dolu olan'::text,'dolu olan'::text,'dolu olan'::text,'Şeritleri sarı taksilerle dolu olan cadde, yüksek binaların arasından geçiyor.'::text),
(332388,36932,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sugárút, ... sávjai tele vannak sárga taxikkal, magas épületek között halad.'::text,'amelynek a'::text,'amely'::text,'ahol'::text,'A sugárút, amelynek a sávjai tele vannak sárga taxikkal, magas épületek között halad.'::text),
(332391,36933,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie plant, die Avenue ... zu verlassen, statt mit ihrem Koffer zu laufen.'::text,'per Taxi'::text,'mit einem Taxi'::text,'mit dem Taxi'::text,'Sie plant, die Avenue per Taxi zu verlassen, statt mit ihrem Koffer zu laufen.'::text),
(332395,36933,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона планує поїхати з проспекту ..., а не йти пішки з валізою.'::text,'на таксі'::text,'на таксі'::text,'на таксі'::text,'Вона планує поїхати з проспекту на таксі, а не йти пішки з валізою.'::text),
(332394,36933,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Planea salir de la avenida ... en vez de caminar con la maleta.'::text,'en taxi'::text,'en un taxi'::text,'en el taxi'::text,'Planea salir de la avenida en taxi en vez de caminar con la maleta.'::text),
(332393,36933,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle compte quitter l''avenue ... plutôt que de marcher avec sa valise.'::text,'en taxi'::text,'dans un taxi'::text,'dans le taxi'::text,'Elle compte quitter l''avenue en taxi plutôt que de marcher avec sa valise.'::text),
(332396,36933,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bavuluyla yürümek yerine caddeden ... ayrılmayı planlıyor.'::text,'taksiyle'::text,'bir taksiyle'::text,'taksiyle'::text,'Bavuluyla yürümek yerine caddeden taksiyle ayrılmayı planlıyor.'::text),
(332397,36933,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt tervezi, hogy ... hagyja el a sugárutat, ahelyett hogy a bőröndjével gyalogolna.'::text,'taxival'::text,'egy taxival'::text,'a taxival'::text,'Azt tervezi, hogy taxival hagyja el a sugárutat, ahelyett hogy a bőröndjével gyalogolna.'::text),
(402798,44756,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, ich hab gehört, das Team hat den Sieg gefeiert, und ...'::text,'der Trainer auch'::text,'der Trainer auch'::text,'der Trainer auch nicht'::text,'Hör zu, ich hab gehört, das Team hat den Sieg gefeiert, und der Trainer auch.'::text),
(402802,44756,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що команда святкувала перемогу, і ...'::text,'тренер теж'::text,'тренер теж'::text,'тренер теж ні'::text,'Слухай, я чула, що команда святкувала перемогу, і тренер теж.'::text),
(402801,44756,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, he oído que el equipo celebró la victoria, y ...'::text,'el entrenador también'::text,'el entrenador también'::text,'el entrenador tampoco'::text,'Oye, he oído que el equipo celebró la victoria, y el entrenador también.'::text),
(402800,44756,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il paraît que l''équipe a fêté la victoire, et ...'::text,'le coach aussi'::text,'le coach aussi'::text,'le coach non plus'::text,'Écoute, il paraît que l''équipe a fêté la victoire, et le coach aussi.'::text),
(402803,44756,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duyduğuma göre takım galibiyeti kutlamış, ...'::text,'koç da'::text,'koç da'::text,'koç da değil'::text,'Dinle, duyduğuma göre takım galibiyeti kutlamış, koç da.'::text),
(402804,44756,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy a csapat megünnepelte a győzelmet, és ...'::text,'az edző is'::text,'az edző is'::text,'az edző sem'::text,'Figyelj, azt hallottam, hogy a csapat megünnepelte a győzelmet, és az edző is.'::text),
(402807,44757,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, der Trainer hat mir erzählt, dass sie monatelang ..., bevor sie diesen Sieg holten.'::text,'trainiert hatten'::text,'trainiert haben'::text,'trainierten'::text,'Rate mal, der Trainer hat mir erzählt, dass sie monatelang trainiert hatten, bevor sie diesen Sieg holten.'::text),
(402811,44757,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, тренер сказав мені, що вони ... місяцями, перш ніж здобули цю перемогу.'::text,'тренувалися'::text,'тренуються'::text,'тренувалися'::text,'Уяви, тренер сказав мені, що вони тренувалися місяцями, перш ніж здобули цю перемогу.'::text),
(402810,44757,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina qué, el entrenador me dijo que ... meses entrenando antes de conseguir esta victoria.'::text,'llevaban'::text,'llevan'::text,'estaban'::text,'Adivina qué, el entrenador me dijo que llevaban meses entrenando antes de conseguir esta victoria.'::text),
(402809,44757,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, le coach m''a dit qu''ils ... depuis des mois avant de décrocher cette victoire.'::text,'s''entraînaient'::text,'s''entraînent'::text,'s''entraînaient'::text,'Devine quoi, le coach m''a dit qu''ils s''entraînaient depuis des mois avant de décrocher cette victoire.'::text),
(402812,44757,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım ne oldu, koç bana bu galibiyeti almadan önce aylardır ... söyledi.'::text,'antrenman yaptıklarını'::text,'antrenman yaptıklarını'::text,'antrenman yaptıklarını'::text,'Bil bakalım ne oldu, koç bana bu galibiyeti almadan önce aylardır antrenman yaptıklarını söyledi.'::text),
(402813,44757,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, az edző azt mondta, hogy hónapok óta ..., mielőtt megszerezték ezt a győzelmet.'::text,'edzettek'::text,'edzenek'::text,'edzettek'::text,'Képzeld, az edző azt mondta, hogy hónapok óta edzettek, mielőtt megszerezték ezt a győzelmet.'::text),
(402816,44758,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, bis Ende des Sommers wirst du zehn Siege in Folge ...'::text,'geholt haben'::text,'holen'::text,'am Holen sein'::text,'Ehrlich, bis Ende des Sommers wirst du zehn Siege in Folge geholt haben.'::text),
(402820,44758,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, до кінця літа ти ... десять перемог поспіль.'::text,'здобудеш'::text,'здобудеш'::text,'здобуватимеш'::text,'Чесно, до кінця літа ти здобудеш десять перемог поспіль.'::text),
(402819,44758,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'De verdad, para el final del verano ... diez victorias seguidas.'::text,'habrás conseguido'::text,'conseguirás'::text,'estarás consiguiendo'::text,'De verdad, para el final del verano habrás conseguido diez victorias seguidas.'::text),
(402818,44758,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, d''ici la fin de l''été, tu ... dix victoires d''affilée.'::text,'auras décroché'::text,'décrocheras'::text,'seras en train de décrocher'::text,'Franchement, d''ici la fin de l''été, tu auras décroché dix victoires d''affilée.'::text),
(402821,44758,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, yaz sonuna kadar üst üste on galibiyet ...'::text,'almış olacaksın'::text,'alacaksın'::text,'alıyor olacaksın'::text,'Açıkçası, yaz sonuna kadar üst üste on galibiyet almış olacaksın.'::text),
(402822,44758,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, a nyár végére zsinórban tíz győzelmet ...'::text,'szerzel majd'::text,'szerzel'::text,'fogsz szerezni'::text,'Őszintén, a nyár végére zsinórban tíz győzelmet szerzel majd.'::text),
(402825,44759,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ganz ehrlich, bis August wirst du ein ganzes Jahr lang für diesen Sieg ...'::text,'trainiert haben'::text,'trainieren'::text,'trainiert'::text,'Ganz ehrlich, bis August wirst du ein ganzes Jahr lang für diesen Sieg trainiert haben.'::text),
(402829,44759,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не брехатиму, до серпня ти ... заради цієї перемоги цілий рік.'::text,'тренуватимешся'::text,'тренуватимешся'::text,'тренувався'::text,'Не брехатиму, до серпня ти тренуватимешся заради цієї перемоги цілий рік.'::text),
(402828,44759,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, para agosto ... un año entero entrenando para esta victoria.'::text,'llevarás'::text,'estarás'::text,'has estado'::text,'No voy a mentir, para agosto llevarás un año entero entrenando para esta victoria.'::text),
(402827,44759,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas te mentir, d''ici août, tu ... pour cette victoire depuis une année entière.'::text,'te seras entraîné'::text,'t''entraîneras'::text,'t''es entraîné'::text,'Je vais pas te mentir, d''ici août, tu te seras entraîné pour cette victoire depuis une année entière.'::text),
(402830,44759,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, ağustosa kadar bu galibiyet için tam bir yıldır ...'::text,'antrenman yapıyor olacaksın'::text,'antrenman yapıyor olacaksın'::text,'antrenman yaptın'::text,'Yalan yok, ağustosa kadar bu galibiyet için tam bir yıldır antrenman yapıyor olacaksın.'::text),
(402831,44759,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem fogok hazudni, augusztusra egy teljes éve ... ezért a győzelemért.'::text,'edzel majd'::text,'fogsz edzeni'::text,'edzettél'::text,'Nem fogok hazudni, augusztusra egy teljes éve edzel majd ezért a győzelemért.'::text),
(402834,44760,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie nicht nach dem Ball gehechtet wäre, ... das Team den Sieg nicht geholt.'::text,'hätte'::text,'wird'::text,'hat'::text,'Wenn sie nicht nach dem Ball gehechtet wäre, hätte das Team den Sieg nicht geholt.'::text),
(402838,44760,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона не пірнула за м''ячем, команда ... перемоги.'::text,'не здобула б'::text,'не здобуде'::text,'не здобула'::text,'Якби вона не пірнула за м''ячем, команда не здобула б перемоги.'::text),
(402837,44760,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no se hubiera lanzado a por la pelota, el equipo no ... la victoria.'::text,'habría conseguido'::text,'conseguirá'::text,'consiguió'::text,'Si no se hubiera lanzado a por la pelota, el equipo no habría conseguido la victoria.'::text),
(402836,44760,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle n''avait pas plongé sur le ballon, l''équipe ... la victoire.'::text,'n''aurait pas obtenu'::text,'n''obtiendra pas'::text,'n''a pas obtenu'::text,'Si elle n''avait pas plongé sur le ballon, l''équipe n''aurait pas obtenu la victoire.'::text),
(402839,44760,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Topa uzanıp atlamasaydı, takım galibiyeti ...'::text,'alamazdı'::text,'alamayacak'::text,'alamadı'::text,'Topa uzanıp atlamasaydı, takım galibiyeti alamazdı.'::text),
(402840,44760,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem vetődött volna a labdáért, a csapat nem ... meg a győzelmet.'::text,'szerezte volna'::text,'fogja megszerezni'::text,'szerezte'::text,'Ha nem vetődött volna a labdáért, a csapat nem szerezte volna meg a győzelmet.'::text),
(402843,44761,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätten sie diesen Punkt nicht gewonnen, ... sie jetzt keinen Sieg feiern.'::text,'würden'::text,'hätten'::text,'werden'::text,'Hätten sie diesen Punkt nicht gewonnen, würden sie jetzt keinen Sieg feiern.'::text),
(402847,44761,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вони не виграли того очка, вони зараз ... перемогу.'::text,'не святкували б'::text,'не святкували б'::text,'не святкуватимуть'::text,'Якби вони не виграли того очка, вони зараз не святкували б перемогу.'::text),
(402846,44761,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no hubieran ganado ese punto, ahora no ... celebrando una victoria.'::text,'estarían'::text,'habrían estado'::text,'estarán'::text,'Si no hubieran ganado ese punto, ahora no estarían celebrando una victoria.'::text),
(402845,44761,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''ils n''avaient pas gagné ce point, ils ... pas en train de fêter une victoire maintenant.'::text,'ne seraient'::text,'n''auraient été'::text,'ne seront'::text,'S''ils n''avaient pas gagné ce point, ils ne seraient pas en train de fêter une victoire maintenant.'::text),
(402848,44761,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O sayıyı almasalardı, şu an bir galibiyet ...'::text,'kutluyor olmazlardı'::text,'kutlamış olmazlardı'::text,'kutluyor olmayacaklar'::text,'O sayıyı almasalardı, şu an bir galibiyet kutluyor olmazlardı.'::text),
(402849,44761,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem nyerték volna meg azt a pontot, most nem ... győzelmet.'::text,'ünnepelnének'::text,'ünnepeltek volna'::text,'fognak ünnepelni'::text,'Ha nem nyerték volna meg azt a pontot, most nem ünnepelnének győzelmet.'::text),
(402852,44762,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Man glaubt, dass der Sieg durch einen cleveren Schmetterball am Netz ...'::text,'entschieden wurde'::text,'entscheiden'::text,'entscheidend'::text,'Man glaubt, dass der Sieg durch einen cleveren Schmetterball am Netz entschieden wurde.'::text),
(402856,44762,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вважають, що перемогу ... один хитрий удар біля сітки.'::text,'вирішив'::text,'вирішити'::text,'вирішуючи'::text,'Вважають, що перемогу вирішив один хитрий удар біля сітки.'::text),
(402855,44762,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se cree que la victoria ... por un remate inteligente en la red.'::text,'fue decidida'::text,'decidir'::text,'decidiendo'::text,'Se cree que la victoria fue decidida por un remate inteligente en la red.'::text),
(402854,44762,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On pense que la victoire ... par un smash astucieux au filet.'::text,'a été décidée'::text,'décider'::text,'décidant'::text,'On pense que la victoire a été décidée par un smash astucieux au filet.'::text),
(402857,44762,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Galibiyetin filedeki zekice bir smaçla ... düşünülüyor.'::text,'belirlendiği'::text,'belirlemek'::text,'belirlerken'::text,'Galibiyetin filedeki zekice bir smaçla belirlendiği düşünülüyor.'::text),
(402858,44762,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy vélik, hogy a győzelmet egyetlen okos leütés ... el a hálónál.'::text,'döntötte'::text,'dönteni'::text,'döntve'::text,'Úgy vélik, hogy a győzelmet egyetlen okos leütés döntötte el a hálónál.'::text),
(402870,44764,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ohne diesen Hechtsprung ... sie den Sieg verlieren können! Eine komplette Katastrophe!'::text,'hätten'::text,'mussten'::text,'sollten'::text,'Ohne diesen Hechtsprung hätten sie den Sieg verlieren können! Eine komplette Katastrophe!'::text),
(402874,44764,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Без того стрибка вони ... втратити перемогу! Повна катастрофа!'::text,'могли'::text,'мусили'::text,'мали б'::text,'Без того стрибка вони могли втратити перемогу! Повна катастрофа!'::text),
(402873,44764,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Sin esa estirada, ... perdido la victoria! ¡Un desastre total!'::text,'podrían haber'::text,'deben de haber'::text,'deberían'::text,'¡Sin esa estirada, podrían haber perdido la victoria! ¡Un desastre total!'::text),
(402872,44764,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sans ce plongeon, ils ... perdu la victoire ! Un désastre complet !'::text,'auraient pu'::text,'ont dû'::text,'devraient'::text,'Sans ce plongeon, ils auraient pu perdu la victoire ! Un désastre complet !'::text),
(402875,44764,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O atlayış olmasa galibiyeti ...! Tam bir felaket!'::text,'kaybedebilirlerdi'::text,'kaybetmiş olmalılar'::text,'kaybetmeliler'::text,'O atlayış olmasa galibiyeti kaybedebilirlerdi! Tam bir felaket!'::text),
(402876,44764,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Anélkül a vetődés nélkül ... a győzelmet! Teljes katasztrófa!'::text,'elveszíthették volna'::text,'biztosan elveszítették'::text,'el kellene veszíteniük'::text,'Anélkül a vetődés nélkül elveszíthették volna a győzelmet! Teljes katasztrófa!'::text),
(402879,44765,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... des Sommers gehörte absolut ihnen!'::text,'Der größte Sieg'::text,'Ein größter Sieg'::text,'Größter Sieg'::text,'Der größte Sieg des Sommers gehörte absolut ihnen!'::text),
(402883,44765,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... літа була повністю їхньою!'::text,'Найбільша перемога'::text,'Найбільша перемога'::text,'Найбільша перемога'::text,'Найбільша перемога літа була повністю їхньою!'::text),
(402882,44765,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... del verano fue totalmente suya!'::text,'La mayor victoria'::text,'Una mayor victoria'::text,'Mayor victoria'::text,'¡La mayor victoria del verano fue totalmente suya!'::text),
(402881,44765,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... de l''été était totalement à eux !'::text,'La plus grande victoire'::text,'Une plus grande victoire'::text,'Plus grande victoire'::text,'La plus grande victoire de l''été était totalement à eux !'::text),
(402884,44765,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yazın ... tamamen onlarındı!'::text,'en büyük galibiyeti'::text,'en büyük galibiyeti'::text,'en büyük galibiyeti'::text,'Yazın en büyük galibiyeti tamamen onlarındı!'::text),
(402885,44765,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ezen a nyáron teljesen az övék volt!'::text,'A legnagyobb győzelem'::text,'Egy legnagyobb győzelem'::text,'Legnagyobb győzelem'::text,'A legnagyobb győzelem ezen a nyáron teljesen az övék volt!'::text),
(395769,43975,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, angeblich ... sie gerade Papiere, als ihr Chef reinkam.'::text,'zerriss'::text,'zerriss'::text,'hat zerrissen'::text,'Hör zu, angeblich zerriss sie gerade Papiere, als ihr Chef reinkam.'::text),
(395773,43975,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, вона ... папери, коли зайшов її бос.'::text,'рвала'::text,'порвала'::text,'порвала'::text,'Слухай, кажуть, вона рвала папери, коли зайшов її бос.'::text),
(395772,43975,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer ... papeles cuando entró su jefe.'::text,'estaba rompiendo'::text,'rompió'::text,'ha roto'::text,'Oye, al parecer estaba rompiendo papeles cuando entró su jefe.'::text),
(395771,43975,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment elle ... des papiers quand son boss est entré.'::text,'déchirait'::text,'a déchiré'::text,'a déchiré'::text,'Écoute, apparemment elle déchirait des papiers quand son boss est entré.'::text),
(395774,43975,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, güya patronu içeri girdiğinde kâğıtları ...'::text,'yırtıyormuş'::text,'yırtmış'::text,'yırtmış'::text,'Dinle, güya patronu içeri girdiğinde kâğıtları yırtıyormuş.'::text),
(395775,43975,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag éppen ... a papírokat, amikor bejött a főnöke.'::text,'tépte'::text,'széttépte'::text,'széttépte'::text,'Figyelj, állítólag éppen tépte a papírokat, amikor bejött a főnöke.'::text),
(395787,43977,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Selten ... jemanden mitten in einer Besprechung einen Vertrag zerreißen sehen.'::text,'haben sie'::text,'sie haben'::text,'sahen sie'::text,'Selten haben sie jemanden mitten in einer Besprechung einen Vertrag zerreißen sehen.'::text),
(395791,43977,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Рідко ..., щоб хтось рвав контракт посеред наради.'::text,'вони бачили'::text,'вони бачили'::text,'вони бачили'::text,'Рідко вони бачили, щоб хтось рвав контракт посеред наради.'::text),
(395790,43977,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pocas veces ... a alguien romper un contrato en mitad de una reunión.'::text,'han visto'::text,'han visto'::text,'vieron'::text,'Pocas veces han visto a alguien romper un contrato en mitad de una reunión.'::text),
(395789,43977,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rarement ... quelqu''un déchirer un contrat en pleine réunion.'::text,'ont-ils vu'::text,'ils ont vu'::text,'ils virent'::text,'Rarement ont-ils vu quelqu''un déchirer un contrat en pleine réunion.'::text),
(395792,43977,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toplantının ortasında birinin sözleşme yırttığını nadiren ...'::text,'görmüşlerdir'::text,'görmüşlerdir'::text,'gördüler'::text,'Toplantının ortasında birinin sözleşme yırttığını nadiren görmüşlerdir.'::text),
(395793,43977,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ritkán ..., hogy valaki egy megbeszélés közepén széttépjen egy szerződést.'::text,'láttak'::text,'láttak'::text,'láttak'::text,'Ritkán láttak, hogy valaki egy megbeszélés közepén széttépjen egy szerződést.'::text),
(395796,43978,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Offensichtlich eine tolle Besprechung: Sie ließ den Vertrag in Stücke ...'::text,'reißen'::text,'reißen'::text,'reißend'::text,'Offensichtlich eine tolle Besprechung: Sie ließ den Vertrag in Stücke reißen.'::text),
(395800,43978,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Очевидно, чудова нарада: вона звеліла ... контракт на шматки.'::text,'порвати'::text,'порвати'::text,'рвучи'::text,'Очевидно, чудова нарада: вона звеліла порвати контракт на шматки.'::text),
(395799,43978,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Obviamente una reunión genial: hizo ... el contrato en pedazos.'::text,'romper'::text,'romper'::text,'rompiendo'::text,'Obviamente una reunión genial: hizo romper el contrato en pedazos.'::text),
(395798,43978,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Visiblement une super réunion : elle a fait ... le contrat en morceaux.'::text,'déchirer'::text,'déchirer'::text,'déchirant'::text,'Visiblement une super réunion : elle a fait déchirer le contrat en morceaux.'::text),
(395801,43978,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki harika bir toplantı: sözleşmeyi paramparça ...'::text,'yırttırdı'::text,'yırttırdı'::text,'yırtarak'::text,'Belli ki harika bir toplantı: sözleşmeyi paramparça yırttırdı.'::text),
(395802,43978,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván szuper megbeszélés: darabokra ... a szerződést.'::text,'tépette'::text,'tépette'::text,'tépve'::text,'Nyilván szuper megbeszélés: darabokra tépette a szerződést.'::text),
(395805,43979,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Männer wünschten, sie ... den Vertrag nicht in zwei Hälften gerissen.'::text,'hätte'::text,'hat'::text,'würde'::text,'Die Männer wünschten, sie hätte den Vertrag nicht in zwei Hälften gerissen.'::text),
(395809,43979,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловіки шкодують, що вона ... контракт навпіл.'::text,'порвала'::text,'рве'::text,'порве'::text,'Чоловіки шкодують, що вона порвала контракт навпіл.'::text),
(395808,43979,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los hombres desearían que no ... el contrato por la mitad.'::text,'hubiera roto'::text,'rompiera'::text,'rompiera'::text,'Los hombres desearían que no hubiera roto el contrato por la mitad.'::text),
(395807,43979,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les hommes aimeraient qu''elle ... le contrat en deux.'::text,'n''ait pas déchiré'::text,'ne déchire pas'::text,'ne déchire pas'::text,'Les hommes aimeraient qu''elle n''ait pas déchiré le contrat en deux.'::text),
(395810,43979,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adamlar keşke sözleşmeyi ikiye ... diyor.'::text,'yırtmasaydı'::text,'yırtmasa'::text,'yırtmasa'::text,'Adamlar keşke sözleşmeyi ikiye yırtmasaydı diyor.'::text),
(395811,43979,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfiak azt szeretnék, bárcsak ne ... ketté a szerződést.'::text,'tépte volna'::text,'tépné'::text,'tépné'::text,'A férfiak azt szeretnék, bárcsak ne tépte volna ketté a szerződést.'::text),
(395814,43980,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Vertrag, ... sie in zwei Hälften riss, liegt in Stücken auf dem Tisch.'::text,'den'::text,'dessen'::text,'der'::text,'Der Vertrag, den sie in zwei Hälften riss, liegt in Stücken auf dem Tisch.'::text),
(395818,43980,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Контракт, ... вона порвала навпіл, лежить шматками на столі.'::text,'який'::text,'чий'::text,'хто'::text,'Контракт, який вона порвала навпіл, лежить шматками на столі.'::text),
(395817,43980,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El contrato, ... rompió por la mitad, está hecho pedazos sobre la mesa.'::text,'que'::text,'cuyo'::text,'quien'::text,'El contrato, que rompió por la mitad, está hecho pedazos sobre la mesa.'::text),
(395816,43980,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le contrat, ... la femme a déchiré en deux, gît en morceaux sur la table.'::text,'que'::text,'dont'::text,'qui'::text,'Le contrat, que la femme a déchiré en deux, gît en morceaux sur la table.'::text),
(395819,43980,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İkiye ... sözleşme masada paramparça duruyor.'::text,'yırttığı'::text,'yırttığı'::text,'yırttığı'::text,'İkiye yırttığı sözleşme masada paramparça duruyor.'::text),
(395820,43980,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szerződés, ... kettétépett, darabokban hever az asztalon.'::text,'amelyet'::text,'akinek'::text,'aki'::text,'A szerződés, amelyet kettétépett, darabokban hever az asztalon.'::text),
(395823,43981,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie zerriss den Vertrag, ... die Männer ihr zusahen.'::text,'obwohl'::text,'trotz'::text,'wegen'::text,'Sie zerriss den Vertrag, obwohl die Männer ihr zusahen.'::text),
(395827,43981,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона порвала контракт, ... чоловіки дивилися на неї.'::text,'хоча'::text,'попри'::text,'через'::text,'Вона порвала контракт, хоча чоловіки дивилися на неї.'::text),
(395826,43981,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rompió el contrato ... los hombres la estaban mirando.'::text,'aunque'::text,'a pesar de'::text,'debido a'::text,'Rompió el contrato aunque los hombres la estaban mirando.'::text),
(395825,43981,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a déchiré le contrat ... les hommes la regardaient.'::text,'alors que'::text,'malgré'::text,'en raison de'::text,'Elle a déchiré le contrat alors que les hommes la regardaient.'::text),
(395828,43981,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adamlar onu izliyor ... sözleşmeyi yırttı.'::text,'olmasına rağmen'::text,'rağmen'::text,'yüzünden'::text,'Adamlar onu izliyor olmasına rağmen sözleşmeyi yırttı.'::text),
(395829,43981,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Széttépte a szerződést, ... a férfiak nézték.'::text,'pedig'::text,'annak ellenére'::text,'miatt'::text,'Széttépte a szerződést, pedig a férfiak nézték.'::text),
(395832,43982,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Männer wussten, dass sie jede einzelne Seite ...! Totales Chaos!'::text,'zerreißen würde'::text,'zerreißen wird'::text,'gerade zerreißt'::text,'Die Männer wussten, dass sie jede einzelne Seite zerreißen würde! Totales Chaos!'::text),
(395836,43982,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловіки знали, що вона ... кожну сторінку! Повний хаос!'::text,'порве'::text,'порве'::text,'рве'::text,'Чоловіки знали, що вона порве кожну сторінку! Повний хаос!'::text),
(395835,43982,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Los hombres sabían que ... cada una de las páginas! ¡Caos total!'::text,'rompería'::text,'romperá'::text,'está rompiendo'::text,'¡Los hombres sabían que rompería cada una de las páginas! ¡Caos total!'::text),
(395834,43982,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les hommes savaient qu''elle ... chaque page ! Chaos total !'::text,'déchirerait'::text,'déchirera'::text,'déchire'::text,'Les hommes savaient qu''elle déchirerait chaque page ! Chaos total !'::text),
(395837,43982,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adamlar onun her bir sayfayı ... biliyordu! Tam bir kaos!'::text,'yırtacağını'::text,'yırtacağını'::text,'yırttığını'::text,'Adamlar onun her bir sayfayı yırtacağını biliyordu! Tam bir kaos!'::text),
(395838,43982,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfiak tudták, hogy ... minden egyes oldalt! Totális káosz!'::text,'széttépi'::text,'szét fogja tépni'::text,'épp tépi'::text,'A férfiak tudták, hogy széttépi minden egyes oldalt! Totális káosz!'::text),
(395841,43983,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade jetzt ... sie jede Seite auseinander! Dieser Deal ist absolut tot!'::text,'reißt'::text,'reißt'::text,'hat gerissen'::text,'Gerade jetzt reißt sie jede Seite auseinander! Dieser Deal ist absolut tot!'::text),
(395845,43983,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Прямо зараз вона ... кожну сторінку! Ця угода остаточно мертва!'::text,'рве'::text,'рве'::text,'порвала'::text,'Прямо зараз вона рве кожну сторінку! Ця угода остаточно мертва!'::text),
(395844,43983,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ahora mismo ... cada página! ¡Este trato está completamente muerto!'::text,'está rompiendo'::text,'rompe'::text,'ha roto'::text,'¡Ahora mismo está rompiendo cada página! ¡Este trato está completamente muerto!'::text),
(395843,43983,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment même, elle ... chaque page ! Ce deal est complètement mort !'::text,'déchire'::text,'déchire'::text,'a déchiré'::text,'En ce moment même, elle déchire chaque page ! Ce deal est complètement mort !'::text),
(395846,43983,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda her sayfayı ...! Bu anlaşma tamamen öldü!'::text,'yırtıyor'::text,'yırtıyor'::text,'yırttı'::text,'Şu anda her sayfayı yırtıyor! Bu anlaşma tamamen öldü!'::text),
(395847,43983,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most ... szét minden oldalt! Ez az üzlet teljesen halott!'::text,'tépi'::text,'tépi'::text,'tépte'::text,'Épp most tépi szét minden oldalt! Ez az üzlet teljesen halott!'::text),
(395859,43985,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, ich hab gehört, bis Freitag wird sie jeden Vertrag in dem Büro ...'::text,'zerrissen haben'::text,'zerreißen'::text,'zerreißt'::text,'Hör zu, ich hab gehört, bis Freitag wird sie jeden Vertrag in dem Büro zerrissen haben.'::text),
(395863,43985,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що до п''ятниці вона ... кожен контракт у тому офісі.'::text,'порве'::text,'порве'::text,'рве'::text,'Слухай, я чула, що до п''ятниці вона порве кожен контракт у тому офісі.'::text),
(395862,43985,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, he oído que para el viernes ... todos los contratos de esa oficina.'::text,'habrá roto'::text,'romperá'::text,'rompe'::text,'Oye, he oído que para el viernes habrá roto todos los contratos de esa oficina.'::text),
(395861,43985,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il paraît que d''ici vendredi, elle ... tous les contrats de ce bureau.'::text,'aura déchiré'::text,'déchirera'::text,'déchire'::text,'Écoute, il paraît que d''ici vendredi, elle aura déchiré tous les contrats de ce bureau.'::text),
(395864,43985,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duyduğuma göre cumaya kadar o ofisteki her sözleşmeyi ...'::text,'yırtmış olacakmış'::text,'yırtacakmış'::text,'yırtıyormuş'::text,'Dinle, duyduğuma göre cumaya kadar o ofisteki her sözleşmeyi yırtmış olacakmış.'::text),
(395865,43985,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy péntekre ... az összes szerződést abban az irodában.'::text,'széttépi majd'::text,'széttépi'::text,'tépi'::text,'Figyelj, azt hallottam, hogy péntekre széttépi majd az összes szerződést abban az irodában.'::text),
(389379,43265,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine leichte Komödie, offensichtlich: Sie ... in ihrem Kummer sechs Taschentücher verbraucht.'::text,'haben'::text,'haben'::text,'verbrauchen'::text,'Eine leichte Komödie, offensichtlich: Sie haben in ihrem Kummer sechs Taschentücher verbraucht.'::text),
(389383,43265,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Легка комедія, очевидно: вони ... шість серветок у своєму смутку.'::text,'витратили'::text,'витрачають'::text,'витрачають'::text,'Легка комедія, очевидно: вони витратили шість серветок у своєму смутку.'::text),
(389382,43265,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una comedia ligera, obviamente: ... seis pañuelos en su tristeza.'::text,'han gastado'::text,'han estado gastando'::text,'gastan'::text,'Una comedia ligera, obviamente: han gastado seis pañuelos en su tristeza.'::text),
(389381,43265,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une comédie légère, évidemment : ils ... six mouchoirs dans leur chagrin.'::text,'ont utilisé'::text,'utilisent'::text,'utilisent'::text,'Une comédie légère, évidemment : ils ont utilisé six mouchoirs dans leur chagrin.'::text),
(389384,43265,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hafif bir komedi, belli ki: kederleri içinde altı mendil ...'::text,'harcadılar'::text,'harcıyorlar'::text,'harcıyorlar'::text,'Hafif bir komedi, belli ki: kederleri içinde altı mendil harcadılar.'::text),
(389385,43265,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Könnyed vígjáték, nyilván: bánatukban hat zsebkendőt ...'::text,'használtak el'::text,'használnak'::text,'használnak'::text,'Könnyed vígjáték, nyilván: bánatukban hat zsebkendőt használtak el.'::text),
(389388,43266,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Offensichtlich ein Happy End: Ihr Kummer ... schon angefangen, bevor der Film überhaupt vorbei war.'::text,'hatte'::text,'hat'::text,'fängt'::text,'Offensichtlich ein Happy End: Ihr Kummer hatte schon angefangen, bevor der Film überhaupt vorbei war.'::text),
(389392,43266,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Очевидно, щасливий кінець: їхній смуток ... ще до того, як фільм узагалі закінчився.'::text,'почався'::text,'почався'::text,'починається'::text,'Очевидно, щасливий кінець: їхній смуток почався ще до того, як фільм узагалі закінчився.'::text),
(389391,43266,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Obviamente, un final feliz: su tristeza ... antes de que la película terminara siquiera.'::text,'había empezado'::text,'ha empezado'::text,'empieza'::text,'Obviamente, un final feliz: su tristeza había empezado antes de que la película terminara siquiera.'::text),
(389390,43266,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Visiblement une fin heureuse : leur chagrin ... avant même la fin du film.'::text,'avait commencé'::text,'a commencé'::text,'commence'::text,'Visiblement une fin heureuse : leur chagrin avait commencé avant même la fin du film.'::text),
(389393,43266,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki mutlu son: kederleri film daha bitmeden ...'::text,'başlamıştı'::text,'başladı'::text,'başlıyor'::text,'Belli ki mutlu son: kederleri film daha bitmeden başlamıştı.'::text),
(389394,43266,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván happy end: a bánatuk már azelőtt ..., hogy a film egyáltalán véget ért volna.'::text,'elkezdődött'::text,'elkezdődött'::text,'kezdődik'::text,'Nyilván happy end: a bánatuk már azelőtt elkezdődött, hogy a film egyáltalán véget ért volna.'::text),
(389397,43267,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Film schlecht endet, ... ihr Kummer noch tiefer.'::text,'wird'::text,'würde'::text,'wurde'::text,'Wenn der Film schlecht endet, wird ihr Kummer noch tiefer.'::text),
(389401,43267,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо фільм закінчиться погано, їхній смуток ... ще глибшим.'::text,'стане'::text,'став би'::text,'став'::text,'Якщо фільм закінчиться погано, їхній смуток стане ще глибшим.'::text),
(389400,43267,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la película acaba mal, su tristeza se ... aún más profunda.'::text,'hará'::text,'haría'::text,'hizo'::text,'Si la película acaba mal, su tristeza se hará aún más profunda.'::text),
(389399,43267,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le film finit mal, leur chagrin ... encore plus profond.'::text,'deviendra'::text,'deviendrait'::text,'est devenu'::text,'Si le film finit mal, leur chagrin deviendra encore plus profond.'::text),
(389402,43267,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Film kötü biterse kederleri daha da ...'::text,'derinleşecek'::text,'derinleşirdi'::text,'derinleşti'::text,'Film kötü biterse kederleri daha da derinleşecek.'::text),
(389403,43267,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a film rosszul végződik, a bánatuk még mélyebb ...'::text,'lesz'::text,'lenne'::text,'lett'::text,'Ha a film rosszul végződik, a bánatuk még mélyebb lesz.'::text),
(389406,43268,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Geschichte glücklich enden würde, ... ihr Kummer weg.'::text,'ginge'::text,'geht'::text,'geht'::text,'Wenn die Geschichte glücklich enden würde, ginge ihr Kummer weg.'::text),
(389410,43268,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби історія закінчилася щасливо, їхній смуток ...'::text,'минув би'::text,'мине'::text,'минає'::text,'Якби історія закінчилася щасливо, їхній смуток минув би.'::text),
(389409,43268,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la historia acabara bien, su tristeza ...'::text,'desaparecería'::text,'desaparecerá'::text,'desaparece'::text,'Si la historia acabara bien, su tristeza desaparecería.'::text),
(389408,43268,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''histoire finissait bien, leur chagrin ...'::text,'s''en irait'::text,'s''en ira'::text,'s''en va'::text,'Si l''histoire finissait bien, leur chagrin s''en irait.'::text),
(389411,43268,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hikâye mutlu bitseydi, kederleri ...'::text,'geçerdi'::text,'geçecek'::text,'geçiyor'::text,'Hikâye mutlu bitseydi, kederleri geçerdi.'::text),
(389412,43268,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a történet boldogan végződne, a bánatuk ...'::text,'elmúlna'::text,'el fog múlni'::text,'elmúlik'::text,'Ha a történet boldogan végződne, a bánatuk elmúlna.'::text),
(389415,43269,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr Kummer ... durch das traurige Ende des Films ausgelöst.'::text,'wurde'::text,'wird'::text,'löste'::text,'Ihr Kummer wurde durch das traurige Ende des Films ausgelöst.'::text),
(389419,43269,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Їхній смуток ... сумним фіналом фільму.'::text,'був спричинений'::text,'спричиняється'::text,'спричинив'::text,'Їхній смуток був спричинений сумним фіналом фільму.'::text),
(389418,43269,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su tristeza ... por el triste final de la película.'::text,'fue causada'::text,'es causada'::text,'causó'::text,'Su tristeza fue causada por el triste final de la película.'::text),
(389417,43269,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Leur chagrin ... par la triste fin du film.'::text,'a été causé'::text,'est causé'::text,'a causé'::text,'Leur chagrin a été causé par la triste fin du film.'::text),
(389420,43269,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kederleri filmin hüzünlü sonu tarafından ...'::text,'yaratıldı'::text,'yaratılıyor'::text,'yarattı'::text,'Kederleri filmin hüzünlü sonu tarafından yaratıldı.'::text),
(389421,43269,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A bánatukat a film szomorú vége ...'::text,'okozta'::text,'okozza'::text,'okozta'::text,'A bánatukat a film szomorú vége okozta.'::text),
(389424,43270,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Film ... sie in totalen Kummer! Davon erholen sie sich nie!'::text,'stürzte'::text,'wurde gestürzt'::text,'stürzend'::text,'Der Film stürzte sie in totalen Kummer! Davon erholen sie sich nie!'::text),
(389428,43270,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Фільм ... їх у повний смуток! Вони ніколи не оговтаються!'::text,'кинув'::text,'був кинутий'::text,'кидаючи'::text,'Фільм кинув їх у повний смуток! Вони ніколи не оговтаються!'::text),
(389427,43270,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La película los ... en la tristeza más absoluta! ¡Nunca se recuperarán!'::text,'hundió'::text,'fue hundida'::text,'hundiendo'::text,'¡La película los hundió en la tristeza más absoluta! ¡Nunca se recuperarán!'::text),
(389426,43270,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le film les ... dans un chagrin total ! Ils ne s''en remettront jamais !'::text,'a plongés'::text,'a été plongé'::text,'plongeant'::text,'Le film les a plongés dans un chagrin total ! Ils ne s''en remettront jamais !'::text),
(389429,43270,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Film onları tam bir kederin içine ...! Asla toparlanamayacaklar!'::text,'attı'::text,'atıldı'::text,'atarak'::text,'Film onları tam bir kederin içine attı! Asla toparlanamayacaklar!'::text),
(389430,43270,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A film teljes bánatba ... őket! Soha nem fogják kiheverni!'::text,'taszította'::text,'taszíttatott'::text,'taszítva'::text,'A film teljes bánatba taszította őket! Soha nem fogják kiheverni!'::text),
(389433,43271,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, angeblich ... das ein trauriger Film sein, weil ihr Kummer riesig ist.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Girl, angeblich muss das ein trauriger Film sein, weil ihr Kummer riesig ist.'::text),
(389437,43271,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, це ... бути сумний фільм, бо їхній смуток величезний.'::text,'мусить'::text,'не може'::text,'мав би'::text,'Подруго, кажуть, це мусить бути сумний фільм, бо їхній смуток величезний.'::text),
(389436,43271,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer ... ser una peli triste, porque su tristeza es enorme.'::text,'debe de'::text,'no puede'::text,'debería'::text,'Tía, al parecer debe de ser una peli triste, porque su tristeza es enorme.'::text),
(389435,43271,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment ça ... être un film triste, parce que leur chagrin est énorme.'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'Meuf, apparemment ça doit être un film triste, parce que leur chagrin est énorme.'::text),
(389438,43271,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, güya hüzünlü bir film ..., çünkü kederleri çok büyük.'::text,'olmalı'::text,'olamaz'::text,'olmalı'::text,'Kızım, güya hüzünlü bir film olmalı, çünkü kederleri çok büyük.'::text),
(389439,43271,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag ... szomorú film, mert hatalmas a bánatuk.'::text,'biztos'::text,'nem lehet'::text,'elvileg'::text,'Csajszi, állítólag biztos szomorú film, mert hatalmas a bánatuk.'::text),
(389442,43272,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, ich hab gehört, der Film, ... den ganzen Kummer ausgelöst hat, hat ein trauriges Ende.'::text,'der'::text,'wer'::text,'wo'::text,'Hör zu, ich hab gehört, der Film, der den ganzen Kummer ausgelöst hat, hat ein trauriges Ende.'::text),
(389446,43272,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що фільм, ... спричинив увесь цей смуток, має сумний фінал.'::text,'який'::text,'хто'::text,'де'::text,'Слухай, я чула, що фільм, який спричинив увесь цей смуток, має сумний фінал.'::text),
(389445,43272,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, he oído que la peli ... causó toda esa tristeza tiene un final triste.'::text,'que'::text,'quien'::text,'donde'::text,'Oye, he oído que la peli que causó toda esa tristeza tiene un final triste.'::text),
(389444,43272,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il paraît que le film ... a causé tout ce chagrin a une fin triste.'::text,'qui'::text,'qui'::text,'où'::text,'Écoute, il paraît que le film qui a causé tout ce chagrin a une fin triste.'::text),
(389447,43272,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duyduğuma göre bütün o kedere ... filmin hüzünlü bir sonu varmış.'::text,'neden olan'::text,'neden olan'::text,'neden olan'::text,'Dinle, duyduğuma göre bütün o kedere neden olan filmin hüzünlü bir sonu varmış.'::text),
(389448,43272,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy a film, ... ezt az egész bánatot okozta, szomorú véget ér.'::text,'amely'::text,'aki'::text,'ahol'::text,'Figyelj, azt hallottam, hogy a film, amely ezt az egész bánatot okozta, szomorú véget ér.'::text),
(389451,43273,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, sie hat mir erzählt, dass ihr Kummer die ganze Nacht ...'::text,'gedauert hatte'::text,'gedauert hat'::text,'dauert'::text,'Bestie, sie hat mir erzählt, dass ihr Kummer die ganze Nacht gedauert hatte.'::text),
(389455,43273,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, вона сказала мені, що їхній смуток ... всю ніч.'::text,'тривав'::text,'тривав'::text,'триває'::text,'Подруго, вона сказала мені, що їхній смуток тривав всю ніч.'::text),
(389454,43273,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, me dijo que su tristeza ... toda la noche.'::text,'había durado'::text,'ha durado'::text,'dura'::text,'Amiga, me dijo que su tristeza había durado toda la noche.'::text),
(389453,43273,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, elle m''a dit que leur chagrin ... toute la nuit.'::text,'avait duré'::text,'a duré'::text,'dure'::text,'Ma belle, elle m''a dit que leur chagrin avait duré toute la nuit.'::text),
(389456,43273,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bana kederlerinin bütün gece ... söyledi.'::text,'sürdüğünü'::text,'sürdüğünü'::text,'sürdüğünü'::text,'Kanka, bana kederlerinin bütün gece sürdüğünü söyledi.'::text),
(389457,43273,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, hogy a bánatuk egész éjjel ...'::text,'tartott'::text,'tartott'::text,'tart'::text,'Csajszi, azt mondta, hogy a bánatuk egész éjjel tartott.'::text)
) v(id, eid, lang, n_intro_text, n_correct_answer, n_distractor_1, n_distractor_2, n_full_sentence, o_intro_text, o_correct_answer, o_distractor_1, o_distractor_2, o_full_sentence)
